INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C1','kor',3,2,'u1',2,'경험을 떠올리는 틀 — 글을 읽고 떠오른 일을 언제·어디에서·무엇을·누구와, 본 것과 들은 것, 그때 든 마음으로 또렷하게 떠올리기(정확한 시각·물건값 같은 것은 필요 없음)',ARRAY['[4국05-02][4국05-05]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C2','kor',3,2,'u1',2,'마음이 이어지는 경험 — 작품과 똑같은 일을 겪지 않았어도 그때 든 생각이나 느낌이 이어지면 알맞게 떠올린 경험이고, 창문·국·휴지처럼 겉에 나온 물건이나 사건이 같다고 이어지는 것이 아님',ARRAY['[4국05-02][4국05-05]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C3','kor',3,2,'u1',2,'시의 내용과 말하는 이의 마음 — 시에서 말하는 이가 겪는 일을 알고, 마음은 시에 그대로 적혀 있지 않으므로 시에 나온 말과 행동(닦아도 또 썼다 · 지우개를 굴렸다)을 근거로 짐작하기',ARRAY['[4국05-02][4국05-05]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C4','kor',3,2,'u1',2,'인상 깊은 부분 견주기와 시 바꾸어 쓰기 — 마음에 남는 줄은 겪은 일과 생각에 따라 사람마다 달라 정답이 없고, 친구와 다를 때는 까닭을 물어 견주며, 시의 한 줄을 내 경험으로 바꿀 때는 뒤에 오는 줄과 이어지게 바꾸기',ARRAY['[4국05-02][4국05-05]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C5','kor',3,2,'u1',4,'이야기의 내용과 낱말 — 「나중에 온 아이」에서 인물이 겪은 일과 까닭을 글에서 찾고, 낱말의 뜻(선뜻 · 기웃거리다 · 멋쩍다)을 그 낱말이 나온 앞뒤 줄로 알기',ARRAY['[4국05-02][4국05-05]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C6','kor',3,2,'u1',4,'근거 있는 짐작 — 인물의 마음 짐작은 사람마다 달라도 되지만, 이야기에 나온 상황·말·행동에서 근거를 댈 수 있어야 하고, 글에 없는 것(원래 청소를 좋아한다 등)을 지어내지 않기; 말이 없는 인물은 행동으로 짐작하기',ARRAY['[4국05-02][4국05-05]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C7','kor',3,2,'u1',4,'인물의 마음과 내 경험 잇기, 하고 싶은 말 — 인물이 겪은 일과 마음을 찾아 그 마음과 이어지는 내 경험을 떠올리고(국·휴지 같은 겉 사건이 아니라 망설이던 마음), 인물에게 하고 싶은 말은 가르치는 말이나 인물 탓이 아니라 인물이 한 말·행동을 짚어 마음을 알아주는 말로 하며, 이야기를 권할 때는 그 친구의 어떤 일과 이어질지 까닭을 대기',ARRAY['[4국05-02][4국05-05]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C8','kor',3,2,'u1',6,'간추리며 듣는 세 걸음 — 듣기 전(무엇을 알려고 듣는지 정하기·제목으로 예상하기·아는 것 떠올리기) → 듣는 중(첫째·둘째·이것은·따라서·가장 중요한 것은 같은 말에 귀를 세우고 간단히 적기) → 들은 후(번호·화살표 같은 기호로 나누어 정리하고 궁금한 것 적기)',ARRAY['[4국01-01]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C9','kor',3,2,'u1',6,'질문과 대답으로 간추리기 — 묻고 답하는 말을 들을 때 질문과 대답을 짝지어 적으면 그 표가 곧 간추린 것이 되고, 들은 말을 하나도 빠뜨리지 않고 받아 적는 것은 간추리기가 아님',ARRAY['[4국01-01]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C10','kor',3,2,'u1',7,'이야기를 간추리는 방법 — 인물의 특성·일이 일어난 차례·원인과 결과를 잡아 이야기의 뼈대를 남기고, 본문을 그대로 옮기거나 재미있던 부분만 남기지 않기(재미있는 것 ≠ 중요한 것), 간추린 것이 한 편으로 읽히는지 살피기',ARRAY['[4국01-01]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C11','kor',3,2,'u1',9,'목적에 맞게 간추려 글로 정리하기 — 듣기 전에 무엇을 하려고 듣는지 정하고, 있는 곳·자랑거리·좋은 점 같은 칸으로 나누어 빠진 것을 찾으며, 목적이 다르면 남길 것도 달라 간추리기에는 하나의 정답이 없으니 서로 다를 때는 목적부터 물어보기',ARRAY['[4국01-01]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C12','kor',3,2,'u1',11,'배운 내용 실천하기 — 내 경험에 어울리는 이야기는 유명하거나 긴 것이 아니라 겪은 일이나 마음이 이어지는 것으로 고르고, 안내를 듣고 표지어 뒤의 중요한 것만 간추려 내가 할 수 있는 한 가지를 언제·무엇을이 드러나게 다짐하기',ARRAY['[4국01-01]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C13','kor',3,2,'u1',11,'받침 ㅎ이 소리 나지 않는 경우 — 받침 ㅎ 뒤에 모음으로 시작하는 말이 오면 ㅎ 소리가 나지 않고(빻아[빠아] · 찧어[찌어]) 자음이 오면 그렇지 않으며(빻고 · 찧다), 소리만 사라질 뿐 쓸 때는 받침 ㅎ을 그대로 쓰기(기초 다지기)',ARRAY['4국04 문법(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C14','kor',3,2,'u1',11,'낱말을 묶는 이름 — 여러 낱말을 한 이름으로 묶을 수 있고(피리·북·장구 → 악기), 묶어 두면 새 낱말을 만나도 어디에 담을지 알 수 있음(기초 다지기)',ARRAY['4국04 문법(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X01','kor',3,'u1',ARRAY['K3-2-u1-C1']::text[],'경험을 떠올릴 때 언제·어디에서·누구와를 빠뜨리거나, 정확한 시각·물건값처럼 필요 없는 것을 떠올린다','남에게 말해 준다면 무엇부터? — 언제·어디·무엇·누구·본 것·마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X02','kor',3,'u1',ARRAY['K3-2-u1-C2','K3-2-u1-C7','K3-2-u1-C12']::text[],'작품과 똑같은 일을 겪었거나 겉에 나온 물건·사건이 같아야 이어지는 경험이라고 여긴다','같은 일이 아니라 같은 마음을 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X03','kor',3,'u1',ARRAY['K3-2-u1-C2']::text[],'작품과 상관없이 아무 일이나 떠올려도 된다고 여긴다','그때 든 마음이 작품과 이어지는가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X04','kor',3,'u1',ARRAY['K3-2-u1-C3','K3-2-u1-C6']::text[],'마음을 짐작할 때 글에 나온 말·행동이 아니라 지금 내 기분·제목·글에 없는 사실을 근거로 댄다','그렇게 짐작한 까닭을 글에서 한 줄 찾아 댈 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X05','kor',3,'u1',ARRAY['K3-2-u1-C4','K3-2-u1-C7']::text[],'인상 깊은 부분에 정답이 있다고 여겨 내 것이 맞다고 우기거나 내 생각을 지우고 친구와 똑같이 고른다','다르면 까닭을 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X06','kor',3,'u1',ARRAY['K3-2-u1-C4']::text[],'시의 한 줄을 바꿀 때 뒤에 오는 줄과 이어지지 않게 바꾼다','바꾼 행동을 하면 친구가 어떻게 될까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X07','kor',3,'u1',ARRAY['K3-2-u1-C3','K3-2-u1-C5','K3-2-u1-C10']::text[],'작품에서 인물(말하는 이)이 겪은 일이나 그렇게 한 까닭을 잘못 읽는다','그 일이 적힌 줄을 다시 찾아 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X08','kor',3,'u1',ARRAY['K3-2-u1-C5']::text[],'낱말의 뜻을 앞뒤 줄을 보지 않고 짐작해 다른 낱말의 뜻과 섞는다','그 낱말이 나온 줄을 앞뒤까지 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X09','kor',3,'u1',ARRAY['K3-2-u1-C7']::text[],'인물에게 하고 싶은 말을 가르치는 말(훈계)이나 인물 탓으로 한다','인물이 한 말·행동을 짚어 마음을 알아주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X10','kor',3,'u1',ARRAY['K3-2-u1-C8','K3-2-u1-C11']::text[],'듣기 전에 무엇을 알려고 듣는지 정하지 않거나, 들을 내용을 미리 다 적어 두려 한다','듣기 전 — 목적 · 제목으로 예상 · 아는 것 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X11','kor',3,'u1',ARRAY['K3-2-u1-C8','K3-2-u1-C12']::text[],'첫째·따라서·가장 중요한 것은 같은 말을 놓치거나, 「음, 그러니까」 같은 군말을 중요한 말로 여긴다','그 말 뒤에 꼭 중요한 내용이 따라오나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X12','kor',3,'u1',ARRAY['K3-2-u1-C9','K3-2-u1-C10','K3-2-u1-C11']::text[],'들은 말이나 본문을 하나도 빠뜨리지 않고 그대로 옮겨 적는 것을 간추리기로 여긴다','간추리기는 줄이기가 아니라 다시 정리하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X13','kor',3,'u1',ARRAY['K3-2-u1-C10','K3-2-u1-C12']::text[],'재미있던 부분이나 말투·장면처럼 눈에 띄는 것을 중요한 내용으로 여긴다','그 일을 빼면 이야기(안내)가 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X14','kor',3,'u1',ARRAY['K3-2-u1-C10']::text[],'이야기를 간추릴 때 일이 일어난 차례를 뒤바꾸거나 왜 그랬는지(원인)를 빠뜨린다','「왜 그랬지?」「그래서?」가 남아 있나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X15','kor',3,'u1',ARRAY['K3-2-u1-C10']::text[],'원인과 결과의 짝을 엇갈리게 잇는다','그 일을 한 다음에 무엇이 돌아왔나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X16','kor',3,'u1',ARRAY['K3-2-u1-C11']::text[],'간추린 것이 서로 다르면 하나가 틀렸다거나 더 많이 적은 쪽이 잘 간추린 것이라고 여긴다','무엇을 하려고 간추렸는지부터 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X17','kor',3,'u1',ARRAY['K3-2-u1-C11','K3-2-u1-C9']::text[],'간추리는 목적과 남길 것을 엇갈리게 짝짓거나 칸(있는 곳·자랑거리·좋은 점)에 맞지 않게 넣는다','그 글을 읽는 사람이 무엇을 할 수 있어야 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X18','kor',3,'u1',ARRAY['K3-2-u1-C12']::text[],'내 경험에 어울리는 이야기를 가장 유명하거나 가장 긴 이야기로 고른다','내 마음과 이어지는 이야기인가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X19','kor',3,'u1',ARRAY['K3-2-u1-C12']::text[],'실천 다짐을 「모두 잘하겠다」처럼 막연하게 쓰거나 남이 지켜야 할 것을 바라는 말로 쓴다','내가 · 언제 · 무엇을 할지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X20','kor',3,'u1',ARRAY['K3-2-u1-C13']::text[],'받침 ㅎ을 모음 앞에서도 소리 내거나, 자음 앞에서도 ㅎ 소리가 사라진다고 여긴다','받침 ㅎ 바로 뒤가 모음인가 자음인가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X21','kor',3,'u1',ARRAY['K3-2-u1-C13']::text[],'소리 나는 대로 받침 ㅎ을 빼고 적는다','소리는 [빠아], 글자는 빻아') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X22','kor',3,'u1',ARRAY['K3-2-u1-C14']::text[],'낱말을 묶는 이름과 그 아래 낱말을 엇갈리게 묶거나 묶는 이름을 아래 낱말로 여긴다','셋을 한마디로 부르면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X23','kor',3,'u1',ARRAY['K3-2-u1-C3']::text[],'시에서 말하는 이를 시를 쓴 사람(시인)으로 여기거나, 사람만 말하는 이가 될 수 있다고 여긴다','말하는 이는 시 속에서 이야기하는 사람 또는 사물 — 시 안에서 「나」가 누구인지 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X24','kor',3,'u1',ARRAY['K3-2-u1-C3','K3-2-u1-C2']::text[],'「맘속에 벽」·「‘입장 바꿔 생각해 보기’란 약」처럼 빗대어 쓴 말을 눈에 보이는 진짜 벽·먹는 약으로 읽는다','벽은 무엇을 막나? 그 특징이 마음의 어떤 모습과 닮았는지 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X25','kor',3,'u1',ARRAY['K3-2-u1-C4']::text[],'시를 바꾸어 쓸 때 뜻이 이어지는 덩어리(의미 단위)가 아닌 곳에서 행을 나누거나 한 행에 몰아 쓴다','소리 내어 읽을 때 자연스럽게 쉬는 곳에서 행을 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X26','kor',3,'u1',ARRAY['K3-2-u1-C5','K3-2-u1-C10']::text[],'글 안에서 바로 답을 찾는 질문(내용 확인), 글의 내용을 바탕으로 생각해야 하는 질문(추론), 내 생각이나 느낌을 말하는 질문(감상)을 가리지 못한다','답이 글에 그대로 있나? 글을 보고 짐작해야 하나? 내 생각을 말해야 하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X27','kor',3,'u1',ARRAY['K3-2-u1-C2','K3-2-u1-C1']::text[],'직접 겪은 일만 경험이라고 여겨, 책이나 영상에서 보고 들은 일(간접 경험)이나 친구의 경험을 듣고 떠오른 일은 떠올리지 못한다','책에서 본 것, 영상에서 본 것, 친구에게 들은 것도 떠올릴 수 있다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X28','kor',3,'u1',ARRAY['K3-2-u1-C7']::text[],'경험 쪽지를 모둠에서 정한 기준(도움을 주었던/받았던 경험 · 혼자 한/함께 한 경험)이 아닌 다른 것(재미, 길이)으로 나누거나 엇갈리게 넣는다','기준 낱말(주었다/받았다 · 혼자/함께)을 쪽지에서 찾아보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_basic#1','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C1',1,'mc','auto','『국어』 34쪽 그림은 물놀이하기 · 찰흙으로 작품 만들기 · 추석에 보름달 보기 · 공연이나 영화 보기예요. 그림과 관련 있는 경험을 떠올릴 때 함께 떠올리면 좋은 것은 무엇인가요?',ARRAY['K3-2-u1-X01']::text[],false,'{"seq":1,"concept":"K3-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 34쪽 그림은 물놀이하기 · 찰흙으로 작품 만들기 · 추석에 보름달 보기 · 공연이나 영화 보기예요. 그림과 관련 있는 경험을 떠올릴 때 함께 떠올리면 좋은 것은 무엇인가요?","options":[{"t":"그때 본 것, 들은 것, 느낀 것","correct":true},{"t":"그날의 정확한 기온","mis":"K3-2-u1-X01"},{"t":"함께 간 사람의 나이","mis":"K3-2-u1-X01"},{"t":"그날 쓴 돈","mis":"K3-2-u1-X01"}],"explanation":["34쪽 날개에 「본 것, 들은 것, 느낀 것을 떠올려 봐요.」라고 했어요.","언제·어디에서·무엇을·누구와도 함께 떠올려요.","기온·나이·돈은 경험을 또렷하게 해 주지 않아요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"추석 밤에 할머니 댁 마당에서 사촌들과 보름달을 보며 소원을 빌었어. 달이 정말 커서 놀랐어."},{"who":"도윤","text":"나는 미술 시간에 교실에서 짝과 찰흙으로 강아지를 만들었어. 손이 끈적했지만 재미있었어."},{"who":"서아","text":"지난여름 바닷가에서 동생과 물놀이를 했어. 파도가 철썩 와서 깜짝 놀랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_basic#2','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C4',1,'mc','auto','『국어활동』 6쪽 「맛있는 소리」에서 「콰륵 콰륵」, 「코로록 칵칵」에 밑줄을 그은 까닭으로 예시 답안과 같은 것은 무엇인가요?',ARRAY['K3-2-u1-X04','K3-2-u1-X05','K3-2-u1-X07']::text[],false,'{"seq":2,"concept":"K3-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어활동』 6쪽 「맛있는 소리」에서 「콰륵 콰륵」, 「코로록 칵칵」에 밑줄을 그은 까닭으로 예시 답안과 같은 것은 무엇인가요?","options":[{"t":"음식 먹는 소리를 다양하게 표현한 점이 재미있어서","correct":true},{"t":"시의 제목이 길어서","mis":"K3-2-u1-X04"},{"t":"누구나 같은 줄에 밑줄을 그어야 해서","mis":"K3-2-u1-X05"},{"t":"과자 이름이 많이 나와서","mis":"K3-2-u1-X07"}],"explanation":["먹는 소리를 흉내 낸 말이에요.","김치·깍두기 먹는 소리를 과자·사탕 소리처럼 나타냈어요.","재미있는 표현은 사람마다 다르게 고를 수 있어요."],"asset":{"type":"passage","lines":["콰륵 콰륵","[간추림] 과자 먹는 소리에 달려가 보면 엄마가 김치 먹는 소리","코로록 칵칵","[간추림] 사탕 깨무는 소리에 달려가 보면 엄마가 깍두기 먹는 소리"],"title":"시 「맛있는 소리」(신민규) — 『국어활동』 6쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_basic#3','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C3',1,'mc','auto','「은행잎 편지」에서 말하는 이는 은행잎을 보고 누구를 떠올렸나요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":1,"kind":"mc","stem":"「은행잎 편지」에서 말하는 이는 은행잎을 보고 누구를 떠올렸나요?","options":[{"t":"방학 때 이사를 가 버린 친구","correct":true},{"t":"은행나무를 심은 할아버지","mis":"K3-2-u1-X07"},{"t":"같은 반 짝꿍","mis":"K3-2-u1-X07"},{"t":"편지를 배달하는 사람","mis":"K3-2-u1-X07"}],"explanation":["1연을 다시 읽어요.","「방학 때 나도 몰래 / 이사 간 친구」예요.","그 친구에게 은행잎 편지를 띄워 보내요."],"asset":{"type":"passage","lines":["방학 때 나도 몰래","이사 간 친구","[간추림] 2~3연 — 떨어진 은행잎에 이야기를 담아 그 친구에게 띄워 보낸다."],"title":"시 「은행잎 편지」(김홍관) 1연 — 『국어』 36쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_basic#4','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C3',1,'ox','auto','시에서 말하는 이는 그 시를 쓴 사람(시인)을 말해요.',ARRAY['K3-2-u1-X23']::text[],false,'{"seq":4,"concept":"K3-2-u1-C3","difficulty":1,"kind":"ox","stem":"시에서 말하는 이는 그 시를 쓴 사람(시인)을 말해요.","answer":"X","reason_options":[{"t":"말하는 이는 시 속에서 이야기하는 사람 또는 사물이기 때문에","correct":true},{"t":"시를 쓴 사람만 시 속에서 말할 수 있기 때문에","mis":"K3-2-u1-X23"}],"mis":"K3-2-u1-X23","explanation":["『국어』 37쪽 날개를 떠올려요.","말하는 이는 시 속에서 이야기하는 사람 또는 사물이에요.","「은행잎 편지」의 말하는 이는 시인이 아니라 친구를 그리워하는 「나」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_basic#5','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C3',2,'mc','auto','「은행잎 편지」에서 말하는 이는 은행잎에 어떤 이야기를 담아 보내고 싶었을까요?',ARRAY['K3-2-u1-X07','K3-2-u1-X04']::text[],false,'{"seq":5,"concept":"K3-2-u1-C3","difficulty":2,"kind":"mc","stem":"「은행잎 편지」에서 말하는 이는 은행잎에 어떤 이야기를 담아 보내고 싶었을까요?","options":[{"t":"갑자기 헤어지게 되어 속상하고 그립다는 말","correct":true},{"t":"은행잎이 노랗게 물들었다는 소식","mis":"K3-2-u1-X07"},{"t":"방학 숙제를 다 했다는 자랑","mis":"K3-2-u1-X04"},{"t":"이사를 가서 잘됐다는 말","mis":"K3-2-u1-X04"}],"explanation":["친구가 「나도 몰래」 이사를 갔어요.","인사도 못 하고 헤어진 마음을 생각해요.","속상하고 그립다는 말을 전하고 싶었을 거예요."],"asset":{"type":"passage","lines":["방학 때 나도 몰래","이사 간 친구","[간추림] 2~3연 — 떨어진 은행잎에 이야기를 담아 그 친구에게 띄워 보낸다."],"title":"시 「은행잎 편지」(김홍관) 1연 — 『국어』 36쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_basic#6','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C3',2,'mc','auto','「은행잎 편지」 6연 「편지 보고 가끔은 / 내 생각 날까?」에서 말하는 이는 어떤 마음이었을까요?',ARRAY['K3-2-u1-X04','K3-2-u1-X07']::text[],false,'{"seq":6,"concept":"K3-2-u1-C3","difficulty":2,"kind":"mc","stem":"「은행잎 편지」 6연 「편지 보고 가끔은 / 내 생각 날까?」에서 말하는 이는 어떤 마음이었을까요?","options":[{"t":"친구도 나를 생각하는지 궁금하고 보고 싶은 마음","correct":true},{"t":"친구에게 화가 난 마음","mis":"K3-2-u1-X04"},{"t":"은행잎을 모으고 싶은 마음","mis":"K3-2-u1-X07"},{"t":"편지 쓰기가 귀찮은 마음","mis":"K3-2-u1-X04"}],"explanation":["「내 생각 날까?」라고 친구에게 묻고 있어요.","친구도 나를 떠올리는지 궁금해해요.","그만큼 친구가 보고 싶은 마음이에요."],"asset":{"type":"passage","lines":["[간추림] 4~5연 — 은행잎이 동동동 흘러가다가 친구가 내 편지를 보지 않을까 생각한다.","편지 보고 가끔은","내 생각 날까?"],"title":"시 「은행잎 편지」 6연 — 『국어』 37쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_basic#7','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C2',2,'mc','auto','「은행잎 편지」와 이어지는 경험으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":7,"concept":"K3-2-u1-C2","difficulty":2,"kind":"mc","stem":"「은행잎 편지」와 이어지는 경험으로 알맞은 것은 무엇인가요?","options":[{"t":"친한 친구와 다른 반이 되어 자주 못 보게 된 일","correct":true},{"t":"가을에 은행잎을 주운 일","mis":"K3-2-u1-X02"},{"t":"편지 봉투를 산 일","mis":"K3-2-u1-X02"},{"t":"어제 저녁에 먹은 반찬","mis":"K3-2-u1-X03"}],"explanation":["은행잎이나 편지가 나오는 일을 찾는 게 아니에요.","누군가와 떨어져 지내 보고 싶던 마음을 찾아요.","겪은 일은 달라도 생각이나 느낌이 비슷하면 돼요."],"asset":{"type":"passage","lines":["방학 때 나도 몰래","이사 간 친구","[간추림] 2~3연 — 떨어진 은행잎에 이야기를 담아 그 친구에게 띄워 보낸다."],"title":"시 「은행잎 편지」(김홍관) 1연 — 『국어』 36쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_basic#8','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C3',2,'match','auto','「벽 부수기」에 나온 말과 그 말이 뜻하는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u1-C3","difficulty":2,"kind":"match","stem":"「벽 부수기」에 나온 말과 그 말이 뜻하는 것을 알맞게 이으세요.","pairs":[{"l":"맘속에 벽","r":"친구와 말도 하기 싫어진 마음"},{"l":"「입장 바꿔 생각해 보기」란 약","r":"마음의 벽을 없애는 방법"},{"l":"‘피식’ 웃음소리","r":"마음의 벽이 부서지는 소리"}],"mis":"K3-2-u1-X24","explanation":["진짜 벽이나 먹는 약이 아니에요.","벽은 사이를 막아요. 그래서 마음이 막힌 모습을 벽에 빗댔어요.","약은 그 마음을 낫게 하는 방법이에요."],"asset":{"type":"passage","lines":["맘속에 벽이 있으면","[간추림] 말도 하고 싶지 않고, 보고 싶지도 않고, 화만 나고 답답하다.","[간추림] 그 벽은 「입장 바꿔 생각해 보기」라는 약을 마음에 풀어 마시면 없어진다."],"title":"시 「벽 부수기」(박희순) 앞부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_basic#9','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C4',2,'ox','auto','「벽 부수기」에서 재미있다고 느낀 부분이 친구와 다르면 둘 중 한 사람은 잘못 읽은 거예요.',ARRAY['K3-2-u1-X05']::text[],false,'{"seq":9,"concept":"K3-2-u1-C4","difficulty":2,"kind":"ox","stem":"「벽 부수기」에서 재미있다고 느낀 부분이 친구와 다르면 둘 중 한 사람은 잘못 읽은 거예요.","answer":"X","reason_options":[{"t":"경험이나 생각이 달라 재미있다고 느끼는 부분도 다르기 때문에","correct":true},{"t":"재미있는 부분은 누구에게나 똑같기 때문에","mis":"K3-2-u1-X05"}],"mis":"K3-2-u1-X05","explanation":["지도서는 재미를 느낀 부분이 다른 까닭을 경험과 생각이 달라서라고 해요.","다르면 까닭을 물어 견주어 봐요.","그래서 X예요."],"asset":{"type":"passage","lines":["[간추림] 그 애 마음을 알 것 같아지면","‘피식’ 웃음소리 나온다","그게 벽 부서지는 소리야."],"title":"시 「벽 부수기」 끝부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_basic#10','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C4',3,'error','auto','「벽 부수기」를 바꾸어 썼어요. 바로 뒤에 오는 「그게 벽 부서지는 소리야.」와 이어지지 않게 바꾼 친구는 누구인가요?',ARRAY['K3-2-u1-X06']::text[],false,'{"seq":10,"concept":"K3-2-u1-C4","difficulty":3,"kind":"error","stem":"「벽 부수기」를 바꾸어 썼어요. 바로 뒤에 오는 「그게 벽 부서지는 소리야.」와 이어지지 않게 바꾼 친구는 누구인가요?","options":[{"t":"친구 다 — 「약을 마셨더니 / 화가 더 나서 문을 쾅 닫았다」","correct":true,"mis_target":"K3-2-u1-X06"},{"t":"친구 가 — 「행복했던 추억이 떠올라 / ‘히힛’ 웃음소리 나온다」","mis":"K3-2-u1-X06"},{"t":"친구 나 — 「같이 놀던 날이 생각나 / ‘풋’ 웃음이 터진다」","mis":"K3-2-u1-X06"}],"explanation":["뒤 줄은 벽이 부서지는 소리예요.","웃음소리가 나와야 그 뒤 줄과 이어져요.","문을 쾅 닫으면 벽이 더 두꺼워지니 친구 다가 잘못 바꾸었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_challenge#1','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C1',2,'sa','auto','『국어』 33쪽 「생각 열기」에서 친구가 「여름 방학에 가족과 갯벌에서 조개를 캤어.」라고 경험을 말했어요. 「누구와」에 해당하는 말을 찾아 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C1","difficulty":2,"kind":"sa","stem":"『국어』 33쪽 「생각 열기」에서 친구가 「여름 방학에 가족과 갯벌에서 조개를 캤어.」라고 경험을 말했어요. 「누구와」에 해당하는 말을 찾아 쓰세요.","answer":["가족과","가족"],"explanation":["언제는 여름 방학, 어디에서는 갯벌이에요.","무엇을은 조개 캐기예요.","누구와는 가족과예요."],"mis":"K3-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_challenge#2','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C1',2,'mc','auto','『국어』 35쪽 2번처럼 친구가 말한 경험을 듣고 정리할 때 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X16','K3-2-u1-X01']::text[],false,'{"seq":2,"concept":"K3-2-u1-C1","difficulty":2,"kind":"mc","stem":"『국어』 35쪽 2번처럼 친구가 말한 경험을 듣고 정리할 때 알맞은 방법은 무엇인가요?","options":[{"t":"들은 말을 그대로 받아쓰지 않고 언제·어디에서·무엇을·누구와 칸에 맞게 간단히 쓴다","correct":true},{"t":"친구가 한 말을 한 글자도 빼지 않고 받아쓴다","mis":"K3-2-u1-X12"},{"t":"정리한 것이 친구와 다르면 지우고 친구 것을 베낀다","mis":"K3-2-u1-X16"},{"t":"기억나지 않는 칸은 내 마음대로 지어 쓴다","mis":"K3-2-u1-X01"}],"explanation":["지도서는 들은 내용을 그대로 받아쓰지 않도록 안내해요.","칸에 맞게 간단히 써요.","같은 이야기를 들어도 정리한 것은 서로 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_challenge#3','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C3',3,'mc','auto','「은행잎 편지」의 분위기를 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":3,"kind":"mc","stem":"「은행잎 편지」의 분위기를 바르게 말한 것은 무엇인가요?","options":[{"t":"떠난 친구를 그리워하는 쓸쓸하고 애틋한 분위기","correct":true},{"t":"신나고 떠들썩한 분위기","mis":"K3-2-u1-X04"},{"t":"무섭고 으스스한 분위기","mis":"K3-2-u1-X04"},{"t":"화가 나서 씩씩거리는 분위기","mis":"K3-2-u1-X04"}],"explanation":["지도서의 첫 교사 질문이 「이 시의 분위기는 어떤가요?」예요.","「나도 몰래 이사 간 친구」와 「내 생각 날까?」를 근거로 들어요.","그리움이 담긴 쓸쓸한 분위기예요."],"asset":{"type":"passage","lines":["[간추림] 4~5연 — 은행잎이 동동동 흘러가다가 친구가 내 편지를 보지 않을까 생각한다.","편지 보고 가끔은","내 생각 날까?"],"title":"시 「은행잎 편지」 6연 — 『국어』 37쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_challenge#4','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C1',3,'match','auto','『국어』 40쪽 5번에서 마음의 벽이 있었던 경험을 떠올리는 물음과 예시 답을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u1-C1","difficulty":3,"kind":"match","stem":"『국어』 40쪽 5번에서 마음의 벽이 있었던 경험을 떠올리는 물음과 예시 답을 알맞게 이으세요.","pairs":[{"l":"언제 누구와 있었던 일인가요?","r":"1학년 때 친구와 있었던 일"},{"l":"무슨 일이 있었나요?","r":"친구가 장난으로 한 말에 상처를 입음"},{"l":"그때 내 마음은 어땠나요?","r":"속상하고 화가 나서 놀고 싶지 않음"},{"l":"나는 어떻게 행동했나요?","r":"마음을 말하고 사과해 달라고 함"}],"mis":"K3-2-u1-X01","explanation":["언제·누구와 → 무슨 일 → 마음 → 행동 차례로 떠올려요.","마음과 행동은 서로 달라요.","이렇게 떠올리면 경험이 또렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_challenge#5','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C2',3,'ox','auto','「벽 부수기」와 이어지는 경험을 떠올리려면 진짜 벽을 쌓거나 부숴 본 일이 있어야 해요.',ARRAY['K3-2-u1-X02']::text[],false,'{"seq":5,"concept":"K3-2-u1-C2","difficulty":3,"kind":"ox","stem":"「벽 부수기」와 이어지는 경험을 떠올리려면 진짜 벽을 쌓거나 부숴 본 일이 있어야 해요.","answer":"X","reason_options":[{"t":"누군가에게 서운하거나 화가 나서 말하기 싫었던 경험이면 되기 때문에","correct":true},{"t":"시에 벽이 나오니 벽과 관련된 일이어야 하기 때문에","mis":"K3-2-u1-X02"}],"mis":"K3-2-u1-X02","explanation":["「맘속에 벽」은 마음이 막힌 모습이에요.","겉에 나온 물건이 같을 필요는 없어요.","마음이 이어지면 되니 X예요."],"asset":{"type":"passage","lines":["맘속에 벽이 있으면","[간추림] 말도 하고 싶지 않고, 보고 싶지도 않고, 화만 나고 답답하다.","[간추림] 그 벽은 「입장 바꿔 생각해 보기」라는 약을 마음에 풀어 마시면 없어진다."],"title":"시 「벽 부수기」(박희순) 앞부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_challenge#6','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C4',3,'blank','auto','5번에서 「친구와 함께했던 행복한 기억을 떠올린다」를 벽 없애는 방법으로 쓴 친구가 「어떻게 벽을 없애느냐고? / ‘○○ ○○ 생각해 보기’란 약을」의 빈칸에 넣을 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X06']::text[],false,'{"seq":6,"concept":"K3-2-u1-C4","difficulty":3,"kind":"blank","stem":"5번에서 「친구와 함께했던 행복한 기억을 떠올린다」를 벽 없애는 방법으로 쓴 친구가 「어떻게 벽을 없애느냐고? / ‘○○ ○○ 생각해 보기’란 약을」의 빈칸에 넣을 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"좋은 추억","correct":true},{"t":"입장 바꿔","mis":"K3-2-u1-X06"},{"t":"빨리 잊어","mis":"K3-2-u1-X06"},{"t":"누가 잘못했나","mis":"K3-2-u1-X06"}],"explanation":["5번에서 떠올린 나만의 방법을 넣어요.","행복한 기억을 떠올리는 것은 「좋은 추억 생각해 보기」예요.","그래야 뒤의 「행복했던 추억이 떠올라」와 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_challenge#7','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C4',3,'mc','auto','시를 바꾸어 쓸 때 뜻이 이어지는 덩어리에 맞게 행을 나눈 것은 어느 것인가요?',ARRAY['K3-2-u1-X25']::text[],false,'{"seq":7,"concept":"K3-2-u1-C4","difficulty":3,"kind":"mc","stem":"시를 바꾸어 쓸 때 뜻이 이어지는 덩어리에 맞게 행을 나눈 것은 어느 것인가요?","options":[{"t":"눈 마주치기 싫고 / 자꾸 미워하는 마음이 / 스멀스멀 올라와.","correct":true},{"t":"눈 마 / 주치기 싫고 자꾸 / 미워하는 마음이 스멀 / 스멀 올라와.","mis":"K3-2-u1-X25"},{"t":"눈 마주치기 싫고 자꾸 미워하는 마음이 스멀스멀 올라와.","mis":"K3-2-u1-X25"},{"t":"눈 / 마주치기 / 싫고 자꾸 미워하는 / 마음이 스멀스멀 / 올라와.","mis":"K3-2-u1-X25"}],"explanation":["지도서는 시를 쓸 때 의미 단위에 맞게 행을 나누라고 해요.","소리 내어 읽을 때 자연스럽게 쉬는 곳에서 나눠요.","낱말 가운데를 자르거나 한 줄에 몰아 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_challenge#8','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C2',4,'essay','teacher','「은행잎 편지」의 말하는 이처럼 누군가와 멀리 떨어져 지낸 경험을 떠올려, 그 사람에게 전하고 싶은 마음을 담아 은행잎 편지를 쓰세요. 언제, 누구와 떨어졌는지도 넣으세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u1-C2","difficulty":4,"kind":"essay","stem":"「은행잎 편지」의 말하는 이처럼 누군가와 멀리 떨어져 지낸 경험을 떠올려, 그 사람에게 전하고 싶은 마음을 담아 은행잎 편지를 쓰세요. 언제, 누구와 떨어졌는지도 넣으세요.","answer_guide":{"answer":"예: 안녕, 지호야? 2학년 때 네가 갑자기 전학을 간다는 소식을 듣고 너무 슬펐어. 나는 지금도 가끔 너랑 운동장에서 놀던 일을 떠올려. 잘 지내고 있니? 이번 방학에 시간이 되면 꼭 만나자.","scoring_points":["떨어져 지낸 사람과 때를 밝혔는가","그 사람에게 전하고 싶은 마음을 담았는가","편지 꼴(받는 사람·인사)을 갖추었는가"]},"explanation":["『국어』 38쪽 3번 (2)번 활동이에요.","겪은 일이 달라도 그리운 마음이 비슷하면 돼요.","편지를 쓰면 말하는 이의 마음에 더 공감할 수 있어요."],"asset":{"type":"passage","lines":["[간추림] 4~5연 — 은행잎이 동동동 흘러가다가 친구가 내 편지를 보지 않을까 생각한다.","편지 보고 가끔은","내 생각 날까?"],"title":"시 「은행잎 편지」 6연 — 『국어』 37쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_challenge#9','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C3',4,'essay','teacher','이사 간 친구가 「은행잎 편지」를 받아 본다면 어떤 마음이 들지 쓰고, 그렇게 짐작한 까닭을 시에 나온 말과 내 경험에서 하나씩 찾아 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C3","difficulty":4,"kind":"essay","stem":"이사 간 친구가 「은행잎 편지」를 받아 본다면 어떤 마음이 들지 쓰고, 그렇게 짐작한 까닭을 시에 나온 말과 내 경험에서 하나씩 찾아 쓰세요.","answer_guide":{"answer":"예: 반갑고 미안한 마음이 들 것 같다. 시에서 「편지 보고 가끔은 / 내 생각 날까?」라고 할 만큼 친구를 그리워했기 때문이다. 나도 전학 간 친구에게서 쪽지를 받았을 때 인사를 못 하고 헤어진 게 미안하면서도 정말 반가웠다.","scoring_points":["친구가 느낄 마음을 썼는가","시에 나온 말을 근거로 들었는가","이어지는 내 경험을 근거로 들었는가"]},"explanation":["지도서 교사 질문 「은행잎 편지를 받아 본다면 어떤 마음이 들까요?」예요.","마음은 시에 그대로 적혀 있지 않아요.","시의 말과 내 경험을 근거로 짐작해요."],"asset":{"type":"passage","lines":["[간추림] 4~5연 — 은행잎이 동동동 흘러가다가 친구가 내 편지를 보지 않을까 생각한다.","편지 보고 가끔은","내 생각 날까?"],"title":"시 「은행잎 편지」 6연 — 『국어』 37쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L02_challenge#10','kor',3,2,'u1','L02','tb_g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C4',4,'essay','teacher','5번에서 떠올린 마음의 벽 경험을 바탕으로 「벽 부수기」의 세 곳(벽이 있을 때 마음 · 벽을 없애는 약 · 벽이 부서질 때)을 바꾸어 쓰세요. 마지막 「그게 벽 부서지는 소리야.」와 이어지게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C4","difficulty":4,"kind":"essay","stem":"5번에서 떠올린 마음의 벽 경험을 바탕으로 「벽 부수기」의 세 곳(벽이 있을 때 마음 · 벽을 없애는 약 · 벽이 부서질 때)을 바꾸어 쓰세요. 마지막 「그게 벽 부서지는 소리야.」와 이어지게 쓰세요.","answer_guide":{"answer":"예: 맘속에 벽이 있으면 / 눈 마주치기 싫고 / 자꾸 미워하는 마음이 / 스멀스멀 올라와. // 어떻게 벽을 없애느냐고? / ‘좋은 추억 생각해 보기’란 약을 / 마음에 풀어서 마시는 거야. // 행복했던 추억이 떠올라 / ‘히힛’ 웃음소리 나온다 / 그게 벽 부서지는 소리야.","scoring_points":["세 곳을 모두 내 경험으로 바꾸었는가","벽을 없애는 약이 내가 쓴 방법과 이어지는가","마지막 줄과 이어지고 뜻 덩어리마다 행을 나누었는가"]},"explanation":["『국어』 41쪽 6번 활동이에요.","마음의 벽을 없애는 가장 좋은 방법을 고민해 빈칸을 채워요.","시를 쓸 때는 의미 단위에 맞게 행을 나눠요."],"asset":{"type":"passage","lines":["맘속에 벽이 있으면","눈 마주치기 싫고","자꾸 미워하는 마음이","스멀스멀 올라와.","‘좋은 추억 생각해 보기’란 약을","마음에 풀어서 마시는 거야.","행복했던 추억이 떠올라","‘히힛’ 웃음소리 나온다"],"title":"「벽 부수기」를 바꾸어 쓴 시 — 『국어』 41쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_basic#1','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C5',1,'mc','auto','「나도 최고가 되고 싶어요」에서 로지는 어떤 말을 듣기 싫어했나요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":1,"concept":"K3-2-u1-C5","difficulty":1,"kind":"mc","stem":"「나도 최고가 되고 싶어요」에서 로지는 어떤 말을 듣기 싫어했나요?","options":[{"t":"바이올렛이 최고라는 말","correct":true},{"t":"로지가 최고라는 말","mis":"K3-2-u1-X07"},{"t":"완두콩을 키우자는 말","mis":"K3-2-u1-X07"},{"t":"화분을 꾸며 오라는 말","mis":"K3-2-u1-X07"}],"explanation":["『국어』 47쪽 「내용 알기」 (1)번이에요.","바이올렛은 뭐든지 최고로 잘했어요.","로지는 바이올렛이 최고라는 말을 듣기가 싫었어요."],"asset":{"type":"passage","lines":["[간추림] 바이올렛은 뭐든지 최고로 잘해요. 가장 빨리 달리고 가장 높게 노래해요.","[간추림] 로지는 바이올렛이 최고라는 말을 듣기가 싫었어요.","[간추림] 윌리스 선생님이 저마다 꼬마 화분에 완두콩을 키우자고 했어요.","[간추림] 바이올렛의 화분은 반짝반짝 빛났고, 로지의 화분은 평범했어요.","[간추림] 로지와 바이올렛의 화분에서 먼저 새싹이 올라왔어요.","바이올렛이 큰 소리로 외쳤어요. “내가 일 등이다! 만세!”"],"title":"이야기 「나도 최고가 되고 싶어요」 ① — 『국어』 42~44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_basic#2','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C5',1,'sa','auto','윌리스 선생님이 「씨앗이 건강한 식물로 자라려면 무엇이 필요할까요?」라고 물었을 때 아이들은 공기, 물, 햇빛과 또 무엇이라고 대답했나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u1-C5","difficulty":1,"kind":"sa","stem":"윌리스 선생님이 「씨앗이 건강한 식물로 자라려면 무엇이 필요할까요?」라고 물었을 때 아이들은 공기, 물, 햇빛과 또 무엇이라고 대답했나요? 한 글자로 쓰세요.","answer":["흙"],"explanation":["이 물음의 답은 글이 아니라 『국어』 43쪽 그림 속 아이들의 말에 있어요.","아이들은 「공기요! 햇빛이요! 흙이요! 물이요!」라고 했어요.","글과 그림을 이어 읽으면 흙을 찾을 수 있어요."],"mis":"K3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_basic#3','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C5',1,'mc','auto','「남이 알아차리지 못하게 슬며시」라는 뜻을 가진 낱말은 무엇인가요?',ARRAY['K3-2-u1-X08']::text[],false,'{"seq":3,"concept":"K3-2-u1-C5","difficulty":1,"kind":"mc","stem":"「남이 알아차리지 못하게 슬며시」라는 뜻을 가진 낱말은 무엇인가요?","options":[{"t":"슬그머니","correct":true},{"t":"듬뿍","mis":"K3-2-u1-X08"},{"t":"평범하다","mis":"K3-2-u1-X08"},{"t":"에워싸다","mis":"K3-2-u1-X08"}],"explanation":["『국어』 47쪽 「낱말 알기」예요.","로지가 새싹을 덮고 「슬그머니 자리에 앉았어요.」","아무도 모르게 움직이는 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_basic#4','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C5',1,'ox','auto','로지는 바이올렛이 학교에 없는 동안 바이올렛의 화분은 내버려 두고 자기 화분만 돌보았어요.',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":4,"concept":"K3-2-u1-C5","difficulty":1,"kind":"ox","stem":"로지는 바이올렛이 학교에 없는 동안 바이올렛의 화분은 내버려 두고 자기 화분만 돌보았어요.","answer":"X","reason_options":[{"t":"2주 동안 매일 아침 일찍 와서 화분 두 개를 똑같이 정성껏 돌보았기 때문에","correct":true},{"t":"바이올렛의 새싹을 흙으로 덮을 만큼 미워했기 때문에","mis":"K3-2-u1-X07"}],"mis":"K3-2-u1-X07","explanation":["③을 다시 읽어요.","흙을 털어 주고 두 화분에 똑같이 물을 주었어요.","노래도 불러 주고 햇빛 드는 자리에 두었으니 X예요."],"asset":{"type":"passage","lines":["[간추림] 로지는 책상에 푹 엎드렸어요. 새싹에게, 바이올렛에게도 미안했어요.","[간추림] 2주 동안 로지는 매일 아침 일찍 와서 화분 두 개를 정성껏 돌보았어요.","[간추림] 바이올렛 새싹을 덮은 흙을 털어 주고, 두 화분에 똑같이 물을 주었어요.","[간추림] 두 완두콩에 노래를 불러 주고, 햇빛이 잘 드는 자리에 두었어요.","“정말 훌륭하게 키웠구나. … 최고의 원예사야!”"],"title":"이야기 「나도 최고가 되고 싶어요」 ③ — 『국어』 45쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_basic#5','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C6',2,'mc','auto','로지가 바이올렛의 새싹을 흙으로 덮어 버린 까닭으로 알맞은 짐작은 무엇인가요?',ARRAY['K3-2-u1-X04','K3-2-u1-X07']::text[],false,'{"seq":5,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"로지가 바이올렛의 새싹을 흙으로 덮어 버린 까닭으로 알맞은 짐작은 무엇인가요?","options":[{"t":"바이올렛의 새싹이 조금 더 큰 것을 보고 질투가 나서","correct":true},{"t":"원래 흙 만지기를 좋아해서","mis":"K3-2-u1-X04"},{"t":"새싹이 추울까 봐 덮어 주려고","mis":"K3-2-u1-X04"},{"t":"선생님이 덮으라고 시켜서","mis":"K3-2-u1-X07"}],"explanation":["『국어』 47쪽 (2)번이에요.","로지는 자기 새싹이 최고가 되기를 바랐어요.","「됐어. 이제 내 완두콩이 최고야.」라는 생각이 근거예요."],"asset":{"type":"passage","lines":["[간추림] 이튿날 아침 일찍, 로지는 바이올렛의 새싹이 조금 더 큰 것을 보았어요.","로지는 마음속으로 생각했어요. ‘이러면 안 되는데.’","[간추림] 로지는 슬쩍 어깨 너머를 살핀 뒤 바이올렛의 새싹을 흙으로 덮었어요.","‘됐어. 이제 내 완두콩이 최고야.’","[간추림] 아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.","[간추림] 그날 바이올렛은 수두에 걸려 당분간 학교에 못 나온다고 했어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ② — 『국어』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_basic#6','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C6',2,'mc','auto','「아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.」에서 로지의 마음이 무거워진 까닭은 무엇일까요?',ARRAY['K3-2-u1-X07','K3-2-u1-X04']::text[],false,'{"seq":6,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"「아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.」에서 로지의 마음이 무거워진 까닭은 무엇일까요?","options":[{"t":"스스로에게 떳떳하지 못한 일을 해서","correct":true},{"t":"완두콩이 다 죽어서","mis":"K3-2-u1-X07"},{"t":"바이올렛이 로지를 혼내서","mis":"K3-2-u1-X07"},{"t":"수업 종이 너무 일찍 울려서","mis":"K3-2-u1-X04"}],"explanation":["최고가 되었다는 생각에 잠깐 기분이 좋았어요.","하지만 정당하지 못한 방법을 썼어요.","그래서 마음이 불편해지고 후회가 되었어요."],"asset":{"type":"passage","lines":["[간추림] 이튿날 아침 일찍, 로지는 바이올렛의 새싹이 조금 더 큰 것을 보았어요.","로지는 마음속으로 생각했어요. ‘이러면 안 되는데.’","[간추림] 로지는 슬쩍 어깨 너머를 살핀 뒤 바이올렛의 새싹을 흙으로 덮었어요.","‘됐어. 이제 내 완두콩이 최고야.’","[간추림] 아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.","[간추림] 그날 바이올렛은 수두에 걸려 당분간 학교에 못 나온다고 했어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ② — 『국어』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_basic#7','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C6',2,'mc','auto','윌리스 선생님께 「최고의 원예사야!」라는 말을 들었을 때 로지의 마음으로 알맞은 짐작은 무엇인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":7,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"윌리스 선생님께 「최고의 원예사야!」라는 말을 들었을 때 로지의 마음으로 알맞은 짐작은 무엇인가요?","options":[{"t":"기쁘고, 바이올렛과 새싹에게 미안했던 마음이 풀렸을 것이다","correct":true},{"t":"바이올렛을 이겨서 신났을 것이다","mis":"K3-2-u1-X04"},{"t":"칭찬이 부끄러워 화가 났을 것이다","mis":"K3-2-u1-X04"},{"t":"아무 느낌이 없었을 것이다","mis":"K3-2-u1-X04"}],"explanation":["『국어』 47쪽 (3)번이에요.","로지는 두 화분을 정성껏 돌본 끝에 칭찬을 들었어요.","「로지는 활짝 웃었어요.」가 근거예요."],"asset":{"type":"passage","lines":["[간추림] 로지는 책상에 푹 엎드렸어요. 새싹에게, 바이올렛에게도 미안했어요.","[간추림] 2주 동안 로지는 매일 아침 일찍 와서 화분 두 개를 정성껏 돌보았어요.","[간추림] 바이올렛 새싹을 덮은 흙을 털어 주고, 두 화분에 똑같이 물을 주었어요.","[간추림] 두 완두콩에 노래를 불러 주고, 햇빛이 잘 드는 자리에 두었어요.","“정말 훌륭하게 키웠구나. … 최고의 원예사야!”"],"title":"이야기 「나도 최고가 되고 싶어요」 ③ — 『국어』 45쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_basic#8','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C5',2,'match','auto','『국어』 47쪽 「낱말 알기」의 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u1-C5","difficulty":2,"kind":"match","stem":"『국어』 47쪽 「낱말 알기」의 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"평범하다","r":"뛰어나거나 색다른 점이 없이 보통이다"},{"l":"듬뿍","r":"매우 많거나 넉넉한 모양"},{"l":"에워싸다","r":"둘레를 빙 둘러싸다"}],"mis":"K3-2-u1-X08","explanation":["로지의 화분은 평범했지만 완두콩이 자라기에 모자람이 없었어요.","햇빛을 듬뿍 받는 자리에 두었어요.","모두가 바이올렛을 에워싸고 수두 이야기를 들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_basic#9','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C7',2,'mc','auto','「나도 최고가 되고 싶어요」를 읽고 떠올린 경험으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X02']::text[],false,'{"seq":9,"concept":"K3-2-u1-C7","difficulty":2,"kind":"mc","stem":"「나도 최고가 되고 싶어요」를 읽고 떠올린 경험으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"반에서 일 등을 하고 싶어서 친구를 몰래 부러워했던 일","correct":true},{"t":"완두콩을 먹어 본 일","mis":"K3-2-u1-X02"},{"t":"수두에 걸렸던 일","mis":"K3-2-u1-X02"},{"t":"화분을 산 일","mis":"K3-2-u1-X02"}],"explanation":["『국어』 48쪽은 최고가 되고 싶었던 마음이 들었던 때를 떠올려요.","완두콩·수두·화분처럼 겉에 나온 것이 같다고 이어지지 않아요.","로지와 비슷한 마음을 느낀 일을 찾아요."],"asset":{"type":"passage","lines":["[간추림] 이튿날 아침 일찍, 로지는 바이올렛의 새싹이 조금 더 큰 것을 보았어요.","로지는 마음속으로 생각했어요. ‘이러면 안 되는데.’","[간추림] 로지는 슬쩍 어깨 너머를 살핀 뒤 바이올렛의 새싹을 흙으로 덮었어요.","‘됐어. 이제 내 완두콩이 최고야.’","[간추림] 아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.","[간추림] 그날 바이올렛은 수두에 걸려 당분간 학교에 못 나온다고 했어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ② — 『국어』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_basic#10','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C7',3,'error','auto','로지네 반 친구에게 하고 싶은 말을 했어요. 인물의 말이나 행동을 짚어 마음을 알아주는 말이 아닌 것은 무엇인가요?',ARRAY['K3-2-u1-X09']::text[],false,'{"seq":10,"concept":"K3-2-u1-C7","difficulty":3,"kind":"error","stem":"로지네 반 친구에게 하고 싶은 말을 했어요. 인물의 말이나 행동을 짚어 마음을 알아주는 말이 아닌 것은 무엇인가요?","options":[{"t":"「로지야, 너는 정말 나쁜 아이야. 다시는 그러지 마.」","correct":true,"mis_target":"K3-2-u1-X09"},{"t":"「로지야, 넌 참 대단해. 잘못을 깨닫고 바로잡았어.」","mis":"K3-2-u1-X09"},{"t":"「바이올렛아, 자신감 있는 모습이 보기 좋았어.」","mis":"K3-2-u1-X09"}],"explanation":["『국어』 49쪽 「자신과 관련짓기」예요.","하고 싶은 말은 인물을 탓하거나 가르치는 말이 아니에요.","인물이 한 일을 짚어 마음을 알아주는 말이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_challenge#1','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C5',2,'mc','auto','「나도 최고가 되고 싶어요」를 읽기 전에 제목과 그림을 보고 내용을 짐작할 때 알맞은 질문은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":1,"concept":"K3-2-u1-C5","difficulty":2,"kind":"mc","stem":"「나도 최고가 되고 싶어요」를 읽기 전에 제목과 그림을 보고 내용을 짐작할 때 알맞은 질문은 무엇인가요?","options":[{"t":"제목이 왜 ‘나도 최고가 되고 싶어요’일까요?","correct":true},{"t":"이 책은 몇 쪽일까요?","mis":"K3-2-u1-X07"},{"t":"그림을 그린 사람은 몇 살일까요?","mis":"K3-2-u1-X07"},{"t":"책은 얼마일까요?","mis":"K3-2-u1-X07"}],"explanation":["지도서는 읽기 전에 제목과 그림으로 내용을 예상하게 해요.","「그림에서 아이가 무엇을 하고 있나요?」도 좋은 질문이에요.","읽은 뒤에는 예상한 내용과 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_challenge#2','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C6',2,'ox','auto','같은 장면을 읽어도 친구마다 로지의 마음을 다르게 짐작할 수 있어요.',ARRAY['K3-2-u1-X05']::text[],false,'{"seq":2,"concept":"K3-2-u1-C6","difficulty":2,"kind":"ox","stem":"같은 장면을 읽어도 친구마다 로지의 마음을 다르게 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"각자의 경험에 따라 같은 상황에서도 인물의 마음을 다르게 짐작할 수 있기 때문에","correct":true},{"t":"이야기에 나온 마음은 하나뿐이라 한 사람만 맞기 때문에","mis":"K3-2-u1-X05"}],"mis":"K3-2-u1-X05","explanation":["지도서는 인물의 마음을 자기 경험에 비추어 생각하게 해요.","그래서 짐작은 서로 다를 수 있어요.","다만 글에 나온 말이나 행동을 근거로 대야 해요."],"asset":{"type":"passage","lines":["[간추림] 이튿날 아침 일찍, 로지는 바이올렛의 새싹이 조금 더 큰 것을 보았어요.","로지는 마음속으로 생각했어요. ‘이러면 안 되는데.’","[간추림] 로지는 슬쩍 어깨 너머를 살핀 뒤 바이올렛의 새싹을 흙으로 덮었어요.","‘됐어. 이제 내 완두콩이 최고야.’","[간추림] 아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.","[간추림] 그날 바이올렛은 수두에 걸려 당분간 학교에 못 나온다고 했어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ② — 『국어』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_challenge#3','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C5',3,'mc','auto','로지가 「‘이러면 안 되는데.’」라고 생각한 때는 언제인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":3,"concept":"K3-2-u1-C5","difficulty":3,"kind":"mc","stem":"로지가 「‘이러면 안 되는데.’」라고 생각한 때는 언제인가요?","options":[{"t":"바이올렛의 새싹이 조금 더 큰 것을 보았을 때","correct":true},{"t":"바이올렛이 수두에 걸렸다는 말을 들었을 때","mis":"K3-2-u1-X07"},{"t":"선생님께 칭찬을 들었을 때","mis":"K3-2-u1-X07"},{"t":"화분을 예쁘게 꾸미라는 숙제를 받았을 때","mis":"K3-2-u1-X07"}],"explanation":["②의 처음을 읽어요.","이튿날 아침 일찍 새싹을 살펴보러 갔어요.","바이올렛의 새싹이 조금 더 큰 것을 보고 생각했어요."],"asset":{"type":"passage","lines":["[간추림] 이튿날 아침 일찍, 로지는 바이올렛의 새싹이 조금 더 큰 것을 보았어요.","로지는 마음속으로 생각했어요. ‘이러면 안 되는데.’","[간추림] 로지는 슬쩍 어깨 너머를 살핀 뒤 바이올렛의 새싹을 흙으로 덮었어요.","‘됐어. 이제 내 완두콩이 최고야.’","[간추림] 아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.","[간추림] 그날 바이올렛은 수두에 걸려 당분간 학교에 못 나온다고 했어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ② — 『국어』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_challenge#4','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C5',3,'mc','auto','다음 질문 가운데 글을 읽고 바로 답을 찾을 수 있는 질문(내용 확인 질문)은 무엇인가요?',ARRAY['K3-2-u1-X26']::text[],false,'{"seq":4,"concept":"K3-2-u1-C5","difficulty":3,"kind":"mc","stem":"다음 질문 가운데 글을 읽고 바로 답을 찾을 수 있는 질문(내용 확인 질문)은 무엇인가요?","options":[{"t":"화분에 키운 것은 무엇이었나요?","correct":true},{"t":"로지는 왜 바이올렛의 새싹을 흙으로 덮어 버렸을까요?","mis":"K3-2-u1-X26"},{"t":"내가 만약 로지라면 바이올렛이 학교에 오지 않을 때 어떻게 했을까요?","mis":"K3-2-u1-X26"},{"t":"로지에게 하고 싶은 말은 무엇인가요?","mis":"K3-2-u1-X26"}],"explanation":["지도서는 내용 확인 · 추론 · 감상 질문을 나누어요.","「완두콩」은 글에 그대로 나와요.","「왜 덮었을까요?」는 추론, 「내가 로지라면」은 감상 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_challenge#5','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C7',3,'match','auto','『국어』 48쪽 경험 나누기 놀이의 경험 쪽지를 모둠에서 「도움을 주었던 경험 / 도움을 받았던 경험」으로 나누었어요. 쪽지와 칸을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C7","difficulty":3,"kind":"match","stem":"『국어』 48쪽 경험 나누기 놀이의 경험 쪽지를 모둠에서 「도움을 주었던 경험 / 도움을 받았던 경험」으로 나누었어요. 쪽지와 칸을 알맞게 이으세요.","pairs":[{"l":"미술 시간에 가위가 없을 때 지윤이가 빌려주어서 고마웠다","r":"도움을 받았던 경험"},{"l":"넘어진 동생을 일으켜 주고 무릎을 닦아 주었다","r":"도움을 주었던 경험"}],"mis":"K3-2-u1-X28","explanation":["놀이 2단계에서 바꾼 쪽지를 모둠별로 모아 나누어요.","누가 누구를 도왔는지 보면 칸이 정해져요.","나눈 쪽지는 칠판에 공간을 나누어 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_challenge#6','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C6',3,'mc','auto','「“고마워, 로지.” 바이올렛이 아주 작은 목소리로 말했어요.」에서 바이올렛이 작은 목소리로 말한 까닭으로 알맞은 짐작은 무엇인가요?',ARRAY['K3-2-u1-X04','K3-2-u1-X07']::text[],false,'{"seq":6,"concept":"K3-2-u1-C6","difficulty":3,"kind":"mc","stem":"「“고마워, 로지.” 바이올렛이 아주 작은 목소리로 말했어요.」에서 바이올렛이 작은 목소리로 말한 까닭으로 알맞은 짐작은 무엇인가요?","options":[{"t":"고맙지만 늘 최고이던 자기가 도움을 받은 것이 쑥스러워서","correct":true},{"t":"목이 아파 큰 소리를 낼 수 없어서","mis":"K3-2-u1-X04"},{"t":"로지에게 화가 나서","mis":"K3-2-u1-X04"},{"t":"선생님이 작게 말하라고 해서","mis":"K3-2-u1-X07"}],"explanation":["바로 뒤에 큰 목소리로 「그래도 내 완두콩이 제일 반짝반짝 빛난다!」라고 했어요.","고마운 마음과 최고이고 싶은 마음이 함께 있어요.","말과 행동을 근거로 짐작해요."],"asset":{"type":"passage","lines":["[간추림] 바이올렛이 돌아와 “내 완두콩이 제일 크다! 만세!” 하고 외쳤어요.","[간추림] 선생님은 로지가 완두콩 두 개를 얼마나 열심히 키웠는지 말해 주었어요.","“고마워, 로지.”","[간추림] 바이올렛은 아주 작은 목소리로 말한 뒤, 큰 목소리로 덧붙였어요.","“그래도 내 완두콩이 제일 반짝반짝 빛난다!”","[간추림] 윌리스 선생님과 로지는 서로 바라보며 빙그레 웃었어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ④ — 『국어』 46쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_challenge#7','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C6',3,'mc','auto','이야기의 마지막에 윌리스 선생님과 로지가 서로 바라보며 빙그레 웃은 까닭으로 알맞은 짐작은 무엇인가요?',ARRAY['K3-2-u1-X04','K3-2-u1-X07']::text[],false,'{"seq":7,"concept":"K3-2-u1-C6","difficulty":3,"kind":"mc","stem":"이야기의 마지막에 윌리스 선생님과 로지가 서로 바라보며 빙그레 웃은 까닭으로 알맞은 짐작은 무엇인가요?","options":[{"t":"로지가 잘못을 바로잡고 두 화분을 정성껏 키운 것을 둘 다 알고 있어서","correct":true},{"t":"바이올렛의 말이 우스워서 놀리려고","mis":"K3-2-u1-X04"},{"t":"로지의 완두콩이 가장 작아서","mis":"K3-2-u1-X07"},{"t":"선생님이 로지를 혼낼 생각이어서","mis":"K3-2-u1-X04"}],"explanation":["지도서는 두 사람이 빙그레 웃은 까닭을 이야기해 보게 해요.","로지가 2주 동안 한 일을 선생님은 알고 있어요.","로지의 마음이 달라진 것을 둘 다 아는 웃음이에요."],"asset":{"type":"passage","lines":["[간추림] 바이올렛이 돌아와 “내 완두콩이 제일 크다! 만세!” 하고 외쳤어요.","[간추림] 선생님은 로지가 완두콩 두 개를 얼마나 열심히 키웠는지 말해 주었어요.","“고마워, 로지.”","[간추림] 바이올렛은 아주 작은 목소리로 말한 뒤, 큰 목소리로 덧붙였어요.","“그래도 내 완두콩이 제일 반짝반짝 빛난다!”","[간추림] 윌리스 선생님과 로지는 서로 바라보며 빙그레 웃었어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ④ — 『국어』 46쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_challenge#8','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C7',4,'essay','teacher','로지가 겪은 일과 비슷한 내 경험을 떠올려 경험 쪽지를 쓰세요. 쪽지 앞면에 들어갈 제목과, 안쪽에 들어갈 경험과 그때의 생각이나 느낌을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u1-C7","difficulty":4,"kind":"essay","stem":"로지가 겪은 일과 비슷한 내 경험을 떠올려 경험 쪽지를 쓰세요. 쪽지 앞면에 들어갈 제목과, 안쪽에 들어갈 경험과 그때의 생각이나 느낌을 쓰세요.","answer_guide":{"answer":"예: 제목 — 달리기 일 등을 놓친 날. 경험 — 운동회 때 일 등을 하고 싶어서 출발 신호보다 먼저 뛰어 나갔다가 다시 뛰게 되었다. 생각이나 느낌 — 일 등만 생각하다가 반칙을 해서 부끄러웠고, 로지처럼 마음이 무거웠다.","scoring_points":["경험에 알맞은 제목을 붙였는가","로지가 겪은 일이나 마음과 이어지는 경험을 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["『국어』 48쪽 경험 나누기 놀이 1단계예요.","종이를 반으로 접어 제목을 쓰고, 펼쳐서 경험과 느낌을 써요.","이야기와 똑같지 않아도 비슷한 마음이면 돼요."],"asset":{"type":"passage","lines":["[간추림] 이튿날 아침 일찍, 로지는 바이올렛의 새싹이 조금 더 큰 것을 보았어요.","로지는 마음속으로 생각했어요. ‘이러면 안 되는데.’","[간추림] 로지는 슬쩍 어깨 너머를 살핀 뒤 바이올렛의 새싹을 흙으로 덮었어요.","‘됐어. 이제 내 완두콩이 최고야.’","[간추림] 아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.","[간추림] 그날 바이올렛은 수두에 걸려 당분간 학교에 못 나온다고 했어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ② — 『국어』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_challenge#9','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C7',4,'essay','teacher','「나도 최고가 되고 싶어요」에서 로지의 마음이 처음과 끝에 어떻게 달라졌는지 쓰고, 그 마음을 알 수 있는 로지의 행동을 하나씩 짚어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C7","difficulty":4,"kind":"essay","stem":"「나도 최고가 되고 싶어요」에서 로지의 마음이 처음과 끝에 어떻게 달라졌는지 쓰고, 그 마음을 알 수 있는 로지의 행동을 하나씩 짚어 쓰세요.","answer_guide":{"answer":"예: 처음에 로지는 바이올렛이 늘 최고인 것이 싫어서 바이올렛의 새싹을 흙으로 덮었다. 하지만 바이올렛과 새싹에게 미안한 마음이 들어서 2주 동안 두 화분을 정성껏 돌보았고, 끝에는 바이올렛이 자기 완두콩이 가장 반짝인다고 말해도 빙그레 웃었다.","scoring_points":["처음 마음과 그 행동을 썼는가","끝 마음과 그 행동을 썼는가","마음이 달라진 까닭(미안한 마음)을 썼는가"]},"explanation":["『국어』 48쪽 (3)번 활동이에요.","흙으로 덮은 행동과 두 화분을 돌본 행동을 견주어요.","마음이 달라진 까닭은 미안한 마음이에요."],"asset":{"type":"passage","lines":["[간추림] 로지는 책상에 푹 엎드렸어요. 새싹에게, 바이올렛에게도 미안했어요.","[간추림] 2주 동안 로지는 매일 아침 일찍 와서 화분 두 개를 정성껏 돌보았어요.","[간추림] 바이올렛 새싹을 덮은 흙을 털어 주고, 두 화분에 똑같이 물을 주었어요.","[간추림] 두 완두콩에 노래를 불러 주고, 햇빛이 잘 드는 자리에 두었어요.","“정말 훌륭하게 키웠구나. … 최고의 원예사야!”"],"title":"이야기 「나도 최고가 되고 싶어요」 ③ — 『국어』 45쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L04_challenge#10','kor',3,2,'u1','L04','tb_g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C7',4,'essay','teacher','「나도 최고가 되고 싶어요」를 누구에게 권하고 싶은지 쓰고, 그 사람에게 이 이야기가 어떤 도움이나 깨달음을 줄 수 있을지 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C7","difficulty":4,"kind":"essay","stem":"「나도 최고가 되고 싶어요」를 누구에게 권하고 싶은지 쓰고, 그 사람에게 이 이야기가 어떤 도움이나 깨달음을 줄 수 있을지 까닭을 쓰세요.","answer_guide":{"answer":"예: 시합에서 지면 속상해서 우는 내 동생에게 권하고 싶다. 로지처럼 최고가 되고 싶은 마음이 앞서면 떳떳하지 못한 일을 할 수도 있다는 것과, 정성껏 노력하는 모습이 진짜 멋지다는 것을 알 수 있기 때문이다.","scoring_points":["권할 사람을 밝혔는가","그 사람의 어떤 일과 이어지는지 썼는가","이야기가 줄 도움이나 깨달음을 썼는가"]},"explanation":["지도서 대안 활동 「이야기 추천하기」예요.","누구에게 왜 소개하고 싶은지 생각해요.","작품을 읽고 느낀 점을 바탕으로 까닭을 대요."],"asset":{"type":"passage","lines":["[간추림] 바이올렛이 돌아와 “내 완두콩이 제일 크다! 만세!” 하고 외쳤어요.","[간추림] 선생님은 로지가 완두콩 두 개를 얼마나 열심히 키웠는지 말해 주었어요.","“고마워, 로지.”","[간추림] 바이올렛은 아주 작은 목소리로 말한 뒤, 큰 목소리로 덧붙였어요.","“그래도 내 완두콩이 제일 반짝반짝 빛난다!”","[간추림] 윌리스 선생님과 로지는 서로 바라보며 빙그레 웃었어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ④ — 『국어』 46쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_basic#1','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C9',1,'mc','auto','「생각이 달라도 대화로 풀어요」에서 대화하는 두 사람은 누구누구인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":1,"concept":"K3-2-u1-C9","difficulty":1,"kind":"mc","stem":"「생각이 달라도 대화로 풀어요」에서 대화하는 두 사람은 누구누구인가요?","options":[{"t":"대화법 전문가와 초등학교 3학년 학생","correct":true},{"t":"선생님과 학부모","mis":"K3-2-u1-X07"},{"t":"3학년 학생 두 명","mis":"K3-2-u1-X07"},{"t":"기자와 의사","mis":"K3-2-u1-X07"}],"explanation":["『국어』 50쪽 1번 (1)번이에요.","박민수 박사님은 대화법 전문가예요.","이슬기는 초등학교 3학년 학생이에요."],"asset":{"type":"speech","turns":[{"who":"이슬기","text":"안녕하세요, 대화법 전문가 박민수 박사님. 저는 초등학교 3학년 이슬기입니다."},{"who":"박민수","text":"저는 친구들과 생각이 다를 때 대화로 푸는 방법을 연구하는 사람이에요."},{"who":"이슬기","text":"우리 반 친구들 사이에서 생각이 달라 다툼이나 문제가 생겼을 때 어떻게 하면 좋을지 궁금해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_basic#2','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C9',1,'mc','auto','「생각이 달라도 대화로 풀어요」에서 두 사람은 어떤 이야기를 하고 있나요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":2,"concept":"K3-2-u1-C9","difficulty":1,"kind":"mc","stem":"「생각이 달라도 대화로 풀어요」에서 두 사람은 어떤 이야기를 하고 있나요?","options":[{"t":"반 친구들 사이에 생각이 달라 다툼이 생겼을 때 어떻게 하면 좋을지","correct":true},{"t":"대화법 전문가가 되는 방법","mis":"K3-2-u1-X07"},{"t":"놀이기구를 안전하게 타는 방법","mis":"K3-2-u1-X07"},{"t":"3학년 공부를 잘하는 방법","mis":"K3-2-u1-X07"}],"explanation":["『국어』 50쪽 1번 (2)번이에요.","이슬기가 우리 반 친구들 사이의 다툼을 이야기했어요.","어떻게 하면 좋을지 물어보고 있어요."],"asset":{"type":"speech","turns":[{"who":"이슬기","text":"안녕하세요, 대화법 전문가 박민수 박사님. 저는 초등학교 3학년 이슬기입니다."},{"who":"박민수","text":"저는 친구들과 생각이 다를 때 대화로 푸는 방법을 연구하는 사람이에요."},{"who":"이슬기","text":"우리 반 친구들 사이에서 생각이 달라 다툼이나 문제가 생겼을 때 어떻게 하면 좋을지 궁금해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_basic#3','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',1,'blank','auto','『국어』 51쪽 3번에서 듣기 전에는 듣는 목적을 생각하고, ○○을/를 보고 들을 내용을 예상해요. ○○에 들어갈 말은 무엇인가요?',ARRAY['K3-2-u1-X10']::text[],false,'{"seq":3,"concept":"K3-2-u1-C8","difficulty":1,"kind":"blank","stem":"『국어』 51쪽 3번에서 듣기 전에는 듣는 목적을 생각하고, ○○을/를 보고 들을 내용을 예상해요. ○○에 들어갈 말은 무엇인가요?","options":[{"t":"제목","correct":true},{"t":"정답","mis":"K3-2-u1-X10"},{"t":"말하는 사람의 옷","mis":"K3-2-u1-X10"},{"t":"들은 뒤의 궁금한 점","mis":"K3-2-u1-X10"}],"explanation":["듣기 전에 하는 일이에요.","제목을 보면 무슨 이야기가 나올지 짐작할 수 있어요.","「생각이 달라도 대화로 풀어요」라는 제목에서 다툼을 대화로 푸는 이야기를 예상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_basic#4','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',1,'ox','auto','간추리며 들을 때는 들은 말을 모두 완전한 문장으로 받아 적어야 해요.',ARRAY['K3-2-u1-X12']::text[],false,'{"seq":4,"concept":"K3-2-u1-C8","difficulty":1,"kind":"ox","stem":"간추리며 들을 때는 들은 말을 모두 완전한 문장으로 받아 적어야 해요.","answer":"X","reason_options":[{"t":"중요한 부분만 간단히 기록하는 것이 간추리며 듣는 방법이기 때문에","correct":true},{"t":"하나라도 빠뜨리면 간추린 것이 아니기 때문에","mis":"K3-2-u1-X12"}],"mis":"K3-2-u1-X12","explanation":["지도서는 「모든 내용을 정리하려고 하기」를 나쁜 듣기 습관으로 들어요.","완전한 문장으로 길게 쓰기보다 요점만 간단히 써요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_basic#5','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C9',2,'match','auto','『국어』 51쪽 2번처럼 「생각이 달라도 대화로 풀어요」의 질문과 대답을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C9","difficulty":2,"kind":"match","stem":"『국어』 51쪽 2번처럼 「생각이 달라도 대화로 풀어요」의 질문과 대답을 알맞게 이으세요.","pairs":[{"l":"친구들과 문제가 생겼을 때 해결하는 방법은?","r":"친구와 계속 이야기하려고 노력해야 함."},{"l":"친구와 이야기 나눌 때 주의할 점은?","r":"자신의 마음을 솔직하게 말해야 함."},{"l":"솔직하게 말하기 어려울 때 해결 방법은?","r":"선생님께 도움을 요청함."}],"mis":"K3-2-u1-X17","explanation":["질문 ①·②·③이 차례로 나와요.","대답을 짧게 줄여 질문과 짝지어요.","이 표가 곧 간추린 내용이에요."],"asset":{"type":"speech","turns":[{"who":"이슬기","text":"첫 번째 질문이에요. 친구들과 생각이 달라 문제가 생기면 어떻게 해결해요?"},{"who":"박민수","text":"친구와 계속 이야기하려고 노력해야 해요. 친구 이야기를 집중해서 들으면 생각을 더 알 수 있어요."},{"who":"이슬기","text":"두 번째 질문이에요. 친구와 이야기 나눌 때 주의할 점이 있을까요?"},{"who":"박민수","text":"자신의 마음을 솔직하게 말해야 해요. 그러면 친구가 내 마음을 오해하지 않아요."},{"who":"이슬기","text":"세 번째 질문이에요. 마음을 솔직하게 말하기 어려울 때는요?"},{"who":"박민수","text":"그럴 때에는 선생님께 도움을 요청할 수 있어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_basic#6','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',2,'mc','auto','『국어』 51쪽 3번에서 듣기 중에 주의하라고 한 말이 아닌 것은 무엇인가요?',ARRAY['K3-2-u1-X11']::text[],false,'{"seq":6,"concept":"K3-2-u1-C8","difficulty":2,"kind":"mc","stem":"『국어』 51쪽 3번에서 듣기 중에 주의하라고 한 말이 아닌 것은 무엇인가요?","options":[{"t":"음, 그러니까","correct":true},{"t":"첫째","mis":"K3-2-u1-X11"},{"t":"이것은","mis":"K3-2-u1-X11"},{"t":"따라서","mis":"K3-2-u1-X11"}],"explanation":["듣기 중에는 「첫째」, 「둘째」, 「이것은」, 「따라서」 같은 말에 주의해요.","그 말 뒤에 중요한 내용이 따라와요.","「음, 그러니까」는 생각하며 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_basic#7','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',2,'mc','auto','「놀이기구를 탈 때 기억해요」에서 「둘째」 뒤에 나온 중요한 내용은 무엇인가요?',ARRAY['K3-2-u1-X11','K3-2-u1-X13']::text[],false,'{"seq":7,"concept":"K3-2-u1-C8","difficulty":2,"kind":"mc","stem":"「놀이기구를 탈 때 기억해요」에서 「둘째」 뒤에 나온 중요한 내용은 무엇인가요?","options":[{"t":"안전띠를 잘 매고 풀리지 않는지 살펴본다","correct":true},{"t":"질서 있게 줄을 서서 기다린다","mis":"K3-2-u1-X11"},{"t":"떨어질 수 있는 물건은 가지고 타지 않는다","mis":"K3-2-u1-X11"},{"t":"사람이 많으면 오래 기다릴 수도 있다","mis":"K3-2-u1-X13"}],"explanation":["지도서 101쪽 동기 유발 자료예요.","「첫째」·「둘째」·「셋째」 뒤를 나누어 들어요.","둘째는 안전띠와 손잡이예요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘은 놀이기구를 탈 때 지켜야 하는 중요한 이야기를 해 줄게요."},{"who":"선생님","text":"첫째는 질서 있게 줄을 서서 기다립니다. 장난치지 않고 기다려 보세요."},{"who":"선생님","text":"둘째는 안전띠를 잘 매고 풀리지 않는지 살펴보세요. 타는 동안 손잡이를 꼭 잡아요."},{"who":"선생님","text":"셋째는 떨어질 수 있는 물건은 가지고 타지 않아요. 선생님이 잘 보관하고 있을게요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_basic#8','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',2,'mc','auto','「생각이 달라도 대화로 풀어요」를 듣기 전에 「누가 누구와 대화하고 있을까요?」 같은 활동 질문을 미리 살펴보는 까닭은 무엇인가요?',ARRAY['K3-2-u1-X10']::text[],false,'{"seq":8,"concept":"K3-2-u1-C8","difficulty":2,"kind":"mc","stem":"「생각이 달라도 대화로 풀어요」를 듣기 전에 「누가 누구와 대화하고 있을까요?」 같은 활동 질문을 미리 살펴보는 까닭은 무엇인가요?","options":[{"t":"무엇을 알려고 들을지 정해 대화에 집중하려고","correct":true},{"t":"들을 내용을 미리 다 받아 적어 두려고","mis":"K3-2-u1-X10"},{"t":"듣지 않고도 답을 쓰려고","mis":"K3-2-u1-X10"},{"t":"대화를 들은 뒤에 질문을 지어내려고","mis":"K3-2-u1-X10"}],"explanation":["지도서는 듣기 전에 활동 질문을 안내하라고 해요.","듣는 목적이 생기면 귀가 열려요.","그래서 대화에 집중할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_basic#9','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C9',2,'mc','auto','박민수 박사님이 「자신의 마음을 솔직하게 말해야 해요.」라고 한 까닭은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":9,"concept":"K3-2-u1-C9","difficulty":2,"kind":"mc","stem":"박민수 박사님이 「자신의 마음을 솔직하게 말해야 해요.」라고 한 까닭은 무엇인가요?","options":[{"t":"친구가 내 마음을 오해하지 않고 있는 그대로 이해할 수 있어서","correct":true},{"t":"선생님께 칭찬을 받을 수 있어서","mis":"K3-2-u1-X07"},{"t":"친구와 이야기하지 않아도 되어서","mis":"K3-2-u1-X07"},{"t":"친구를 이길 수 있어서","mis":"K3-2-u1-X07"}],"explanation":["질문 ②의 대답을 다시 들어요.","솔직하게 말하면 오해가 생기지 않아요.","친구가 내 마음을 있는 그대로 이해해요."],"asset":{"type":"speech","turns":[{"who":"이슬기","text":"첫 번째 질문이에요. 친구들과 생각이 달라 문제가 생기면 어떻게 해결해요?"},{"who":"박민수","text":"친구와 계속 이야기하려고 노력해야 해요. 친구 이야기를 집중해서 들으면 생각을 더 알 수 있어요."},{"who":"이슬기","text":"두 번째 질문이에요. 친구와 이야기 나눌 때 주의할 점이 있을까요?"},{"who":"박민수","text":"자신의 마음을 솔직하게 말해야 해요. 그러면 친구가 내 마음을 오해하지 않아요."},{"who":"이슬기","text":"세 번째 질문이에요. 마음을 솔직하게 말하기 어려울 때는요?"},{"who":"박민수","text":"그럴 때에는 선생님께 도움을 요청할 수 있어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_basic#10','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',3,'error','auto','세 친구가 「들은 후」에 할 일을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X12']::text[],false,'{"seq":10,"concept":"K3-2-u1-C8","difficulty":3,"kind":"error","stem":"세 친구가 「들은 후」에 할 일을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「들은 말을 처음부터 끝까지 그대로 다시 옮겨 써.」","correct":true,"mis_target":"K3-2-u1-X12"},{"t":"친구 가 — 「중요한 내용이 무엇인지 생각해.」","mis":"K3-2-u1-X12"},{"t":"친구 다 — 「번호나 화살표 같은 기호를 써서 정리해.」","mis":"K3-2-u1-X12"}],"explanation":["『국어』 51쪽 3번 「들은 후」 칸이에요.","중요한 내용을 생각하고 기호로 정리해요.","그대로 옮겨 쓰는 것은 간추리기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_challenge#1','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',2,'sa','auto','「생각이 달라도 대화로 풀어요」에서 마음을 솔직하게 말하기 어려울 때는 누구에게 도움을 요청할 수 있다고 했나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C9","difficulty":2,"kind":"sa","stem":"「생각이 달라도 대화로 풀어요」에서 마음을 솔직하게 말하기 어려울 때는 누구에게 도움을 요청할 수 있다고 했나요? 세 글자로 쓰세요.","answer":["선생님"],"explanation":["질문 ③의 대답이에요.","「그럴 때에는 ○○○께 도움을 요청할 수 있어요.」예요.","선생님이에요."],"asset":{"type":"speech","turns":[{"who":"이슬기","text":"첫 번째 질문이에요. 친구들과 생각이 달라 문제가 생기면 어떻게 해결해요?"},{"who":"박민수","text":"친구와 계속 이야기하려고 노력해야 해요. 친구 이야기를 집중해서 들으면 생각을 더 알 수 있어요."},{"who":"이슬기","text":"두 번째 질문이에요. 친구와 이야기 나눌 때 주의할 점이 있을까요?"},{"who":"박민수","text":"자신의 마음을 솔직하게 말해야 해요. 그러면 친구가 내 마음을 오해하지 않아요."},{"who":"이슬기","text":"세 번째 질문이에요. 마음을 솔직하게 말하기 어려울 때는요?"},{"who":"박민수","text":"그럴 때에는 선생님께 도움을 요청할 수 있어요."}]},"mis":"K3-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_challenge#2','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C8',2,'ox','auto','중요한 내용을 간추리며 듣는 방법은 듣기 전, 듣기 중, 들은 후로 나누어 생각할 수 있어요.',ARRAY['K3-2-u1-X10']::text[],false,'{"seq":2,"concept":"K3-2-u1-C8","difficulty":2,"kind":"ox","stem":"중요한 내용을 간추리며 듣는 방법은 듣기 전, 듣기 중, 들은 후로 나누어 생각할 수 있어요.","answer":"O","reason_options":[{"t":"듣기 전에는 목적과 예상, 듣기 중에는 표지어와 간단한 기록, 들은 후에는 정리를 하기 때문에","correct":true},{"t":"듣는 동안에만 무엇을 할지 생각하면 되기 때문에","mis":"K3-2-u1-X10"}],"mis":"K3-2-u1-X10","explanation":["『국어』 51쪽 3번 표가 세 칸이에요.","세 단계마다 할 일이 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_challenge#3','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C8',3,'match','auto','『국어』 51쪽 3번의 세 단계와 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u1-C8","difficulty":3,"kind":"match","stem":"『국어』 51쪽 3번의 세 단계와 할 일을 알맞게 이으세요.","pairs":[{"l":"듣기 전","r":"듣는 목적을 생각하고 제목을 보고 들을 내용을 예상한다"},{"l":"듣기 중","r":"표지어에 주의하며 중요한 부분을 간단히 기록한다"},{"l":"들은 후","r":"중요한 내용이 무엇인지 생각하고 기호를 활용해 정리한다"}],"mis":"K3-2-u1-X10","explanation":["목적과 예상은 듣기 전이에요.","표지어와 간단한 기록은 듣기 중이에요.","기호로 정리하는 것은 들은 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_challenge#4','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',3,'mc','auto','『국어활동』 8쪽 「내가 좋아하는 운동」에서 윤찬이가 수영을 좋아하는 까닭을 간추린 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X17','K3-2-u1-X12']::text[],false,'{"seq":4,"concept":"K3-2-u1-C9","difficulty":3,"kind":"mc","stem":"『국어활동』 8쪽 「내가 좋아하는 운동」에서 윤찬이가 수영을 좋아하는 까닭을 간추린 것으로 알맞은 것은 무엇인가요?","options":[{"t":"건강에 좋고, 다칠 일이 별로 없고, 시원해서 기분이 좋다","correct":true},{"t":"팀을 이루어 협동심을 기를 수 있다","mis":"K3-2-u1-X17"},{"t":"골을 넣었을 때 기분이 짜릿하다","mis":"K3-2-u1-X17"},{"t":"나는 수영을 좋아해.","mis":"K3-2-u1-X12"}],"explanation":["말하는 이가 강조하는 내용을 찾아요.","윤찬이는 까닭을 세 가지 말했어요.","협동심과 골은 민이의 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"윤찬","text":"나는 수영을 좋아해. 온몸을 골고루 움직여서 건강에 좋고, 물에서 하니까 다칠 일이 별로 없어. 시원해서 기분도 좋아."},{"who":"민이","text":"나는 축구가 좋아. 팀을 이루어서 하니까 협동심을 기르고 친해질 수 있어. 다리 근육이 튼튼해지고, 골을 넣으면 짜릿해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_challenge#5','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C8',3,'mc','auto','간추리며 잘 듣는 사람의 모습으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X12','K3-2-u1-X11']::text[],false,'{"seq":5,"concept":"K3-2-u1-C8","difficulty":3,"kind":"mc","stem":"간추리며 잘 듣는 사람의 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"전체 요점을 잡으려고 부분과 부분이 어떻게 이어지는지 생각하며 듣는다","correct":true},{"t":"쉽고 재미있는 부분만 골라 듣는다","mis":"K3-2-u1-X13"},{"t":"들은 말을 모두 완전한 문장으로 길게 받아 적는다","mis":"K3-2-u1-X12"},{"t":"주변 소리에 휩쓸려 이것저것 듣는다","mis":"K3-2-u1-X11"}],"explanation":["지도서 102쪽 「나쁜 듣기 습관」을 거꾸로 보면 돼요.","단편적인 사실이 아니라 전체 요점을 잡아요.","쉬운 내용만 듣거나 모두 적으려 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_challenge#6','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',3,'mc','auto','「생각이 달라도 대화로 풀어요」처럼 묻고 답하는 대화를 들을 때 질문과 대답을 짝지어 적으면 좋은 점은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X17']::text[],false,'{"seq":6,"concept":"K3-2-u1-C9","difficulty":3,"kind":"mc","stem":"「생각이 달라도 대화로 풀어요」처럼 묻고 답하는 대화를 들을 때 질문과 대답을 짝지어 적으면 좋은 점은 무엇인가요?","options":[{"t":"짝지은 표가 그대로 중요한 내용을 간추린 것이 된다","correct":true},{"t":"대화를 한 글자도 빼지 않고 적을 수 있다","mis":"K3-2-u1-X12"},{"t":"대답은 적지 않아도 된다","mis":"K3-2-u1-X17"},{"t":"질문을 내 마음대로 바꿀 수 있다","mis":"K3-2-u1-X17"}],"explanation":["질문 하나에 대답 하나가 짝이에요.","짝만 남기면 인사말 같은 것은 저절로 빠져요.","그 표가 간추린 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_challenge#7','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',3,'error','auto','세 친구가 「생각이 달라도 대화로 풀어요」의 대답을 간추려 적었어요. 잘못 간추린 친구는 누구인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":7,"concept":"K3-2-u1-C9","difficulty":3,"kind":"error","stem":"세 친구가 「생각이 달라도 대화로 풀어요」의 대답을 간추려 적었어요. 잘못 간추린 친구는 누구인가요?","options":[{"t":"친구 다 — 대답 ③: 친구에게 무조건 사과함.","correct":true,"mis_target":"K3-2-u1-X07"},{"t":"친구 가 — 대답 ①: 친구와 계속 이야기하려고 노력해야 함.","mis":"K3-2-u1-X07"},{"t":"친구 나 — 대답 ②: 자신의 마음을 솔직하게 말해야 함.","mis":"K3-2-u1-X07"}],"explanation":["대답 ③은 솔직하게 말하기 어려울 때예요.","박사님은 선생님께 도움을 요청하라고 했어요.","친구 다는 들은 내용과 다르게 적었어요."],"asset":{"type":"speech","turns":[{"who":"이슬기","text":"첫 번째 질문이에요. 친구들과 생각이 달라 문제가 생기면 어떻게 해결해요?"},{"who":"박민수","text":"친구와 계속 이야기하려고 노력해야 해요. 친구 이야기를 집중해서 들으면 생각을 더 알 수 있어요."},{"who":"이슬기","text":"두 번째 질문이에요. 친구와 이야기 나눌 때 주의할 점이 있을까요?"},{"who":"박민수","text":"자신의 마음을 솔직하게 말해야 해요. 그러면 친구가 내 마음을 오해하지 않아요."},{"who":"이슬기","text":"세 번째 질문이에요. 마음을 솔직하게 말하기 어려울 때는요?"},{"who":"박민수","text":"그럴 때에는 선생님께 도움을 요청할 수 있어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_challenge#8','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',4,'essay','teacher','『국어활동』 8쪽 「내가 좋아하는 운동」에서 민이가 축구를 좋아하는 까닭을 세 가지로 간추려 쓰세요. 민이의 말을 그대로 옮기지 말고 짧게 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u1-C9","difficulty":4,"kind":"essay","stem":"『국어활동』 8쪽 「내가 좋아하는 운동」에서 민이가 축구를 좋아하는 까닭을 세 가지로 간추려 쓰세요. 민이의 말을 그대로 옮기지 말고 짧게 쓰세요.","answer_guide":{"answer":"예: ① 협동심을 기르고 친구와 친해질 수 있다. ② 다리 근육이 튼튼해지고 체력이 좋아진다. ③ 골을 넣으면 기분이 짜릿하다.","scoring_points":["까닭을 세 가지로 나누었는가","민이가 강조한 내용만 남겼는가","말을 그대로 옮기지 않고 짧게 썼는가"]},"explanation":["말하는 이가 강조하는 내용을 찾아요.","까닭마다 번호를 붙여 나누어요.","짧게 줄여 쓰는 것이 간추리기예요."],"asset":{"type":"speech","turns":[{"who":"윤찬","text":"나는 수영을 좋아해. 온몸을 골고루 움직여서 건강에 좋고, 물에서 하니까 다칠 일이 별로 없어. 시원해서 기분도 좋아."},{"who":"민이","text":"나는 축구가 좋아. 팀을 이루어서 하니까 협동심을 기르고 친해질 수 있어. 다리 근육이 튼튼해지고, 골을 넣으면 짜릿해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_challenge#9','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C8',4,'essay','teacher','학교에서 훈화 말씀이나 안내 방송을 들은 경험을 떠올려, 다음에 그런 말을 들을 때 듣기 전 · 듣기 중 · 들은 후에 내가 할 일을 하나씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C8","difficulty":4,"kind":"essay","stem":"학교에서 훈화 말씀이나 안내 방송을 들은 경험을 떠올려, 다음에 그런 말을 들을 때 듣기 전 · 듣기 중 · 들은 후에 내가 할 일을 하나씩 쓰세요.","answer_guide":{"answer":"예: 듣기 전 — 「운동회 안내」라는 제목을 듣고 언제, 무엇을 준비해야 하는지 알려고 듣기로 정한다. 듣기 중 — 「첫째」, 「둘째」가 들리면 그 뒤의 말을 번호를 붙여 짧게 적는다. 들은 후 — 적은 것을 번호대로 정리하고 궁금한 점은 선생님께 여쭌다.","scoring_points":["세 단계로 나누어 썼는가","듣기 전에 목적이나 예상을 썼는가","듣기 중 표지어·간단한 기록과 들은 후 정리를 썼는가"]},"explanation":["지도서 동기 유발은 훈화 말씀이나 안내를 떠올려요.","세 단계마다 할 일이 달라요.","실제 들을 상황에 맞추어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L06_challenge#10','kor',3,2,'u1','L06','tb_g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',4,'essay','teacher','「생각이 달라도 대화로 풀어요」에서 간추린 세 가지 방법 가운데 하나를 골라, 친구와 생각이 달라 다툰 내 경험에 그 방법을 썼다면 어떻게 되었을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C9","difficulty":4,"kind":"essay","stem":"「생각이 달라도 대화로 풀어요」에서 간추린 세 가지 방법 가운데 하나를 골라, 친구와 생각이 달라 다툰 내 경험에 그 방법을 썼다면 어떻게 되었을지 쓰세요.","answer_guide":{"answer":"예: 나는 쉬는 시간에 놀이를 정하다가 친구와 다툰 적이 있다. 그때 박사님 말씀처럼 친구와 계속 이야기하려고 노력했다면, 친구가 왜 그 놀이를 하고 싶었는지 알게 되어 둘이 번갈아 놀자고 정할 수 있었을 것이다.","scoring_points":["간추린 방법 하나를 바르게 골랐는가","생각이 달라 다툰 내 경험을 썼는가","그 방법을 썼을 때 달라졌을 점을 썼는가"]},"explanation":["먼저 대답 세 가지를 간추려요.","그중 하나를 내 경험에 이어요.","간추린 내용을 생활에 쓰는 연습이에요."],"asset":{"type":"speech","turns":[{"who":"이슬기","text":"첫 번째 질문이에요. 친구들과 생각이 달라 문제가 생기면 어떻게 해결해요?"},{"who":"박민수","text":"친구와 계속 이야기하려고 노력해야 해요. 친구 이야기를 집중해서 들으면 생각을 더 알 수 있어요."},{"who":"이슬기","text":"두 번째 질문이에요. 친구와 이야기 나눌 때 주의할 점이 있을까요?"},{"who":"박민수","text":"자신의 마음을 솔직하게 말해야 해요. 그러면 친구가 내 마음을 오해하지 않아요."},{"who":"이슬기","text":"세 번째 질문이에요. 마음을 솔직하게 말하기 어려울 때는요?"},{"who":"박민수","text":"그럴 때에는 선생님께 도움을 요청할 수 있어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_basic#1','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',1,'mc','auto','「호랑이를 이긴 개미」에서 호랑이가 개미에게 화가 난 까닭은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":1,"concept":"K3-2-u1-C10","difficulty":1,"kind":"mc","stem":"「호랑이를 이긴 개미」에서 호랑이가 개미에게 화가 난 까닭은 무엇인가요?","options":[{"t":"작은 개미가 호랑이를 보고도 무서워하지 않아서","correct":true},{"t":"개미가 호랑이 먹이를 훔쳐서","mis":"K3-2-u1-X07"},{"t":"개미가 숲속의 왕이 되겠다고 해서","mis":"K3-2-u1-X07"},{"t":"호랑이가 배가 고파서","mis":"K3-2-u1-X07"}],"explanation":["『국어』 53쪽 「내용 알기」 (1)번이에요.","호랑이는 모두 자기를 무서워할 거라고 생각했어요.","그런데 작은 개미가 무서워하지 않았어요."],"asset":{"type":"passage","lines":["[장면] 어느 날 숲속에서 호랑이와 개미가 만났어요.","[장면] 호랑이는 숲속의 왕인 자기를 모두 무서워할 거라며 으스댔어요.","[장면] 개미는 힘만 세고 동물들을 괴롭히는 호랑이는 무섭지 않다고 했어요.","[장면] 화가 난 호랑이가 개미를 잡으려 했지만 개미는 요리조리 피했어요.","[장면] 발톱을 잘 피하는 개미 때문에 호랑이는 더 화가 났어요.","[장면] 둘은 다음 날 다시 만나기로 했어요."],"title":"영상 「호랑이를 이긴 개미」 ① — 『국어』 52~53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_basic#2','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',1,'mc','auto','「호랑이를 이긴 개미」에서 개미가 호랑이를 무서워하지 않은 까닭은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":2,"concept":"K3-2-u1-C10","difficulty":1,"kind":"mc","stem":"「호랑이를 이긴 개미」에서 개미가 호랑이를 무서워하지 않은 까닭은 무엇인가요?","options":[{"t":"호랑이가 힘만 세고 동물들을 괴롭혀서","correct":true},{"t":"개미가 호랑이보다 커서","mis":"K3-2-u1-X07"},{"t":"호랑이가 잠들어 있어서","mis":"K3-2-u1-X07"},{"t":"호랑이와 친구라서","mis":"K3-2-u1-X07"}],"explanation":["『국어』 53쪽 (2)번이에요.","개미는 호랑이가 하는 일을 보고 판단했어요.","힘만 세고 괴롭히는 호랑이는 무섭지 않다고 했어요."],"asset":{"type":"passage","lines":["[장면] 어느 날 숲속에서 호랑이와 개미가 만났어요.","[장면] 호랑이는 숲속의 왕인 자기를 모두 무서워할 거라며 으스댔어요.","[장면] 개미는 힘만 세고 동물들을 괴롭히는 호랑이는 무섭지 않다고 했어요.","[장면] 화가 난 호랑이가 개미를 잡으려 했지만 개미는 요리조리 피했어요.","[장면] 발톱을 잘 피하는 개미 때문에 호랑이는 더 화가 났어요.","[장면] 둘은 다음 날 다시 만나기로 했어요."],"title":"영상 「호랑이를 이긴 개미」 ① — 『국어』 52~53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_basic#3','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',1,'sa','auto','「일정한 방향이 없이 요쪽 조쪽으로」라는 뜻의 낱말을 영상 내용에서 찾아 네 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u1-C10","difficulty":1,"kind":"sa","stem":"「일정한 방향이 없이 요쪽 조쪽으로」라는 뜻의 낱말을 영상 내용에서 찾아 네 글자로 쓰세요.","answer":["요리조리"],"explanation":["『국어』 53쪽 「낱말 알기」예요.","개미가 호랑이를 피하는 모습이에요.","요리조리예요."],"asset":{"type":"passage","lines":["[장면] 어느 날 숲속에서 호랑이와 개미가 만났어요.","[장면] 호랑이는 숲속의 왕인 자기를 모두 무서워할 거라며 으스댔어요.","[장면] 개미는 힘만 세고 동물들을 괴롭히는 호랑이는 무섭지 않다고 했어요.","[장면] 화가 난 호랑이가 개미를 잡으려 했지만 개미는 요리조리 피했어요.","[장면] 발톱을 잘 피하는 개미 때문에 호랑이는 더 화가 났어요.","[장면] 둘은 다음 날 다시 만나기로 했어요."],"title":"영상 「호랑이를 이긴 개미」 ① — 『국어』 52~53쪽"},"mis":"K3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_basic#4','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',1,'ox','auto','개미 떼를 만난 뒤에도 호랑이는 다른 동물들 앞에서 큰소리치며 괴롭혔어요.',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":4,"concept":"K3-2-u1-C10","difficulty":1,"kind":"ox","stem":"개미 떼를 만난 뒤에도 호랑이는 다른 동물들 앞에서 큰소리치며 괴롭혔어요.","answer":"X","reason_options":[{"t":"그 뒤로 큰소리치거나 괴롭히지 않게 되었기 때문에","correct":true},{"t":"호랑이는 힘이 세니 달라질 까닭이 없기 때문에","mis":"K3-2-u1-X07"}],"mis":"K3-2-u1-X07","explanation":["『국어』 53쪽 (3)번이에요.","호랑이는 개미 떼에게 혼이 났어요.","그 뒤로 달라졌으니 X예요."],"asset":{"type":"passage","lines":["[장면] 다음 날, 개미 떼가 나타나 호랑이 털 속으로 들어갔어요.","[장면] 호랑이는 가려움을 참지 못해 아무것도 할 수 없었어요.","[장면] 그 뒤로 호랑이는 다른 동물들 앞에서 큰소리치거나 괴롭히지 않았어요."],"title":"영상 「호랑이를 이긴 개미」 ② — 『국어』 53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_basic#5','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',2,'match','auto','『국어』 54쪽 「이야기 간추리기」 (1)번처럼 원인과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C10","difficulty":2,"kind":"match","stem":"『국어』 54쪽 「이야기 간추리기」 (1)번처럼 원인과 결과를 알맞게 이으세요.","pairs":[{"l":"개미가 호랑이를 무서워하지 않고 당당하게 대함","r":"호랑이가 화를 냄"},{"l":"발톱을 잘 피하는 개미","r":"호랑이가 더 화가 남"},{"l":"개미 떼가 나타나 호랑이 털 속으로 들어감","r":"호랑이는 가려움을 참지 못함"}],"mis":"K3-2-u1-X15","explanation":["원인은 먼저 일어난 일, 결과는 그 때문에 생긴 일이에요.","「왜?」에 답하는 것이 원인이에요.","「그래서?」에 답하는 것이 결과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_basic#6','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',2,'mc','auto','「목표물을 맞히지 못하고 빗나가는 발길질」을 뜻하는 낱말은 무엇인가요?',ARRAY['K3-2-u1-X08']::text[],false,'{"seq":6,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"「목표물을 맞히지 못하고 빗나가는 발길질」을 뜻하는 낱말은 무엇인가요?","options":[{"t":"헛발질","correct":true},{"t":"콧방귀","mis":"K3-2-u1-X08"},{"t":"요리조리","mis":"K3-2-u1-X08"},{"t":"발톱","mis":"K3-2-u1-X08"}],"explanation":["『국어』 53쪽 「낱말 알기」예요.","「헛-」은 보람 없이 빗나간다는 뜻을 더해요.","헛발질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_basic#7','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',2,'mc','auto','이야기에서 인물의 특성을 생각하며 중요한 내용을 간추릴 때 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X12']::text[],false,'{"seq":7,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"이야기에서 인물의 특성을 생각하며 중요한 내용을 간추릴 때 알맞은 방법은 무엇인가요?","options":[{"t":"인물이 좋아하는 것과 싫어하는 것을 생각하고, 그에 따라 한 말이나 행동을 찾는다","correct":true},{"t":"인물의 생김새를 자세히 적는다","mis":"K3-2-u1-X13"},{"t":"인물이 한 말을 모두 그대로 옮긴다","mis":"K3-2-u1-X12"},{"t":"가장 재미있는 장면 하나만 남긴다","mis":"K3-2-u1-X13"}],"explanation":["지도서 107쪽 「인물의 특성」 칸이에요.","호랑이는 으스대기를 좋아하고, 개미는 약한 동물을 괴롭히는 것을 싫어해요.","그래서 일어난 중요한 일을 찾아 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_basic#8','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',2,'mc','auto','친구가 소개한 옛이야기에서 잘못된 점은 무엇인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X12']::text[],false,'{"seq":8,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"친구가 소개한 옛이야기에서 잘못된 점은 무엇인가요?","options":[{"t":"일이 일어난 순서가 바뀌어 있다","correct":true},{"t":"등장인물이 너무 많다","mis":"K3-2-u1-X13"},{"t":"토끼가 나와서 재미없다","mis":"K3-2-u1-X13"},{"t":"문장이 너무 짧다","mis":"K3-2-u1-X12"}],"explanation":["지도서 104쪽 동기 유발이에요.","용왕님이 병에 걸린 일이 맨 처음이어야 해요.","순서가 바뀌면 왜 그런 일이 일어났는지 알 수 없어요."],"asset":{"type":"passage","lines":["옛날에 육지에 사는 토끼가 바닷속 용궁으로 구경을 갔어.","토끼는 자라의 등에 올라타고 간을 가지러 육지로 다시 올라갔어.","육지에 도착하자 토끼는 도망가 버렸지.","그런데 용왕님은 큰 병에 걸려서 시름시름 앓았어.","용왕님의 병을 낫게 하려면 토끼의 간이 필요했거든.","자라는 토끼를 등에 태워서 용궁으로 데려왔어."],"title":"친구가 소개한 옛이야기 — 지도서 104쪽 동기 유발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_basic#9','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',2,'mc','auto','『국어』 52쪽에서 「호랑이를 이긴 개미」라는 제목을 보고 예상한 내용으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":9,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"『국어』 52쪽에서 「호랑이를 이긴 개미」라는 제목을 보고 예상한 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"작은 개미가 큰 호랑이와 맞서는 이야기일 것 같다","correct":true},{"t":"개미가 호랑이에게 지는 이야기일 것 같다","mis":"K3-2-u1-X07"},{"t":"호랑이와 개미가 함께 소풍 가는 이야기일 것 같다","mis":"K3-2-u1-X07"},{"t":"호랑이가 개미를 업어 주는 이야기일 것 같다","mis":"K3-2-u1-X07"}],"explanation":["지도서는 제목과 그림으로 내용을 미리 짐작하게 해요.","제목에 「이긴」이 들어 있어요.","개미가 호랑이와 맞서는 이야기를 예상할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_basic#10','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',3,'error','auto','『국어』 55쪽 (2)번처럼 일이 일어난 차례대로 두 일을 이었어요. 차례를 잘못 이은 친구는 누구인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":10,"concept":"K3-2-u1-C10","difficulty":3,"kind":"error","stem":"『국어』 55쪽 (2)번처럼 일이 일어난 차례대로 두 일을 이었어요. 차례를 잘못 이은 친구는 누구인가요?","options":[{"t":"친구 나 — 개미 떼가 털 속으로 들어감 → 호랑이와 개미가 다음 날 다시 만나기로 함","correct":true,"mis_target":"K3-2-u1-X14"},{"t":"친구 가 — 호랑이와 개미가 만남 → 개미가 무서워하지 않아 호랑이가 화가 남","mis":"K3-2-u1-X14"},{"t":"친구 다 — 개미 떼가 털 속으로 들어감 → 호랑이가 큰소리치거나 괴롭히지 않게 됨","mis":"K3-2-u1-X14"}],"explanation":["다음 날 다시 만나기로 한 것이 먼저예요.","그다음 날 개미 떼가 나타났어요.","친구 나는 앞뒤를 바꾸었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_challenge#1','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',2,'sa','auto','「코로 나오는 숨을 막았다가 갑자기 터뜨리면서 불어 내는 소리」를 뜻하는 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C10","difficulty":2,"kind":"sa","stem":"「코로 나오는 숨을 막았다가 갑자기 터뜨리면서 불어 내는 소리」를 뜻하는 낱말을 쓰세요.","answer":["콧방귀"],"explanation":["『국어』 53쪽 「낱말 알기」예요.","남을 깔보며 「흥!」 하고 내는 소리예요.","콧방귀예요."],"mis":"K3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_challenge#2','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',2,'ox','auto','「호랑이는 개미가 자신을 어떻게 대할 것이라 생각했을까요?」는 영상에서 바로 답을 찾을 수 있는 사실 질문이에요.',ARRAY['K3-2-u1-X26']::text[],false,'{"seq":2,"concept":"K3-2-u1-C10","difficulty":2,"kind":"ox","stem":"「호랑이는 개미가 자신을 어떻게 대할 것이라 생각했을까요?」는 영상에서 바로 답을 찾을 수 있는 사실 질문이에요.","answer":"X","reason_options":[{"t":"영상 내용을 바탕으로 생각해야 답할 수 있는 추론 질문이기 때문에","correct":true},{"t":"물음표로 끝나는 질문은 모두 사실 질문이기 때문에","mis":"K3-2-u1-X26"}],"mis":"K3-2-u1-X26","explanation":["『국어』 54쪽 「내용과 연결하기」예요.","사실 질문은 글에서 답을 찾고, 추론 질문은 내용을 바탕으로 생각해요.","호랑이의 생각은 짐작해야 하니 추론 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_challenge#3','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',3,'mc','auto','「호랑이를 이긴 개미」를 잘 이해했는지 확인하는 사실 질문으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X26']::text[],false,'{"seq":3,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"「호랑이를 이긴 개미」를 잘 이해했는지 확인하는 사실 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"개미는 어떤 방법으로 호랑이를 이길 수 있었나요?","correct":true},{"t":"개미가 생각하는 ‘숲속의 왕’은 어떤 모습일까요?","mis":"K3-2-u1-X26"},{"t":"내가 개미라면 호랑이에게 무슨 말을 했을까요?","mis":"K3-2-u1-X26"},{"t":"호랑이는 개미가 자신을 어떻게 대할 것이라 생각했을까요?","mis":"K3-2-u1-X26"}],"explanation":["사실 질문은 영상에서 답을 바로 찾을 수 있어요.","개미 떼가 털 속으로 들어간 방법이 영상에 나와요.","나머지는 추론이나 감상 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_challenge#4','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',3,'mc','auto','짝이 「개미가 호랑이를 이긴 방법은 무엇인가요?」라고 물었어요. 알맞은 대답은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":4,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"짝이 「개미가 호랑이를 이긴 방법은 무엇인가요?」라고 물었어요. 알맞은 대답은 무엇인가요?","options":[{"t":"많은 개미 떼가 호랑이 털 속으로 들어가 호랑이를 간지럽혔습니다.","correct":true},{"t":"개미가 호랑이보다 힘이 세서 이겼습니다.","mis":"K3-2-u1-X07"},{"t":"개미가 호랑이 발톱을 물었습니다.","mis":"K3-2-u1-X07"},{"t":"호랑이가 잠든 사이에 도망쳤습니다.","mis":"K3-2-u1-X07"}],"explanation":["『국어』 54쪽 (2)번 예시예요.","개미 혼자가 아니라 개미 떼였어요.","털 속에서 간지럽혀 호랑이가 아무것도 못 했어요."],"asset":{"type":"passage","lines":["[장면] 다음 날, 개미 떼가 나타나 호랑이 털 속으로 들어갔어요.","[장면] 호랑이는 가려움을 참지 못해 아무것도 할 수 없었어요.","[장면] 그 뒤로 호랑이는 다른 동물들 앞에서 큰소리치거나 괴롭히지 않았어요."],"title":"영상 「호랑이를 이긴 개미」 ② — 『국어』 53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_challenge#5','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',3,'mc','auto','일어난 일의 차례를 생각하며 이야기를 간추리는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X14','K3-2-u1-X12']::text[],false,'{"seq":5,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"일어난 일의 차례를 생각하며 이야기를 간추리는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"장면마다 누가 어떤 일을 했는지 생각하고, 순서에 따라 중요한 일을 정리한다","correct":true},{"t":"기억나는 장면부터 아무 순서로 적는다","mis":"K3-2-u1-X14"},{"t":"마지막 장면만 자세히 적는다","mis":"K3-2-u1-X14"},{"t":"모든 장면을 대사까지 그대로 옮긴다","mis":"K3-2-u1-X12"}],"explanation":["지도서 107쪽 「일어난 일의 차례」 칸이에요.","시간이나 장소에 따라 장면을 나누어요.","순서대로 중요한 일만 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_challenge#6','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',3,'mc','auto','『국어활동』 9쪽처럼 「갈대와 떡갈나무」를 계절에 따라 간추렸어요. 떡갈나무의 마음이 어떻게 달라졌는지 간추린 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X14','K3-2-u1-X15']::text[],false,'{"seq":6,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"『국어활동』 9쪽처럼 「갈대와 떡갈나무」를 계절에 따라 간추렸어요. 떡갈나무의 마음이 어떻게 달라졌는지 간추린 것으로 알맞은 것은 무엇인가요?","options":[{"t":"자신만만하다가 기둥이 부러진 뒤 후회했다","correct":true},{"t":"처음부터 끝까지 후회했다","mis":"K3-2-u1-X14"},{"t":"처음에는 후회하다가 나중에 자신만만해졌다","mis":"K3-2-u1-X14"},{"t":"갈대를 부러워하다가 자랑스러워했다","mis":"K3-2-u1-X15"}],"explanation":["봄·여름에는 자랑스럽고 자신만만했어요.","가을에 바람에 기둥이 부러졌어요.","겨울에 누워서 후회했어요."],"asset":{"type":"passage","lines":["봄 — 떡갈나무는 자기 모습이 자랑스러웠고, 갈대는 작은 바람에도 흔들렸다.","여름 — 떡갈나무 잎이 무성해져 더욱 자신만만해졌고, 갈대는 조용히 자리를 지켰다.","가을 — 바람이 거세도 떡갈나무는 버티려 했지만, 바람에 기둥이 부러졌다.","겨울 — 부러진 떡갈나무는 누워서 후회했고, 갈대는 때로는 흔들릴 줄도 알아야 한다고 말했다."],"title":"「갈대와 떡갈나무」를 계절에 따라 간추린 것 — 『국어활동』 9쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_challenge#7','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',3,'error','auto','세 친구가 「호랑이를 이긴 개미」를 한 문장으로 간추렸어요. 중요한 내용이 빠져 무슨 이야기인지 알 수 없는 친구는 누구인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":7,"concept":"K3-2-u1-C10","difficulty":3,"kind":"error","stem":"세 친구가 「호랑이를 이긴 개미」를 한 문장으로 간추렸어요. 중요한 내용이 빠져 무슨 이야기인지 알 수 없는 친구는 누구인가요?","options":[{"t":"친구 다 — 「호랑이와 개미가 숲에서 만났다.」","correct":true,"mis_target":"K3-2-u1-X14"},{"t":"친구 가 — 「으스대던 호랑이가 개미 떼에게 혼난 뒤 다른 동물을 괴롭히지 않게 되었다.」","mis":"K3-2-u1-X14"},{"t":"친구 나 — 「개미를 무시한 호랑이가 개미 떼에게 간지럼을 당하고 큰소리치지 않게 되었다.」","mis":"K3-2-u1-X14"}],"explanation":["지도서는 너무 간단히 줄여 중요한 내용이 빠지는 것을 잘못으로 들어요.","누가 왜 무엇을 해서 어떻게 되었는지가 남아야 해요.","친구 다는 처음 장면만 남겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_challenge#8','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',4,'essay','teacher','인물의 특성이나 일이 일어난 차례를 생각하며 「호랑이를 이긴 개미」의 중요한 내용을 한 편의 이야기가 되도록 간추려 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u1-C10","difficulty":4,"kind":"essay","stem":"인물의 특성이나 일이 일어난 차례를 생각하며 「호랑이를 이긴 개미」의 중요한 내용을 한 편의 이야기가 되도록 간추려 쓰세요.","answer_guide":{"answer":"예: 어느 날 숲속에서 호랑이와 개미가 만났다. 숲속의 왕이라고 으스대던 호랑이는 개미가 자기를 무서워하지 않자 화를 내며 잡으려 했다. 개미가 요리조리 피하자 더 화가 난 호랑이는 다음 날 다시 만나기로 했다. 다음 날 개미 떼가 호랑이 털 속으로 들어가자 호랑이는 간지러워 아무것도 할 수 없었다. 그 뒤로 호랑이는 다른 동물들 앞에서 큰소리치거나 괴롭히지 않았다.","scoring_points":["인물의 특성(으스대는 호랑이·당당한 개미)이 드러나는가","일이 일어난 차례대로 썼는가","처음과 끝이 이어지는 한 편의 이야기가 되었는가"]},"explanation":["지도서 108쪽 「이야기 간추리기 예시」를 떠올려요.","중요한 일을 차례대로 이어요.","읽는 사람이 한 편의 이야기로 알아들을 수 있어야 해요."],"asset":{"type":"passage","lines":["[장면] 다음 날, 개미 떼가 나타나 호랑이 털 속으로 들어갔어요.","[장면] 호랑이는 가려움을 참지 못해 아무것도 할 수 없었어요.","[장면] 그 뒤로 호랑이는 다른 동물들 앞에서 큰소리치거나 괴롭히지 않았어요."],"title":"영상 「호랑이를 이긴 개미」 ② — 『국어』 53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_challenge#9','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',4,'essay','teacher','『국어』 55쪽 「다른 글과 연결하기」처럼 친구들에게 들려주고 싶은 옛이야기 한 편을 골라 제목, 중요한 내용, 들려주고 싶은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C10","difficulty":4,"kind":"essay","stem":"『국어』 55쪽 「다른 글과 연결하기」처럼 친구들에게 들려주고 싶은 옛이야기 한 편을 골라 제목, 중요한 내용, 들려주고 싶은 까닭을 쓰세요.","answer_guide":{"answer":"예: 제목 — 「해와 달이 된 오누이」. 중요한 내용 — 떡을 팔고 오던 어머니를 잡아먹은 호랑이가 오누이까지 노리자, 오누이는 나무 위로 올라가 하늘에서 내려온 동아줄을 타고 해와 달이 되었다. 까닭 — 어려울 때 지혜를 모으면 이겨 낼 수 있다는 것을 알려 주고 싶어서이다.","scoring_points":["제목을 밝혔는가","중요한 내용을 차례대로 간추렸는가","들려주고 싶은 까닭을 썼는가"]},"explanation":["지도서 109쪽 활동지 꼴이에요.","인물과 일어난 일의 차례를 먼저 정리해요.","그것을 바탕으로 짧게 간추려 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L07_challenge#10','kor',3,2,'u1','L07','tb_g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',4,'essay','teacher','「호랑이를 이긴 개미」에서 인상 깊었던 부분을 하나 고르고, 그렇게 생각한 까닭을 쓰세요. 이 이야기가 친구들에게 어떤 깨달음을 줄 수 있는지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C10","difficulty":4,"kind":"essay","stem":"「호랑이를 이긴 개미」에서 인상 깊었던 부분을 하나 고르고, 그렇게 생각한 까닭을 쓰세요. 이 이야기가 친구들에게 어떤 깨달음을 줄 수 있는지도 쓰세요.","answer_guide":{"answer":"예: 호랑이가 개미 떼에게 혼이 난 부분이 인상 깊었다. 큰 호랑이도 작은 개미들이 힘을 모으자 꼼짝 못 했기 때문이다. 이 이야기는 상대가 작다고 무시하면 안 된다는 것과, 힘을 합치면 어려운 일도 해낼 수 있다는 깨달음을 준다.","scoring_points":["인상 깊었던 부분을 밝혔는가","그렇게 생각한 까닭을 썼는가","이야기가 주는 깨달음을 썼는가"]},"explanation":["지도서 108쪽 「동영상을 본 느낌 나누기」예요.","인상 깊은 부분은 사람마다 다를 수 있어요.","까닭을 함께 말해야 친구가 이해해요."],"asset":{"type":"passage","lines":["[장면] 다음 날, 개미 떼가 나타나 호랑이 털 속으로 들어갔어요.","[장면] 호랑이는 가려움을 참지 못해 아무것도 할 수 없었어요.","[장면] 그 뒤로 호랑이는 다른 동물들 앞에서 큰소리치거나 괴롭히지 않았어요."],"title":"영상 「호랑이를 이긴 개미」 ② — 『국어』 53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_basic#1','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',1,'mc','auto','「우리 지역의 자랑거리」에 나온 자랑거리를 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":1,"concept":"K3-2-u1-C11","difficulty":1,"kind":"mc","stem":"「우리 지역의 자랑거리」에 나온 자랑거리를 바르게 모은 것은 무엇인가요?","options":[{"t":"홍천 옥수수, 울릉도 오징어, 전주 한지, 공주 알밤","correct":true},{"t":"홍천 옥수수, 가평 잣, 전주 한지, 공주 알밤","mis":"K3-2-u1-X07"},{"t":"상주 곶감, 울릉도 오징어, 보령 김, 공주 알밤","mis":"K3-2-u1-X07"},{"t":"홍천 옥수수, 울릉도 오징어, 순천 딸기, 전주 한지","mis":"K3-2-u1-X07"}],"explanation":["『국어』 57쪽 「내용 알기」 (1)번이에요.","참가자는 네 명이었어요.","가평 잣·상주 곶감·보령 김·순천 딸기는 동기 유발에서 본 특산물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_basic#2','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',1,'mc','auto','「우리 지역의 자랑거리」에서 울릉도 오징어를 말리면 어떤 맛이 난다고 했나요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":2,"concept":"K3-2-u1-C11","difficulty":1,"kind":"mc","stem":"「우리 지역의 자랑거리」에서 울릉도 오징어를 말리면 어떤 맛이 난다고 했나요?","options":[{"t":"고소하고 씹을수록 약간의 단맛이 난다","correct":true},{"t":"달고 쫀득쫀득하다","mis":"K3-2-u1-X17"},{"t":"질기고 오래 변하지 않는다","mis":"K3-2-u1-X17"},{"t":"달고 단단해서 오래 보관할 수 있다","mis":"K3-2-u1-X17"}],"explanation":["『국어』 57쪽 (2)번이에요.","달고 쫀득쫀득한 것은 홍천 옥수수예요.","울릉도 오징어는 고소하고 씹을수록 단맛이 나요."],"asset":{"type":"speech","turns":[{"who":"기자","text":"여기는 ‘우리 지역의 자랑거리’를 찾는 현장입니다. 첫 번째 참가자는 홍천 옥수수입니다."},{"who":"홍천 옥수수","text":"제가 온 강원특별자치도 홍천군은 낮과 밤의 온도 차이가 크고 공기가 깨끗해요. 달고 쫀득쫀득한 맛을 자랑하지요."},{"who":"기자","text":"이어서 두 번째 참가자인 울릉도 오징어입니다."},{"who":"울릉도 오징어","text":"저는 경상북도 울릉군 울릉도에서 왔어요. 바닷물이 맑고 깨끗해 해산물이 많아요. 저를 말리면 고소하고 씹을수록 약간 단맛이 나요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_basic#3','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',1,'sa','auto','「식물을 심어서 가꾸는 것」을 뜻하는 낱말을 「우리 지역의 자랑거리」에서 찾아 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u1-C11","difficulty":1,"kind":"sa","stem":"「식물을 심어서 가꾸는 것」을 뜻하는 낱말을 「우리 지역의 자랑거리」에서 찾아 두 글자로 쓰세요.","answer":["재배"],"explanation":["『국어』 57쪽 「낱말 알기」예요.","공주 알밤은 깨끗한 공기와 물, 흙으로 ○○해요.","재배예요."],"asset":{"type":"speech","turns":[{"who":"전주 한지","text":"저는 전북특별자치도 전주시에서 온 한지예요. 우리나라 고유의 방법으로 만든 종이를 한지라고 해요."},{"who":"전주 한지","text":"닥나무와 깨끗한 물, 장인들의 노력으로 만들어져 질기고 오랜 시간이 흘러도 변하지 않아요."},{"who":"기자","text":"마지막 참가자로 충청남도 공주시에서 온 공주 알밤이 있었네요."},{"who":"공주 알밤","text":"저는 깨끗한 공기와 물, 흙으로 재배해 달고 고소해요. 단단해서 오래 보관할 수도 있어요."},{"who":"기자","text":"모두 지역의 자랑거리가 될 자격이 충분합니다. 여러분이 사는 곳에는 어떤 자랑거리가 있나요?"}]},"mis":"K3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_basic#4','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',1,'ox','auto','이야기를 들으면서 이해되지 않는 낱말이 나오면 책 한쪽에 써 두었다가 질문하면 좋아요.',ARRAY['K3-2-u1-X08']::text[],false,'{"seq":4,"concept":"K3-2-u1-C11","difficulty":1,"kind":"ox","stem":"이야기를 들으면서 이해되지 않는 낱말이 나오면 책 한쪽에 써 두었다가 질문하면 좋아요.","answer":"O","reason_options":[{"t":"들은 뒤에 뜻을 확인하면 내용을 더 잘 이해할 수 있기 때문에","correct":true},{"t":"모르는 낱말은 그냥 넘겨도 내용을 아는 데 아무 상관이 없기 때문에","mis":"K3-2-u1-X08"}],"mis":"K3-2-u1-X08","explanation":["지도서 111쪽의 안내예요.","모르는 낱말 때문에 중요한 내용을 놓칠 수 있어요.","써 두었다가 묻고, 국어사전이나 앞뒤 말로 뜻을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_basic#5','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',2,'match','auto','『국어』 58쪽 「내용 간추리기」에서 네 자랑거리와 「사는 곳」을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C11","difficulty":2,"kind":"match","stem":"『국어』 58쪽 「내용 간추리기」에서 네 자랑거리와 「사는 곳」을 알맞게 이으세요.","pairs":[{"l":"홍천 옥수수","r":"강원특별자치도 홍천군"},{"l":"울릉도 오징어","r":"경상북도 울릉군 울릉도"},{"l":"전주 한지","r":"전북특별자치도 전주시"},{"l":"공주 알밤","r":"충청남도 공주시"}],"mis":"K3-2-u1-X17","explanation":["이야기를 나누어 정리하는 첫 칸이 「사는 곳」이에요.","참가자마다 자기가 온 곳을 먼저 말했어요.","이름 앞에 지역 이름이 붙어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_basic#6','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',2,'mc','auto','『국어』 58쪽 표에서 전주 한지의 「만드는 방법」 칸에 들어갈 말은 무엇인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":6,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"『국어』 58쪽 표에서 전주 한지의 「만드는 방법」 칸에 들어갈 말은 무엇인가요?","options":[{"t":"닥나무와 깨끗한 물을 이용해 장인들의 노력으로 만듦","correct":true},{"t":"깨끗한 공기와 물, 흙으로 재배함","mis":"K3-2-u1-X17"},{"t":"낮과 밤의 온도 차가 크고 공기가 깨끗함","mis":"K3-2-u1-X17"},{"t":"바닷물이 맑고 깨끗함","mis":"K3-2-u1-X17"}],"explanation":["전주 한지는 먹는 것이 아니라 종이예요.","그래서 「맛」 대신 「만드는 방법」과 「특성」 칸이 있어요.","닥나무·깨끗한 물·장인들의 노력이에요."],"asset":{"type":"speech","turns":[{"who":"전주 한지","text":"저는 전북특별자치도 전주시에서 온 한지예요. 우리나라 고유의 방법으로 만든 종이를 한지라고 해요."},{"who":"전주 한지","text":"닥나무와 깨끗한 물, 장인들의 노력으로 만들어져 질기고 오랜 시간이 흘러도 변하지 않아요."},{"who":"기자","text":"마지막 참가자로 충청남도 공주시에서 온 공주 알밤이 있었네요."},{"who":"공주 알밤","text":"저는 깨끗한 공기와 물, 흙으로 재배해 달고 고소해요. 단단해서 오래 보관할 수도 있어요."},{"who":"기자","text":"모두 지역의 자랑거리가 될 자격이 충분합니다. 여러분이 사는 곳에는 어떤 자랑거리가 있나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_basic#7','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',2,'mc','auto','「어떤 일을 오랫동안 해 와서 손으로 물건을 잘 만들고 고치는 기술이 뛰어난 사람」을 뜻하는 낱말은 무엇인가요?',ARRAY['K3-2-u1-X08']::text[],false,'{"seq":7,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"「어떤 일을 오랫동안 해 와서 손으로 물건을 잘 만들고 고치는 기술이 뛰어난 사람」을 뜻하는 낱말은 무엇인가요?","options":[{"t":"장인","correct":true},{"t":"해산물","mis":"K3-2-u1-X08"},{"t":"재배","mis":"K3-2-u1-X08"},{"t":"참가자","mis":"K3-2-u1-X08"}],"explanation":["『국어』 57쪽 「낱말 알기」예요.","전주 한지는 장인들의 노력으로 만들어져요.","오랫동안 전통 한지를 만들어 온 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_basic#8','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',2,'mc','auto','「우리 지역의 자랑거리」를 들으며 간추리는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13','K3-2-u1-X10']::text[],false,'{"seq":8,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"「우리 지역의 자랑거리」를 들으며 간추리는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"내용을 몇 가지로 나누어 간단히 쓰고, 인상 깊은 부분이나 떠오른 생각도 짧게 쓴다","correct":true},{"t":"기자와 참가자의 말을 모두 그대로 받아 적는다","mis":"K3-2-u1-X12"},{"t":"가장 재미있는 참가자의 말만 적는다","mis":"K3-2-u1-X13"},{"t":"다 들은 뒤에 기억나는 대로 한꺼번에 적는다","mis":"K3-2-u1-X10"}],"explanation":["지도서 111쪽 「활동의 유의점」이에요.","「첫째」, 「둘째」, 「이것은」 같은 말에도 주의해요.","인상 깊은 부분이나 생각, 느낌도 간단히 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_basic#9','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',2,'mc','auto','『국어』 56쪽 「경험 떠올리기」에서 우리 지역의 자랑거리를 떠올릴 때 생각하면 좋은 것은 무엇인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":9,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"『국어』 56쪽 「경험 떠올리기」에서 우리 지역의 자랑거리를 떠올릴 때 생각하면 좋은 것은 무엇인가요?","options":[{"t":"우리 지역에 있는 장소, 음식, 동물이나 식물 가운데 널리 알려진 것","correct":true},{"t":"우리 집에만 있는 물건","mis":"K3-2-u1-X17"},{"t":"다른 나라의 유명한 장소","mis":"K3-2-u1-X17"},{"t":"내가 가장 싫어하는 음식","mis":"K3-2-u1-X17"}],"explanation":["56쪽 날개의 안내예요.","예를 들어 부산이라면 해운대, 동백꽃, 자갈치 시장을 떠올릴 수 있어요.","널리 알려진 것이 자랑거리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_basic#10','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',3,'error','auto','세 친구가 「우리 지역의 자랑거리」를 간추린 내용이 서로 달라요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X16']::text[],false,'{"seq":10,"concept":"K3-2-u1-C11","difficulty":3,"kind":"error","stem":"세 친구가 「우리 지역의 자랑거리」를 간추린 내용이 서로 달라요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「내 것과 다르니까 너희가 간추린 것은 틀렸어.」","correct":true,"mis_target":"K3-2-u1-X16"},{"t":"친구 가 — 「나는 맛을 알려 주려고 맛만 간추렸어.」","mis":"K3-2-u1-X16"},{"t":"친구 다 — 「나는 사는 곳과 자랑거리로 나누어 간추렸어.」","mis":"K3-2-u1-X16"}],"explanation":["지도서는 목적이나 방법에 따라 간추린 결과가 달라질 수 있다고 해요.","다르다고 틀린 것은 아니에요.","무엇을 하려고 간추렸는지 먼저 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_challenge#1','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',2,'sa','auto','울릉도 오징어가 말한 전복, 미역, 다시마처럼 「바다에서 나는 모든 동물과 식물」을 뜻하는 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C11","difficulty":2,"kind":"sa","stem":"울릉도 오징어가 말한 전복, 미역, 다시마처럼 「바다에서 나는 모든 동물과 식물」을 뜻하는 낱말을 쓰세요.","answer":["해산물"],"explanation":["『국어』 57쪽 「낱말 알기」예요.","울릉도 주변은 바닷물이 맑고 깨끗해 ○○○이 많아요.","해산물이에요."],"mis":"K3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_challenge#2','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',2,'ox','auto','이야기를 간추리는 것은 내용을 그대로 옮겨 쓰는 것이 아니라 자신의 말로 다시 짓는 일이에요.',ARRAY['K3-2-u1-X12']::text[],false,'{"seq":2,"concept":"K3-2-u1-C11","difficulty":2,"kind":"ox","stem":"이야기를 간추리는 것은 내용을 그대로 옮겨 쓰는 것이 아니라 자신의 말로 다시 짓는 일이에요.","answer":"O","reason_options":[{"t":"중요한 내용을 골라 내 말로 짜임새 있게 다시 정리하기 때문에","correct":true},{"t":"들은 말을 빠짐없이 옮겨야 정확하기 때문에","mis":"K3-2-u1-X12"}],"mis":"K3-2-u1-X12","explanation":["지도서는 간추리기를 자신의 언어로 재창조하는 또 다른 창작이라고 해요.","그대로 옮겨 쓰지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_challenge#3','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',3,'mc','auto','홍천 옥수수가 우리 지역의 자랑거리가 되어야 한다고 말한 까닭을 바르게 간추린 것은 무엇인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":3,"concept":"K3-2-u1-C11","difficulty":3,"kind":"mc","stem":"홍천 옥수수가 우리 지역의 자랑거리가 되어야 한다고 말한 까닭을 바르게 간추린 것은 무엇인가요?","options":[{"t":"낮과 밤의 온도 차가 크고 공기가 깨끗한 곳에서 자라 달고 쫀득쫀득해서","correct":true},{"t":"바닷물이 맑고 깨끗한 곳에서 자라서","mis":"K3-2-u1-X17"},{"t":"단단해서 오래 보관할 수 있어서","mis":"K3-2-u1-X17"},{"t":"장인들이 오랫동안 만들어 와서","mis":"K3-2-u1-X17"}],"explanation":["지도서는 네 참가자가 자랑거리가 되어야 한다고 말한 까닭을 각각 정리하게 해요.","홍천 옥수수의 까닭은 「환경」과 「맛」이에요.","다른 참가자의 까닭과 섞지 않아요."],"asset":{"type":"speech","turns":[{"who":"기자","text":"여기는 ‘우리 지역의 자랑거리’를 찾는 현장입니다. 첫 번째 참가자는 홍천 옥수수입니다."},{"who":"홍천 옥수수","text":"제가 온 강원특별자치도 홍천군은 낮과 밤의 온도 차이가 크고 공기가 깨끗해요. 달고 쫀득쫀득한 맛을 자랑하지요."},{"who":"기자","text":"이어서 두 번째 참가자인 울릉도 오징어입니다."},{"who":"울릉도 오징어","text":"저는 경상북도 울릉군 울릉도에서 왔어요. 바닷물이 맑고 깨끗해 해산물이 많아요. 저를 말리면 고소하고 씹을수록 약간 단맛이 나요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_challenge#4','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',3,'mc','auto','공주 알밤의 「특성」 칸에 들어갈 말로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":4,"concept":"K3-2-u1-C11","difficulty":3,"kind":"mc","stem":"공주 알밤의 「특성」 칸에 들어갈 말로 알맞은 것은 무엇인가요?","options":[{"t":"달고 고소하며 단단해서 오래 보관할 수 있음","correct":true},{"t":"질기고 오랜 시간이 흘러도 변하지 않음","mis":"K3-2-u1-X17"},{"t":"씹을수록 약간의 단맛이 남","mis":"K3-2-u1-X17"},{"t":"깨끗한 공기와 물, 흙으로 재배함","mis":"K3-2-u1-X17"}],"explanation":["『국어』 57쪽 (3)번과 58쪽 표예요.","「깨끗한 공기와 물, 흙으로 재배함」은 환경 칸이에요.","특성은 달고 고소하며 단단해 오래 보관할 수 있는 것이에요."],"asset":{"type":"speech","turns":[{"who":"전주 한지","text":"저는 전북특별자치도 전주시에서 온 한지예요. 우리나라 고유의 방법으로 만든 종이를 한지라고 해요."},{"who":"전주 한지","text":"닥나무와 깨끗한 물, 장인들의 노력으로 만들어져 질기고 오랜 시간이 흘러도 변하지 않아요."},{"who":"기자","text":"마지막 참가자로 충청남도 공주시에서 온 공주 알밤이 있었네요."},{"who":"공주 알밤","text":"저는 깨끗한 공기와 물, 흙으로 재배해 달고 고소해요. 단단해서 오래 보관할 수도 있어요."},{"who":"기자","text":"모두 지역의 자랑거리가 될 자격이 충분합니다. 여러분이 사는 곳에는 어떤 자랑거리가 있나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_challenge#5','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',3,'mc','auto','「우리 지역의 자랑거리」를 듣기 전에 하면 좋은 일을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u1-X10','K3-2-u1-X12']::text[],false,'{"seq":5,"concept":"K3-2-u1-C11","difficulty":3,"kind":"mc","stem":"「우리 지역의 자랑거리」를 듣기 전에 하면 좋은 일을 바르게 모은 것은 무엇인가요?","options":[{"t":"듣는 목적 생각하기, 아는 내용이나 관련 경험 떠올리기, 간추릴 방법 생각하기","correct":true},{"t":"들을 내용 미리 다 적기, 듣는 목적 생각하기, 궁금한 점 정리하기","mis":"K3-2-u1-X10"},{"t":"기호로 정리하기, 다시 듣기, 발표하기","mis":"K3-2-u1-X10"},{"t":"들은 말 그대로 옮겨 적기, 제목 지우기, 듣는 목적 생각하기","mis":"K3-2-u1-X12"}],"explanation":["지도서 110쪽 「활동의 유의점」이에요.","듣기 전에는 목적·경험·방법을 생각해요.","기호로 정리하기는 들은 후에 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_challenge#6','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',3,'mc','auto','『국어』 59쪽 (2)번에서 「우리 지역의 자랑거리」를 떠올리며 쓴 궁금한 점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":6,"concept":"K3-2-u1-C11","difficulty":3,"kind":"mc","stem":"『국어』 59쪽 (2)번에서 「우리 지역의 자랑거리」를 떠올리며 쓴 궁금한 점으로 알맞은 것은 무엇인가요?","options":[{"t":"한지로 만든 책을 실제로 읽으면 어떤 느낌이 들지 궁금해요.","correct":true},{"t":"홍천 옥수수는 달고 쫀득쫀득해요.","mis":"K3-2-u1-X17"},{"t":"울릉도 오징어는 경상북도에서 왔어요.","mis":"K3-2-u1-X17"},{"t":"공주 알밤은 단단해요.","mis":"K3-2-u1-X17"}],"explanation":["궁금한 점은 들은 내용에서 더 알고 싶은 것이에요.","들은 내용을 그대로 적은 것은 궁금한 점이 아니에요.","「다른 지역의 옥수수 맛은 어떨지 궁금해요.」도 좋은 예예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_challenge#7','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',3,'match','auto','간추리는 목적에 따라 「우리 지역의 자랑거리」에서 남길 내용이 달라져요. 목적과 남길 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u1-C11","difficulty":3,"kind":"match","stem":"간추리는 목적에 따라 「우리 지역의 자랑거리」에서 남길 내용이 달라져요. 목적과 남길 내용을 알맞게 이으세요.","pairs":[{"l":"간식으로 무엇을 맛볼지 고르려고","r":"옥수수·오징어·알밤의 맛"},{"l":"지도에 자랑거리를 표시하려고","r":"네 자랑거리의 사는 곳"},{"l":"오래 두고 쓸 종이를 찾으려고","r":"전주 한지의 특성"}],"mis":"K3-2-u1-X17","explanation":["목적이 다르면 남길 것도 달라요.","맛을 고르려면 맛, 지도에는 사는 곳이 필요해요.","종이를 찾으려면 한지의 특성을 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_challenge#8','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',4,'essay','teacher','『국어』 59쪽 「자신과 관련짓기」 (1)번처럼 「우리 지역의 자랑거리」에서 기억에 남는 부분을 찾고, 그 부분에 대한 내 생각이나 느낌을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u1-C11","difficulty":4,"kind":"essay","stem":"『국어』 59쪽 「자신과 관련짓기」 (1)번처럼 「우리 지역의 자랑거리」에서 기억에 남는 부분을 찾고, 그 부분에 대한 내 생각이나 느낌을 쓰세요.","answer_guide":{"answer":"예: 기억에 남는 부분 — 우리나라 고유의 방법으로 만든 종이가 한지라는 것을 새롭게 알았다. 생각이나 느낌 — 오랜 시간이 흘러도 변하지 않는 종이를 장인들이 손으로 만든다는 것이 놀라웠고, 전주 한지에 대해 더 알고 싶다.","scoring_points":["기억에 남는 부분을 밝혔는가","그 부분에 대한 생각이나 느낌을 썼는가","들은 내용을 그대로 옮기지 않고 간단히 정리했는가"]},"explanation":["기억에 남는 부분은 사람마다 달라요.","내 생각이나 느낌을 덧붙여요.","쓴 글은 짝이나 모둠의 글과 견주어 봐요."],"asset":{"type":"speech","turns":[{"who":"전주 한지","text":"저는 전북특별자치도 전주시에서 온 한지예요. 우리나라 고유의 방법으로 만든 종이를 한지라고 해요."},{"who":"전주 한지","text":"닥나무와 깨끗한 물, 장인들의 노력으로 만들어져 질기고 오랜 시간이 흘러도 변하지 않아요."},{"who":"기자","text":"마지막 참가자로 충청남도 공주시에서 온 공주 알밤이 있었네요."},{"who":"공주 알밤","text":"저는 깨끗한 공기와 물, 흙으로 재배해 달고 고소해요. 단단해서 오래 보관할 수도 있어요."},{"who":"기자","text":"모두 지역의 자랑거리가 될 자격이 충분합니다. 여러분이 사는 곳에는 어떤 자랑거리가 있나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_challenge#9','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',4,'essay','teacher','『국어』 58쪽처럼 네 자랑거리 가운데 두 가지를 골라 「사는 곳」과 「자랑거리」(환경·맛 또는 만드는 방법·특성)로 나누어 정리하세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C11","difficulty":4,"kind":"essay","stem":"『국어』 58쪽처럼 네 자랑거리 가운데 두 가지를 골라 「사는 곳」과 「자랑거리」(환경·맛 또는 만드는 방법·특성)로 나누어 정리하세요.","answer_guide":{"answer":"예: 홍천 옥수수 — 사는 곳: 강원특별자치도 홍천군 / 환경: 낮과 밤의 온도 차가 크고 공기가 깨끗함 / 맛: 달고 쫀득쫀득함. 전주 한지 — 사는 곳: 전북특별자치도 전주시 / 만드는 방법: 닥나무와 깨끗한 물, 장인들의 노력 / 특성: 질기고 오랜 시간이 흘러도 변하지 않음.","scoring_points":["두 자랑거리를 골랐는가","사는 곳을 바르게 썼는가","자랑거리를 알맞은 칸으로 나누어 짧게 썼는가"]},"explanation":["내용을 나누어 정리하면 한눈에 보여요.","칸 이름에 맞는 내용만 넣어요.","들은 말을 그대로 옮기지 않고 짧게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L09_challenge#10','kor',3,2,'u1','L09','tb_g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',4,'essay','teacher','「우리 지역의 자랑거리」처럼 내가 사는 지역의 자랑거리 하나를 골라, 사는 곳과 자랑거리를 나누어 소개하는 짧은 글을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C11","difficulty":4,"kind":"essay","stem":"「우리 지역의 자랑거리」처럼 내가 사는 지역의 자랑거리 하나를 골라, 사는 곳과 자랑거리를 나누어 소개하는 짧은 글을 쓰세요.","answer_guide":{"answer":"예: 제가 사는 부산의 자랑거리는 해운대입니다. 해운대는 부산 해운대구에 있습니다. 모래사장이 넓고 바다가 맑아 여름이면 많은 사람이 물놀이를 하러 옵니다. 겨울에도 바다를 보며 산책하기 좋아 부산의 최고 자랑거리라고 생각합니다.","scoring_points":["자랑거리와 사는 곳을 밝혔는가","자랑할 점을 나누어 썼는가","듣는 사람이 알기 쉽게 짜임새 있게 썼는가"]},"explanation":["『국어』 56쪽에서 떠올린 자랑거리를 써도 좋아요.","사는 곳 → 자랑거리 차례로 나누어요.","『국어』 59쪽처럼 소개하는 글을 찾아 읽어 보면 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_basic#1','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C12',1,'mc','auto','『국어』 60쪽 「경험에 어울리는 이야기 찾기」 활동의 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":1,"concept":"K3-2-u1-C12","difficulty":1,"kind":"mc","stem":"『국어』 60쪽 「경험에 어울리는 이야기 찾기」 활동의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"자신의 경험 떠올리기 → 경험에 어울리는 이야기 찾기 → 친구들에게 경험과 관련지어 이야기 말하기","correct":true},{"t":"경험에 어울리는 이야기 찾기 → 자신의 경험 떠올리기 → 친구들에게 이야기 말하기","mis":"K3-2-u1-X14"},{"t":"친구들에게 이야기 말하기 → 자신의 경험 떠올리기 → 이야기 찾기","mis":"K3-2-u1-X14"},{"t":"자신의 경험 떠올리기 → 친구들에게 이야기 말하기 → 이야기 찾기","mis":"K3-2-u1-X14"}],"explanation":["경험이 먼저 있어야 어울리는 이야기를 찾을 수 있어요.","찾은 이야기의 제목과 고른 까닭을 정리해요.","그다음 친구들에게 경험과 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_basic#2','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C13',1,'mc','auto','『국어』 64쪽 대화에 나온 「낳아」는 어떻게 소리 나나요?',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":2,"concept":"K3-2-u1-C13","difficulty":1,"kind":"mc","stem":"『국어』 64쪽 대화에 나온 「낳아」는 어떻게 소리 나나요?","options":[{"t":"[나아]","correct":true},{"t":"[나하]","mis":"K3-2-u1-X20"},{"t":"[나타]","mis":"K3-2-u1-X20"},{"t":"[낟아]","mis":"K3-2-u1-X20"}],"explanation":["받침 ㅎ 뒤에 모음으로 시작하는 「아」가 왔어요.","이때 받침 ㅎ은 소리 나지 않아요.","그래서 [나아]예요."],"asset":{"type":"passage","lines":["가 — 너희 개는 새끼를 언제 낳아? / 이번 주에 낳을 것 같아.","나 — 그 책은 내 책상 위에 놓아. / 응, 알았어.","다 — 내일 운동장에서 만나는 건 어때? / 응, 좋아.","라 — 손이 책에 안 닿아. 좀 도와줄래? / 그래, 내가 도와줄게."],"title":"기초 다지기 대화 — 『국어』 64쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_basic#3','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C13',1,'ox','auto','「좋아」를 [조아]로 소리 내니 쓸 때도 「조아」로 써요.',ARRAY['K3-2-u1-X21']::text[],false,'{"seq":3,"concept":"K3-2-u1-C13","difficulty":1,"kind":"ox","stem":"「좋아」를 [조아]로 소리 내니 쓸 때도 「조아」로 써요.","answer":"X","reason_options":[{"t":"소리는 [조아]지만 글자는 받침 ㅎ을 살려 「좋아」로 쓰기 때문에","correct":true},{"t":"소리 나는 대로 쓰는 것이 바른 글자이기 때문에","mis":"K3-2-u1-X21"}],"mis":"K3-2-u1-X21","explanation":["받침 ㅎ은 소리만 나지 않아요.","쓸 때는 받침 ㅎ을 그대로 써요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_basic#4','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C14',1,'mc','auto','『국어』 64쪽 생각그물 보기에서 「개, 나비, 고래」를 묶는 이름은 무엇인가요?',ARRAY['K3-2-u1-X22']::text[],false,'{"seq":4,"concept":"K3-2-u1-C14","difficulty":1,"kind":"mc","stem":"『국어』 64쪽 생각그물 보기에서 「개, 나비, 고래」를 묶는 이름은 무엇인가요?","options":[{"t":"동물","correct":true},{"t":"옷","mis":"K3-2-u1-X22"},{"t":"고래","mis":"K3-2-u1-X22"},{"t":"바다","mis":"K3-2-u1-X22"}],"explanation":["셋을 한마디로 부르는 이름을 찾아요.","개·나비·고래는 모두 동물이에요.","고래는 묶이는 낱말 가운데 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_basic#5','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C12',2,'mc','auto','친구들이 경험에 어울리는 이야기를 찾았어요. 준우가 「까먹어도 될까요」를 고른 까닭은 무엇인가요?',ARRAY['K3-2-u1-X18','K3-2-u1-X07']::text[],false,'{"seq":5,"concept":"K3-2-u1-C12","difficulty":2,"kind":"mc","stem":"친구들이 경험에 어울리는 이야기를 찾았어요. 준우가 「까먹어도 될까요」를 고른 까닭은 무엇인가요?","options":[{"t":"연필을 자주 잃어버린 경험과 이어져서","correct":true},{"t":"가장 유명한 이야기라서","mis":"K3-2-u1-X18"},{"t":"가장 긴 이야기라서","mis":"K3-2-u1-X18"},{"t":"여행 간 경험과 이어져서","mis":"K3-2-u1-X07"}],"explanation":["『국어』 60쪽의 말을 다시 읽어요.","준우는 연필을 자주 잃어버린 경험을 떠올렸어요.","경험과 이어지는 이야기를 골랐어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"여행 갔을 때 본 바위가 생각났어. 바위와 관련 있는 이야기가 무엇이 있을지 생각해 봤어."},{"who":"서아","text":"나는 여행 간 경험을 떠올려 보니 「하나 둘 셋 찰칵! 김치, 치즈, 카프카」의 주인공이 생각났어."},{"who":"준우","text":"연필을 자주 잃어버린 경험이 떠올라서 1학기 때 읽은 「까먹어도 될까요」를 찾아봤어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_basic#6','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C12',2,'mc','auto','「분리배출을 잘하는 방법」을 듣고 표로 정리했어요. 「종이」 칸에 들어갈 것은 무엇인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":6,"concept":"K3-2-u1-C12","difficulty":2,"kind":"mc","stem":"「분리배출을 잘하는 방법」을 듣고 표로 정리했어요. 「종이」 칸에 들어갈 것은 무엇인가요?","options":[{"t":"신문지, 책","correct":true},{"t":"음료수 캔, 통조림 캔","mis":"K3-2-u1-X17"},{"t":"플라스틱 도시락통","mis":"K3-2-u1-X17"},{"t":"종이컵, 기름 묻은 피자 상자","mis":"K3-2-u1-X17"}],"explanation":["『국어』 61쪽 표의 「분리배출 방법」 칸이에요.","캔·종이·플라스틱으로 나누어 정리해요.","종이컵과 기름 묻은 피자 상자는 종이로 버리지 않아요."],"asset":{"type":"speech","turns":[{"who":"지유","text":"선생님, 분리배출을 쉽게 알려 주세요!"},{"who":"전문가","text":"음료수 캔이나 통조림 캔은 캔으로, 신문지나 책은 종이로, 플라스틱 도시락통은 플라스틱으로 버려요."},{"who":"전문가","text":"그런데 헷갈리는 것도 있어요. 종이컵은 안쪽이 코팅되어 있어서 깨끗이 씻어 종이컵 전용으로 버려요."},{"who":"전문가","text":"페트병 뚜껑은 따로 떼어 플라스틱으로 버리고, 기름이 묻은 피자 상자는 쓰레기로 버려요."},{"who":"전문가","text":"스티로폼은 깨끗하면 재활용할 수 있지만, 음식물이 묻었으면 쓰레기로 버려요."},{"who":"전문가","text":"그리고 이것은 꼭 기억하세요. 더러운 것은 깨끗이 씻어 버려야 다시 쓸 수 있어요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_basic#7','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C12',2,'mc','auto','전문가가 「이것은 꼭 기억하세요.」라고 한 뒤에 말한 중요한 내용은 무엇인가요?',ARRAY['K3-2-u1-X11']::text[],false,'{"seq":7,"concept":"K3-2-u1-C12","difficulty":2,"kind":"mc","stem":"전문가가 「이것은 꼭 기억하세요.」라고 한 뒤에 말한 중요한 내용은 무엇인가요?","options":[{"t":"더러운 것은 깨끗이 씻어 버려야 한다","correct":true},{"t":"페트병 뚜껑은 따로 뗀다","mis":"K3-2-u1-X11"},{"t":"분리배출을 쉽게 알려 달라","mis":"K3-2-u1-X11"},{"t":"이제 더 잘 알겠다","mis":"K3-2-u1-X11"}],"explanation":["「이것은」은 중요한 내용을 알려 주는 말이에요.","그 바로 뒤의 말을 잡아요.","더러운 것은 씻어 버려야 다시 쓸 수 있어요."],"asset":{"type":"speech","turns":[{"who":"지유","text":"선생님, 분리배출을 쉽게 알려 주세요!"},{"who":"전문가","text":"음료수 캔이나 통조림 캔은 캔으로, 신문지나 책은 종이로, 플라스틱 도시락통은 플라스틱으로 버려요."},{"who":"전문가","text":"그런데 헷갈리는 것도 있어요. 종이컵은 안쪽이 코팅되어 있어서 깨끗이 씻어 종이컵 전용으로 버려요."},{"who":"전문가","text":"페트병 뚜껑은 따로 떼어 플라스틱으로 버리고, 기름이 묻은 피자 상자는 쓰레기로 버려요."},{"who":"전문가","text":"스티로폼은 깨끗하면 재활용할 수 있지만, 음식물이 묻었으면 쓰레기로 버려요."},{"who":"전문가","text":"그리고 이것은 꼭 기억하세요. 더러운 것은 깨끗이 씻어 버려야 다시 쓸 수 있어요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_basic#8','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C13',2,'mc','auto','다음 가운데 받침 ㅎ이 소리 나지 않는 말은 무엇인가요?',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":8,"concept":"K3-2-u1-C13","difficulty":2,"kind":"mc","stem":"다음 가운데 받침 ㅎ이 소리 나지 않는 말은 무엇인가요?","options":[{"t":"놓아","correct":true},{"t":"놓고","mis":"K3-2-u1-X20"},{"t":"놓다","mis":"K3-2-u1-X20"},{"t":"놓지","mis":"K3-2-u1-X20"}],"explanation":["받침 ㅎ 바로 뒤를 봐요.","「아」처럼 모음으로 시작하면 ㅎ 소리가 나지 않아요.","「고·다·지」처럼 자음이 오면 그렇지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_basic#9','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C13',2,'match','auto','받침 ㅎ이 있는 낱말과 소리를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C13","difficulty":2,"kind":"match","stem":"받침 ㅎ이 있는 낱말과 소리를 알맞게 이으세요.","pairs":[{"l":"닿아","r":"[다아]"},{"l":"쌓아","r":"[싸아]"},{"l":"넣어","r":"[너어]"}],"mis":"K3-2-u1-X20","explanation":["「닿아」는 『국어』 64쪽, 「쌓아」·「넣어」는 지도서가 더한 예예요.","모두 받침 ㅎ 뒤에 모음이 왔어요.","그래서 ㅎ 소리가 나지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_basic#10','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C12',3,'error','auto','『국어』 61쪽처럼 분리배출 실천 다짐을 썼어요. 내가 할 일이 드러나지 않게 막연하게 쓴 친구는 누구인가요?',ARRAY['K3-2-u1-X19']::text[],false,'{"seq":10,"concept":"K3-2-u1-C12","difficulty":3,"kind":"error","stem":"『국어』 61쪽처럼 분리배출 실천 다짐을 썼어요. 내가 할 일이 드러나지 않게 막연하게 쓴 친구는 누구인가요?","options":[{"t":"친구 다 — 「모두 환경을 잘 지키면 좋겠습니다.」","correct":true,"mis_target":"K3-2-u1-X19"},{"t":"친구 가 — 「나는 이제부터 쓰레기를 버릴 때 종류를 잘 보고 분리배출하겠습니다.」","mis":"K3-2-u1-X19"},{"t":"친구 나 — 「나는 우유갑을 버리기 전에 깨끗이 씻겠습니다.」","mis":"K3-2-u1-X19"}],"explanation":["다짐은 내가 할 일을 쓰는 거예요.","「모두 ~하면 좋겠습니다」는 남에게 바라는 말이에요.","언제·무엇을 할지가 드러나야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_challenge#1','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C13',2,'sa','auto','지도서는 겹받침에 ㅎ이 있을 때도 모음 앞에서 ㅎ 소리가 나지 않는다고 해요. 「끓이다」가 [끄리다]로 소리 나듯이, 「끊어지다」는 어떻게 소리 나는지 대괄호 없이 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C13","difficulty":2,"kind":"sa","stem":"지도서는 겹받침에 ㅎ이 있을 때도 모음 앞에서 ㅎ 소리가 나지 않는다고 해요. 「끓이다」가 [끄리다]로 소리 나듯이, 「끊어지다」는 어떻게 소리 나는지 대괄호 없이 쓰세요.","answer":["끄너지다"],"explanation":["「끊어지다」의 겹받침은 ㄴ과 ㅎ이에요.","뒤에 모음 「어」가 오면 ㅎ 소리가 나지 않아요.","남은 ㄴ이 넘어가 [끄너지다]가 돼요."],"mis":"K3-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_challenge#2','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C14',2,'ox','auto','「모자, 양말, 바지」를 「옷」으로 묶어 두면 처음 보는 낱말도 어디에 담을지 알 수 있어요.',ARRAY['K3-2-u1-X22']::text[],false,'{"seq":2,"concept":"K3-2-u1-C14","difficulty":2,"kind":"ox","stem":"「모자, 양말, 바지」를 「옷」으로 묶어 두면 처음 보는 낱말도 어디에 담을지 알 수 있어요.","answer":"O","reason_options":[{"t":"묶는 이름을 알면 새 낱말도 같은 갈래인지 따져 볼 수 있기 때문에","correct":true},{"t":"묶는 이름은 그 세 낱말에만 쓸 수 있기 때문에","mis":"K3-2-u1-X22"}],"mis":"K3-2-u1-X22","explanation":["『국어』 64쪽 보기의 생각그물이에요.","「옷」 아래에 장갑이나 치마도 담을 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_challenge#3','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',3,'mc','auto','「분리배출을 잘하는 방법」에서 종이컵을 그냥 종이처럼 버리면 안 되는 까닭은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":3,"concept":"K3-2-u1-C12","difficulty":3,"kind":"mc","stem":"「분리배출을 잘하는 방법」에서 종이컵을 그냥 종이처럼 버리면 안 되는 까닭은 무엇인가요?","options":[{"t":"안쪽이 코팅되어 있어서","correct":true},{"t":"종이컵은 플라스틱이라서","mis":"K3-2-u1-X07"},{"t":"너무 작아서","mis":"K3-2-u1-X07"},{"t":"기름이 묻어 있어서","mis":"K3-2-u1-X07"}],"explanation":["전문가가 「헷갈리는 것도 있어요.」라고 한 뒤의 말이에요.","종이컵은 안쪽이 코팅되어 있어요.","그래서 씻어서 종이컵 전용으로 버려요."],"asset":{"type":"speech","turns":[{"who":"지유","text":"선생님, 분리배출을 쉽게 알려 주세요!"},{"who":"전문가","text":"음료수 캔이나 통조림 캔은 캔으로, 신문지나 책은 종이로, 플라스틱 도시락통은 플라스틱으로 버려요."},{"who":"전문가","text":"그런데 헷갈리는 것도 있어요. 종이컵은 안쪽이 코팅되어 있어서 깨끗이 씻어 종이컵 전용으로 버려요."},{"who":"전문가","text":"페트병 뚜껑은 따로 떼어 플라스틱으로 버리고, 기름이 묻은 피자 상자는 쓰레기로 버려요."},{"who":"전문가","text":"스티로폼은 깨끗하면 재활용할 수 있지만, 음식물이 묻었으면 쓰레기로 버려요."},{"who":"전문가","text":"그리고 이것은 꼭 기억하세요. 더러운 것은 깨끗이 씻어 버려야 다시 쓸 수 있어요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_challenge#4','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',3,'mc','auto','「분리배출을 잘하는 방법」에 따라 바르게 버린 친구는 누구인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":4,"concept":"K3-2-u1-C12","difficulty":3,"kind":"mc","stem":"「분리배출을 잘하는 방법」에 따라 바르게 버린 친구는 누구인가요?","options":[{"t":"음식물이 묻은 스티로폼을 쓰레기로 버린 친구","correct":true},{"t":"기름 묻은 피자 상자를 종이로 버린 친구","mis":"K3-2-u1-X17"},{"t":"뚜껑을 닫은 채 페트병을 버린 친구","mis":"K3-2-u1-X17"},{"t":"씻지 않은 종이컵을 종이로 버린 친구","mis":"K3-2-u1-X17"}],"explanation":["헷갈리는 것들을 다시 들어요.","음식물이 묻은 스티로폼은 쓰레기로 버려요.","피자 상자·페트병 뚜껑·종이컵은 따로 챙겨야 해요."],"asset":{"type":"speech","turns":[{"who":"지유","text":"선생님, 분리배출을 쉽게 알려 주세요!"},{"who":"전문가","text":"음료수 캔이나 통조림 캔은 캔으로, 신문지나 책은 종이로, 플라스틱 도시락통은 플라스틱으로 버려요."},{"who":"전문가","text":"그런데 헷갈리는 것도 있어요. 종이컵은 안쪽이 코팅되어 있어서 깨끗이 씻어 종이컵 전용으로 버려요."},{"who":"전문가","text":"페트병 뚜껑은 따로 떼어 플라스틱으로 버리고, 기름이 묻은 피자 상자는 쓰레기로 버려요."},{"who":"전문가","text":"스티로폼은 깨끗하면 재활용할 수 있지만, 음식물이 묻었으면 쓰레기로 버려요."},{"who":"전문가","text":"그리고 이것은 꼭 기억하세요. 더러운 것은 깨끗이 씻어 버려야 다시 쓸 수 있어요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_challenge#5','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',3,'mc','auto','「친구를 도와줬더니 부모님께 칭찬을 받았다」는 경험에 어울리는 이야기로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X18']::text[],false,'{"seq":5,"concept":"K3-2-u1-C12","difficulty":3,"kind":"mc","stem":"「친구를 도와줬더니 부모님께 칭찬을 받았다」는 경험에 어울리는 이야기로 알맞은 것은 무엇인가요?","options":[{"t":"다친 제비를 도와준 흥부가 복을 받은 「흥부와 놀부」","correct":true},{"t":"가장 많은 사람이 아는 이야기","mis":"K3-2-u1-X18"},{"t":"가장 두꺼운 책에 실린 이야기","mis":"K3-2-u1-X18"},{"t":"제목이 가장 긴 이야기","mis":"K3-2-u1-X18"}],"explanation":["지도서 114쪽의 예시예요.","남을 도운 일과 그 뒤에 좋은 일이 생긴 것이 이어져요.","유명하거나 길어서가 아니라 경험과 이어져서 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_challenge#6','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C13',3,'mc','auto','받침 ㅎ이 소리 나지 않는 경우를 바르게 설명한 것은 무엇인가요?',ARRAY['K3-2-u1-X20','K3-2-u1-X21']::text[],false,'{"seq":6,"concept":"K3-2-u1-C13","difficulty":3,"kind":"mc","stem":"받침 ㅎ이 소리 나지 않는 경우를 바르게 설명한 것은 무엇인가요?","options":[{"t":"받침 ㅎ 뒤에 모음으로 시작하는 말이 오면 ㅎ 소리가 나지 않는다","correct":true},{"t":"받침 ㅎ 뒤에 자음이 오면 ㅎ 소리가 나지 않는다","mis":"K3-2-u1-X20"},{"t":"받침 ㅎ은 언제나 소리 나지 않는다","mis":"K3-2-u1-X20"},{"t":"소리가 나지 않으니 받침 ㅎ을 빼고 쓴다","mis":"K3-2-u1-X21"}],"explanation":["『국어』 64쪽 날개의 설명이에요.","「낳아」·「놓아」·「좋아」·「닿아」 모두 뒤가 모음이에요.","쓸 때는 받침 ㅎ을 그대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_challenge#7','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C14',3,'match','auto','지도서는 사회나 과학 교과서의 낱말로도 생각그물을 만들어 보게 해요. 묶는 이름과 그 아래 낱말을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u1-C14","difficulty":3,"kind":"match","stem":"지도서는 사회나 과학 교과서의 낱말로도 생각그물을 만들어 보게 해요. 묶는 이름과 그 아래 낱말을 알맞게 이으세요.","pairs":[{"l":"곤충","r":"개미 · 벌 · 잠자리"},{"l":"교통수단","r":"버스 · 기차 · 배"},{"l":"옷","r":"모자 · 양말 · 바지"}],"mis":"K3-2-u1-X22","explanation":["셋을 한마디로 부르는 이름을 찾아요.","곤충·교통수단은 과학·사회 교과서에 나오는 낱말이에요.","묶는 이름이 위, 묶이는 낱말이 아래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_challenge#8','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',4,'essay','teacher','내 경험 하나를 떠올리고, 그 경험에 어울리는 이야기의 제목과 고른 까닭을 쓰세요. 친구들에게 말하듯이 경험과 이어서 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u1-C12","difficulty":4,"kind":"essay","stem":"내 경험 하나를 떠올리고, 그 경험에 어울리는 이야기의 제목과 고른 까닭을 쓰세요. 친구들에게 말하듯이 경험과 이어서 쓰세요.","answer_guide":{"answer":"예: 나는 동생과 장난감을 두고 다투다가 내가 먼저 양보했더니 동생이 고맙다며 그림을 그려 준 적이 있어. 그 경험이 떠올라 「나도 최고가 되고 싶어요」를 골랐어. 로지가 바이올렛의 화분까지 정성껏 돌보았을 때 바이올렛이 고맙다고 한 장면이 내 경험과 닮았기 때문이야.","scoring_points":["내 경험을 언제·무엇을이 드러나게 썼는가","어울리는 이야기 제목을 밝혔는가","경험과 이야기가 어떻게 이어지는지 까닭을 썼는가"]},"explanation":["『국어』 60쪽 활동 ①~③이에요.","유명하거나 긴 이야기가 아니라 경험과 이어지는 이야기를 골라요.","고른 까닭에 경험과 이야기의 닮은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_challenge#9','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',4,'essay','teacher','「분리배출을 잘하는 방법」에서 들은 내용 가운데 하나를 근거로 들어, 내가 오늘부터 할 분리배출 실천 다짐을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C12","difficulty":4,"kind":"essay","stem":"「분리배출을 잘하는 방법」에서 들은 내용 가운데 하나를 근거로 들어, 내가 오늘부터 할 분리배출 실천 다짐을 쓰세요.","answer_guide":{"answer":"예: 전문가께서 페트병 뚜껑은 따로 떼어 플라스틱으로 버려야 한다고 하셨다. 그래서 나는 오늘부터 급식 우유나 음료수 병을 버릴 때 뚜껑을 떼고 병을 헹군 뒤 플라스틱 통에 넣겠다.","scoring_points":["들은 내용을 근거로 들었는가","내가 할 일을 썼는가","언제·무엇을이 드러나게 썼는가"]},"explanation":["『국어』 61쪽 2번 활동이에요.","들은 내용을 간추린 것이 다짐의 근거가 돼요.","「모두 잘하겠다」가 아니라 내가 할 한 가지를 써요."],"asset":{"type":"speech","turns":[{"who":"지유","text":"선생님, 분리배출을 쉽게 알려 주세요!"},{"who":"전문가","text":"음료수 캔이나 통조림 캔은 캔으로, 신문지나 책은 종이로, 플라스틱 도시락통은 플라스틱으로 버려요."},{"who":"전문가","text":"그런데 헷갈리는 것도 있어요. 종이컵은 안쪽이 코팅되어 있어서 깨끗이 씻어 종이컵 전용으로 버려요."},{"who":"전문가","text":"페트병 뚜껑은 따로 떼어 플라스틱으로 버리고, 기름이 묻은 피자 상자는 쓰레기로 버려요."},{"who":"전문가","text":"스티로폼은 깨끗하면 재활용할 수 있지만, 음식물이 묻었으면 쓰레기로 버려요."},{"who":"전문가","text":"그리고 이것은 꼭 기억하세요. 더러운 것은 깨끗이 씻어 버려야 다시 쓸 수 있어요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_L11_challenge#10','kor',3,2,'u1','L11','tb_g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C13',4,'essay','teacher','『국어』 64쪽 대화의 「낳아」, 「놓아」, 「좋아」, 「닿아」 가운데 두 말을 넣어 문장을 하나씩 만들고, 그 말이 어떻게 소리 나는지와 쓸 때는 어떻게 쓰는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C13","difficulty":4,"kind":"essay","stem":"『국어』 64쪽 대화의 「낳아」, 「놓아」, 「좋아」, 「닿아」 가운데 두 말을 넣어 문장을 하나씩 만들고, 그 말이 어떻게 소리 나는지와 쓸 때는 어떻게 쓰는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「우리 집 고양이가 새끼를 낳아 기뻤다.」에서 「낳아」는 [나아], 「선반이 높아 손이 안 닿아.」에서 「닿아」는 [다아]로 소리 난다. 받침 ㅎ 뒤에 모음으로 시작하는 말이 와서 ㅎ 소리가 나지 않기 때문이다. 그래도 쓸 때는 받침 ㅎ을 살려 「낳아」, 「닿아」로 쓴다.","scoring_points":["두 말을 넣어 문장을 만들었는가","소리를 바르게 썼는가","쓸 때는 받침 ㅎ을 그대로 쓴다는 것과 까닭을 썼는가"]},"explanation":["받침 ㅎ 뒤에 모음이 와요.","소리는 [나아]·[노아]·[조아]·[다아]예요.","글자는 받침 ㅎ을 그대로 써요."],"asset":{"type":"passage","lines":["가 — 너희 개는 새끼를 언제 낳아? / 이번 주에 낳을 것 같아.","나 — 그 책은 내 책상 위에 놓아. / 응, 알았어.","다 — 내일 운동장에서 만나는 건 어때? / 응, 좋아.","라 — 손이 책에 안 닿아. 좀 도와줄래? / 그래, 내가 도와줄게."],"title":"기초 다지기 대화 — 『국어』 64쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#1','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C8',1,'mc','auto','『국어』 63쪽 「스스로 확인하기」에서 중요한 내용을 간추리는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u1-X10','K3-2-u1-X11']::text[],false,'{"seq":1,"concept":"K3-2-u1-C8","difficulty":1,"kind":"mc","stem":"『국어』 63쪽 「스스로 확인하기」에서 중요한 내용을 간추리는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"모든 내용을 옮겨 적는다","correct":true},{"t":"듣는 목적을 생각한다","mis":"K3-2-u1-X10"},{"t":"제목을 보고 들을 내용을 예상한다","mis":"K3-2-u1-X10"},{"t":"들으면서 ‘첫째’, ‘둘째’와 같은 말에 주의한다","mis":"K3-2-u1-X11"}],"explanation":["바구니에 담을 감은 알맞은 방법만이에요.","목적·예상·표지어·기호는 모두 알맞아요.","모든 내용을 옮겨 적는 것은 간추리기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#2','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C1',1,'blank','auto','「나도 최고가 되고 싶어요」를 읽고 떠오른 경험을 쓰는 평가지의 칸은 「언제 · 무엇을 · 그때 자신의 ○○」예요. ○○에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u1-X01']::text[],false,'{"seq":2,"concept":"K3-2-u1-C1","difficulty":1,"kind":"blank","stem":"「나도 최고가 되고 싶어요」를 읽고 떠오른 경험을 쓰는 평가지의 칸은 「언제 · 무엇을 · 그때 자신의 ○○」예요. ○○에 알맞은 말은 무엇인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"물건값","mis":"K3-2-u1-X01"},{"t":"정확한 시각","mis":"K3-2-u1-X01"},{"t":"친구의 나이","mis":"K3-2-u1-X01"}],"explanation":["지도서 121쪽 평가 예시 1번이에요.","언제·무엇을 다음에 그때의 마음을 써요.","생각이나 느낌이 있어야 작품과 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#3','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C3',1,'sa','auto','「은행잎 편지」에서 말하는 이가 이야기를 담아 띄워 보낸 것은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":1,"kind":"sa","stem":"「은행잎 편지」에서 말하는 이가 이야기를 담아 띄워 보낸 것은 무엇인가요? 세 글자로 쓰세요.","answer":["은행잎"],"explanation":["2~3연을 간추린 줄을 읽어요.","떨어진 ○○○에 이야기를 담았어요.","은행잎이에요."],"asset":{"type":"passage","lines":["방학 때 나도 몰래","이사 간 친구","[간추림] 2~3연 — 떨어진 은행잎에 이야기를 담아 그 친구에게 띄워 보낸다."],"title":"시 「은행잎 편지」(김홍관) 1연 — 『국어』 36쪽"},"mis":"K3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#4','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C5',1,'mc','auto','「나도 최고가 되고 싶어요」에서 아이들이 꼬마 화분에 키운 것은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":4,"concept":"K3-2-u1-C5","difficulty":1,"kind":"mc","stem":"「나도 최고가 되고 싶어요」에서 아이들이 꼬마 화분에 키운 것은 무엇인가요?","options":[{"t":"완두콩","correct":true},{"t":"강낭콩","mis":"K3-2-u1-X07"},{"t":"해바라기","mis":"K3-2-u1-X07"},{"t":"방울토마토","mis":"K3-2-u1-X07"}],"explanation":["지도서가 든 내용 확인 질문이에요.","윌리스 선생님이 완두콩을 키우자고 했어요.","답이 글에 그대로 있어요."],"asset":{"type":"passage","lines":["[간추림] 바이올렛은 뭐든지 최고로 잘해요. 가장 빨리 달리고 가장 높게 노래해요.","[간추림] 로지는 바이올렛이 최고라는 말을 듣기가 싫었어요.","[간추림] 윌리스 선생님이 저마다 꼬마 화분에 완두콩을 키우자고 했어요.","[간추림] 바이올렛의 화분은 반짝반짝 빛났고, 로지의 화분은 평범했어요.","[간추림] 로지와 바이올렛의 화분에서 먼저 새싹이 올라왔어요.","바이올렛이 큰 소리로 외쳤어요. “내가 일 등이다! 만세!”"],"title":"이야기 「나도 최고가 되고 싶어요」 ① — 『국어』 42~44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#5','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C10',1,'mc','auto','호랑이가 개미 떼를 만나고 나서 달라진 점은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":5,"concept":"K3-2-u1-C10","difficulty":1,"kind":"mc","stem":"호랑이가 개미 떼를 만나고 나서 달라진 점은 무엇인가요?","options":[{"t":"다른 동물들 앞에서 큰소리치거나 괴롭히지 않게 되었다","correct":true},{"t":"개미 떼와 함께 숲속의 왕이 되었다","mis":"K3-2-u1-X07"},{"t":"더 크게 으스대게 되었다","mis":"K3-2-u1-X07"},{"t":"개미를 잡아먹게 되었다","mis":"K3-2-u1-X07"}],"explanation":["『국어』 53쪽 (3)번이에요.","호랑이는 개미 떼에게 혼이 났어요.","그 뒤로 큰소리치거나 괴롭히지 않았어요."],"asset":{"type":"passage","lines":["[장면] 다음 날, 개미 떼가 나타나 호랑이 털 속으로 들어갔어요.","[장면] 호랑이는 가려움을 참지 못해 아무것도 할 수 없었어요.","[장면] 그 뒤로 호랑이는 다른 동물들 앞에서 큰소리치거나 괴롭히지 않았어요."],"title":"영상 「호랑이를 이긴 개미」 ② — 『국어』 53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#6','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C11',1,'mc','auto','「우리 지역의 자랑거리」에서 여러 지역의 대표들이 한자리에 모인 까닭은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":6,"concept":"K3-2-u1-C11","difficulty":1,"kind":"mc","stem":"「우리 지역의 자랑거리」에서 여러 지역의 대표들이 한자리에 모인 까닭은 무엇인가요?","options":[{"t":"우리 지역의 자랑거리를 찾는 현장에서 자기 자랑을 하려고","correct":true},{"t":"시장에서 물건을 팔려고","mis":"K3-2-u1-X07"},{"t":"여행을 떠나려고","mis":"K3-2-u1-X07"},{"t":"요리 대회에 나가려고","mis":"K3-2-u1-X07"}],"explanation":["지도서 111쪽 「내용 파악에 도움이 되는 질문」이에요.","기자가 처음에 현장을 소개했어요.","대표들이 자기 자랑을 하느라 분주했어요."],"asset":{"type":"speech","turns":[{"who":"기자","text":"여기는 ‘우리 지역의 자랑거리’를 찾는 현장입니다. 첫 번째 참가자는 홍천 옥수수입니다."},{"who":"홍천 옥수수","text":"제가 온 강원특별자치도 홍천군은 낮과 밤의 온도 차이가 크고 공기가 깨끗해요. 달고 쫀득쫀득한 맛을 자랑하지요."},{"who":"기자","text":"이어서 두 번째 참가자인 울릉도 오징어입니다."},{"who":"울릉도 오징어","text":"저는 경상북도 울릉군 울릉도에서 왔어요. 바닷물이 맑고 깨끗해 해산물이 많아요. 저를 말리면 고소하고 씹을수록 약간 단맛이 나요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#7','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C13',1,'mc','auto','『국어』 64쪽 대화에 나온 「놓아」는 어떻게 소리 나나요?',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":7,"concept":"K3-2-u1-C13","difficulty":1,"kind":"mc","stem":"『국어』 64쪽 대화에 나온 「놓아」는 어떻게 소리 나나요?","options":[{"t":"[노아]","correct":true},{"t":"[노하]","mis":"K3-2-u1-X20"},{"t":"[노타]","mis":"K3-2-u1-X20"},{"t":"[녿아]","mis":"K3-2-u1-X20"}],"explanation":["받침 ㅎ 뒤에 모음으로 시작하는 「아」가 왔어요.","받침 ㅎ은 소리 나지 않아요.","그래서 [노아]예요."],"asset":{"type":"passage","lines":["가 — 너희 개는 새끼를 언제 낳아? / 이번 주에 낳을 것 같아.","나 — 그 책은 내 책상 위에 놓아. / 응, 알았어.","다 — 내일 운동장에서 만나는 건 어때? / 응, 좋아.","라 — 손이 책에 안 닿아. 좀 도와줄래? / 그래, 내가 도와줄게."],"title":"기초 다지기 대화 — 『국어』 64쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#8','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C12',1,'mc','auto','『국어』 63쪽 「생활 속으로」에 쓴 다짐 가운데 언제, 무엇을 할지 드러나게 쓴 것은 무엇인가요?',ARRAY['K3-2-u1-X19']::text[],false,'{"seq":8,"concept":"K3-2-u1-C12","difficulty":1,"kind":"mc","stem":"『국어』 63쪽 「생활 속으로」에 쓴 다짐 가운데 언제, 무엇을 할지 드러나게 쓴 것은 무엇인가요?","options":[{"t":"안내 방송을 들을 때 중요한 내용을 간단히 정리해 볼 거야.","correct":true},{"t":"앞으로 다 잘할 거야.","mis":"K3-2-u1-X19"},{"t":"친구들이 잘 들으면 좋겠어.","mis":"K3-2-u1-X19"},{"t":"국어를 열심히 할 거야.","mis":"K3-2-u1-X19"}],"explanation":["「생활 속으로」의 친구 말이에요.","언제(안내 방송을 들을 때) 무엇을(간단히 정리) 할지 들어 있어요.","막연한 다짐이나 남에게 바라는 말은 실천하기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#9','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C2',2,'mc','auto','『국어활동』 7쪽 「책에 나온 것들」과 비슷한 경험으로 예시 답안에 나온 것은 무엇인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":9,"concept":"K3-2-u1-C2","difficulty":2,"kind":"mc","stem":"『국어활동』 7쪽 「책에 나온 것들」과 비슷한 경험으로 예시 답안에 나온 것은 무엇인가요?","options":[{"t":"책에서 귀여운 강아지 그림을 보고 강아지를 키우고 싶었던 일","correct":true},{"t":"망고를 사러 시장에 간 일","mis":"K3-2-u1-X02"},{"t":"안경을 새로 맞춘 일","mis":"K3-2-u1-X02"},{"t":"아무 책이나 읽은 일","mis":"K3-2-u1-X03"}],"explanation":["시의 망고와 안경이 나온 일을 찾는 게 아니에요.","책에서 본 것을 갖고 싶었던 마음을 찾아요.","강아지를 키우고 싶었던 일이 이어져요."],"asset":{"type":"passage","lines":["책에 나온 망고","나도 먹고 싶다.","[간추림] 멋있는 안경도 쓰고 싶지만, 책 밖으로 나오지 못해 내 것이 될 수 없다.","[간추림] 책 속에 있는 것들은 모든 사람들의 것이다."],"title":"시 「책에 나온 것들」(김옥애) — 『국어활동』 7쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#10','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C6',2,'mc','auto','로지가 바이올렛의 새싹을 덮기 전에 슬쩍 어깨 너머를 살펴본 행동으로 짐작할 수 있는 로지의 마음은 무엇인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":10,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"로지가 바이올렛의 새싹을 덮기 전에 슬쩍 어깨 너머를 살펴본 행동으로 짐작할 수 있는 로지의 마음은 무엇인가요?","options":[{"t":"나쁜 일이라는 것을 알고 누가 볼까 봐 조마조마했다","correct":true},{"t":"선생님께 칭찬받고 싶었다","mis":"K3-2-u1-X04"},{"t":"바이올렛을 도와주고 싶었다","mis":"K3-2-u1-X04"},{"t":"아무 생각이 없었다","mis":"K3-2-u1-X04"}],"explanation":["마음은 글에 그대로 적혀 있지 않아요.","누가 보는지 살핀 행동이 근거예요.","스스로도 잘못이라는 것을 알았어요."],"asset":{"type":"passage","lines":["[간추림] 이튿날 아침 일찍, 로지는 바이올렛의 새싹이 조금 더 큰 것을 보았어요.","로지는 마음속으로 생각했어요. ‘이러면 안 되는데.’","[간추림] 로지는 슬쩍 어깨 너머를 살핀 뒤 바이올렛의 새싹을 흙으로 덮었어요.","‘됐어. 이제 내 완두콩이 최고야.’","[간추림] 아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.","[간추림] 그날 바이올렛은 수두에 걸려 당분간 학교에 못 나온다고 했어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ② — 『국어』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#11','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C9',2,'mc','auto','박민수 박사님은 친구의 이야기를 집중해서 들으면 무엇을 알 수 있다고 했나요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":11,"concept":"K3-2-u1-C9","difficulty":2,"kind":"mc","stem":"박민수 박사님은 친구의 이야기를 집중해서 들으면 무엇을 알 수 있다고 했나요?","options":[{"t":"친구가 어떤 부분에서 화가 났는지, 내가 어떻게 해 주었으면 좋을지","correct":true},{"t":"친구가 좋아하는 음식","mis":"K3-2-u1-X07"},{"t":"친구의 시험 점수","mis":"K3-2-u1-X07"},{"t":"친구가 사는 곳","mis":"K3-2-u1-X07"}],"explanation":["질문 ①의 대답 뒷부분이에요.","친구의 생각을 더 많이 알 수 있어요.","화난 까닭과 바라는 것을 알 수 있어요."],"asset":{"type":"speech","turns":[{"who":"이슬기","text":"첫 번째 질문이에요. 친구들과 생각이 달라 문제가 생기면 어떻게 해결해요?"},{"who":"박민수","text":"친구와 계속 이야기하려고 노력해야 해요. 친구 이야기를 집중해서 들으면 생각을 더 알 수 있어요."},{"who":"이슬기","text":"두 번째 질문이에요. 친구와 이야기 나눌 때 주의할 점이 있을까요?"},{"who":"박민수","text":"자신의 마음을 솔직하게 말해야 해요. 그러면 친구가 내 마음을 오해하지 않아요."},{"who":"이슬기","text":"세 번째 질문이에요. 마음을 솔직하게 말하기 어려울 때는요?"},{"who":"박민수","text":"그럴 때에는 선생님께 도움을 요청할 수 있어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#12','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C10',2,'mc','auto','「호랑이를 이긴 개미」에서 「호랑이가 화를 냄.」의 원인으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X15']::text[],false,'{"seq":12,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"「호랑이를 이긴 개미」에서 「호랑이가 화를 냄.」의 원인으로 알맞은 것은 무엇인가요?","options":[{"t":"개미가 호랑이를 무서워하지 않고 당당하게 대함.","correct":true},{"t":"호랑이가 다른 동물들을 괴롭히지 않게 됨.","mis":"K3-2-u1-X15"},{"t":"개미 떼가 털 속으로 들어감.","mis":"K3-2-u1-X15"},{"t":"호랑이와 개미가 다음 날 만나기로 함.","mis":"K3-2-u1-X15"}],"explanation":["『국어』 54쪽 (1)번이에요.","원인은 그 일보다 먼저 일어난 까닭이에요.","개미가 당당하게 대해서 호랑이가 화를 냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#13','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C11',2,'mc','auto','『국어』 58쪽 표에서 울릉도 오징어의 「환경」 칸에 들어갈 말은 무엇인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":13,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"『국어』 58쪽 표에서 울릉도 오징어의 「환경」 칸에 들어갈 말은 무엇인가요?","options":[{"t":"바닷물이 맑고 깨끗함.","correct":true},{"t":"낮과 밤의 온도 차가 크고 공기가 깨끗함.","mis":"K3-2-u1-X17"},{"t":"깨끗한 공기와 물, 흙으로 재배함.","mis":"K3-2-u1-X17"},{"t":"맛이 고소하고 씹을수록 단맛이 남.","mis":"K3-2-u1-X17"}],"explanation":["환경은 자란 곳의 모습이에요.","맛은 다른 칸에 넣어요.","울릉도는 바닷물이 맑고 깨끗해요."],"asset":{"type":"speech","turns":[{"who":"기자","text":"여기는 ‘우리 지역의 자랑거리’를 찾는 현장입니다. 첫 번째 참가자는 홍천 옥수수입니다."},{"who":"홍천 옥수수","text":"제가 온 강원특별자치도 홍천군은 낮과 밤의 온도 차이가 크고 공기가 깨끗해요. 달고 쫀득쫀득한 맛을 자랑하지요."},{"who":"기자","text":"이어서 두 번째 참가자인 울릉도 오징어입니다."},{"who":"울릉도 오징어","text":"저는 경상북도 울릉군 울릉도에서 왔어요. 바닷물이 맑고 깨끗해 해산물이 많아요. 저를 말리면 고소하고 씹을수록 약간 단맛이 나요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#14','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C14',2,'mc','auto','『국어』 64쪽 생각그물 보기에서 「모자, 양말, 바지」를 묶는 이름은 무엇인가요?',ARRAY['K3-2-u1-X22']::text[],false,'{"seq":14,"concept":"K3-2-u1-C14","difficulty":2,"kind":"mc","stem":"『국어』 64쪽 생각그물 보기에서 「모자, 양말, 바지」를 묶는 이름은 무엇인가요?","options":[{"t":"옷","correct":true},{"t":"동물","mis":"K3-2-u1-X22"},{"t":"양말","mis":"K3-2-u1-X22"},{"t":"신발","mis":"K3-2-u1-X22"}],"explanation":["셋을 한마디로 불러요.","모두 몸에 입거나 쓰거나 신는 옷이에요.","양말은 묶이는 낱말 가운데 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#15','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C5',2,'mc','auto','「뛰어나거나 색다른 점이 없이 보통이다」를 뜻하는 낱말은 무엇인가요?',ARRAY['K3-2-u1-X08']::text[],false,'{"seq":15,"concept":"K3-2-u1-C5","difficulty":2,"kind":"mc","stem":"「뛰어나거나 색다른 점이 없이 보통이다」를 뜻하는 낱말은 무엇인가요?","options":[{"t":"평범하다","correct":true},{"t":"에워싸다","mis":"K3-2-u1-X08"},{"t":"슬그머니","mis":"K3-2-u1-X08"},{"t":"듬뿍","mis":"K3-2-u1-X08"}],"explanation":["『국어』 47쪽 「낱말 알기」예요.","로지의 화분을 나타낸 말이에요.","평범하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#16','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C4',2,'mc','auto','「은행잎 편지」를 소리 내어 읽을 때 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":16,"concept":"K3-2-u1-C4","difficulty":2,"kind":"mc","stem":"「은행잎 편지」를 소리 내어 읽을 때 알맞은 방법은 무엇인가요?","options":[{"t":"말하는 이의 마음에 알맞은 쓸쓸하고 그리운 목소리로 읽는다","correct":true},{"t":"씩씩하고 신나는 목소리로 빠르게 읽는다","mis":"K3-2-u1-X04"},{"t":"아무 느낌 없이 한 글자씩 끊어 읽는다","mis":"K3-2-u1-X04"},{"t":"가장 큰 소리로 소리치듯 읽는다","mis":"K3-2-u1-X04"}],"explanation":["지도서는 말하는 이의 마음에 알맞은 목소리로 낭송하게 해요.","두 사람이 주고받거나 돌림 노래처럼 읽어도 좋아요.","친구를 그리워하는 마음을 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#17','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C7',3,'mc','auto','경험 나누기 놀이에서 쪽지를 「혼자 한 경험 / 함께 한 경험」으로 나누었어요. 「함께 한 경험」 칸에 들어갈 쪽지는 무엇인가요?',ARRAY['K3-2-u1-X28']::text[],false,'{"seq":17,"concept":"K3-2-u1-C7","difficulty":3,"kind":"mc","stem":"경험 나누기 놀이에서 쪽지를 「혼자 한 경험 / 함께 한 경험」으로 나누었어요. 「함께 한 경험」 칸에 들어갈 쪽지는 무엇인가요?","options":[{"t":"모둠 친구들과 교실 화분에 번갈아 물을 주었다","correct":true},{"t":"혼자 방에서 그림책을 읽었다","mis":"K3-2-u1-X28"},{"t":"혼자 줄넘기 백 번을 넘었다","mis":"K3-2-u1-X28"},{"t":"가장 재미있었던 경험","mis":"K3-2-u1-X28"}],"explanation":["『국어』 48쪽 놀이 2단계의 기준이에요.","「혼자」와 「함께」라는 기준 낱말을 쪽지에서 찾아요.","재미는 이 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#18','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C10',3,'mc','auto','「갈대와 떡갈나무」에서 떡갈나무에게 일어난 일을 계절 차례대로 간추린 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":18,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"「갈대와 떡갈나무」에서 떡갈나무에게 일어난 일을 계절 차례대로 간추린 것으로 알맞은 것은 무엇인가요?","options":[{"t":"자랑스러워함 → 잎이 무성해져 자신만만해짐 → 바람에 기둥이 부러짐 → 누워서 후회함","correct":true},{"t":"자신만만해짐 → 후회함 → 자랑스러워함 → 기둥이 부러짐","mis":"K3-2-u1-X14"},{"t":"기둥이 부러짐 → 자랑스러워함 → 후회함 → 자신만만해짐","mis":"K3-2-u1-X14"},{"t":"자랑스러워함 → 후회함 → 기둥이 부러짐 → 자신만만해짐","mis":"K3-2-u1-X14"}],"explanation":["『국어활동』 9쪽은 봄·여름·가을·겨울로 나누어 간추려요.","부러진 다음에야 후회할 수 있어요.","원인이 결과보다 먼저 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#19','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C8',3,'mc','auto','「놀이기구를 탈 때 기억해요」를 들은 뒤 간추린 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13']::text[],false,'{"seq":19,"concept":"K3-2-u1-C8","difficulty":3,"kind":"mc","stem":"「놀이기구를 탈 때 기억해요」를 들은 뒤 간추린 것으로 알맞은 것은 무엇인가요?","options":[{"t":"① 줄 서서 기다리기 ② 안전띠 매고 손잡이 잡기 ③ 떨어질 물건 두고 타기","correct":true},{"t":"① 안녕하세요 ② 3학년 학생 여러분 ③ 잠시 뒤에 만나요","mis":"K3-2-u1-X12"},{"t":"① 줄 서서 기다리기 ② 사람이 많음 ③ 오래 기다림","mis":"K3-2-u1-X13"},{"t":"① 놀이기구는 재미있음 ② 안전띠는 멋짐 ③ 즐겁게 타기","mis":"K3-2-u1-X13"}],"explanation":["「첫째」·「둘째」·「셋째」 뒤의 말을 잡아요.","인사말이나 덧붙인 말은 남기지 않아요.","번호를 붙여 짧게 정리해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘은 놀이기구를 탈 때 지켜야 하는 중요한 이야기를 해 줄게요."},{"who":"선생님","text":"첫째는 질서 있게 줄을 서서 기다립니다. 장난치지 않고 기다려 보세요."},{"who":"선생님","text":"둘째는 안전띠를 잘 매고 풀리지 않는지 살펴보세요. 타는 동안 손잡이를 꼭 잡아요."},{"who":"선생님","text":"셋째는 떨어질 수 있는 물건은 가지고 타지 않아요. 선생님이 잘 보관하고 있을게요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#20','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C12',3,'mc','auto','「분리배출을 잘하는 방법」을 듣고 정리한 표의 「분리배출할 때 주의할 점」으로 알맞게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u1-X17','K3-2-u1-X07']::text[],false,'{"seq":20,"concept":"K3-2-u1-C12","difficulty":3,"kind":"mc","stem":"「분리배출을 잘하는 방법」을 듣고 정리한 표의 「분리배출할 때 주의할 점」으로 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"헷갈리지 않기 · 더러운 것 씻어 버리기","correct":true},{"t":"음료수 캔 · 통조림 캔","mis":"K3-2-u1-X17"},{"t":"신문지 · 책","mis":"K3-2-u1-X17"},{"t":"빨리 버리기 · 한꺼번에 버리기","mis":"K3-2-u1-X07"}],"explanation":["『국어』 61쪽 표의 아래 칸이에요.","캔·종이는 「분리배출 방법」 칸에 들어가요.","주의할 점은 헷갈리지 않기와 씻어 버리기예요."],"asset":{"type":"speech","turns":[{"who":"지유","text":"선생님, 분리배출을 쉽게 알려 주세요!"},{"who":"전문가","text":"음료수 캔이나 통조림 캔은 캔으로, 신문지나 책은 종이로, 플라스틱 도시락통은 플라스틱으로 버려요."},{"who":"전문가","text":"그런데 헷갈리는 것도 있어요. 종이컵은 안쪽이 코팅되어 있어서 깨끗이 씻어 종이컵 전용으로 버려요."},{"who":"전문가","text":"페트병 뚜껑은 따로 떼어 플라스틱으로 버리고, 기름이 묻은 피자 상자는 쓰레기로 버려요."},{"who":"전문가","text":"스티로폼은 깨끗하면 재활용할 수 있지만, 음식물이 묻었으면 쓰레기로 버려요."},{"who":"전문가","text":"그리고 이것은 꼭 기억하세요. 더러운 것은 깨끗이 씻어 버려야 다시 쓸 수 있어요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#21','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C5',3,'mc','auto','「내가 만약 로지라면 바이올렛이 학교에 오지 않을 때 어떻게 했을까요?」는 어떤 질문인가요?',ARRAY['K3-2-u1-X26']::text[],false,'{"seq":21,"concept":"K3-2-u1-C5","difficulty":3,"kind":"mc","stem":"「내가 만약 로지라면 바이올렛이 학교에 오지 않을 때 어떻게 했을까요?」는 어떤 질문인가요?","options":[{"t":"내 생각이나 느낌을 말하는 감상 질문","correct":true},{"t":"글에서 바로 답을 찾는 내용 확인 질문","mis":"K3-2-u1-X26"},{"t":"글을 바탕으로 짐작하는 추론 질문","mis":"K3-2-u1-X26"},{"t":"낱말의 뜻을 묻는 질문","mis":"K3-2-u1-X26"}],"explanation":["지도서 95쪽 「내용 알기 질문의 유형」이에요.","「내가 만약 ~라면」은 내 생각을 묻는 질문이에요.","감상 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#22','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C10',3,'mc','auto','친구가 소개한 옛이야기를 바르게 고치려면 맨 앞으로 옮겨야 할 내용은 무엇인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":22,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"친구가 소개한 옛이야기를 바르게 고치려면 맨 앞으로 옮겨야 할 내용은 무엇인가요?","options":[{"t":"용왕님은 큰 병에 걸려서 시름시름 앓았다","correct":true},{"t":"토끼가 바닷속 용궁으로 구경을 갔다","mis":"K3-2-u1-X14"},{"t":"육지에 도착하자 토끼는 도망가 버렸다","mis":"K3-2-u1-X14"},{"t":"자라는 토끼를 등에 태워서 용궁으로 데려왔다","mis":"K3-2-u1-X14"}],"explanation":["지도서 105쪽 「옛이야기 소개에서 잘못된 점 찾기」예요.","용왕님이 병에 걸려야 토끼의 간이 필요해져요.","모든 일의 원인이 맨 앞에 와요."],"asset":{"type":"passage","lines":["옛날에 육지에 사는 토끼가 바닷속 용궁으로 구경을 갔어.","토끼는 자라의 등에 올라타고 간을 가지러 육지로 다시 올라갔어.","육지에 도착하자 토끼는 도망가 버렸지.","그런데 용왕님은 큰 병에 걸려서 시름시름 앓았어.","용왕님의 병을 낫게 하려면 토끼의 간이 필요했거든.","자라는 토끼를 등에 태워서 용궁으로 데려왔어."],"title":"친구가 소개한 옛이야기 — 지도서 104쪽 동기 유발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#23','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C7',4,'essay','teacher','「나도 최고가 되고 싶어요」를 읽고 떠오른 내 경험을 언제·무엇을·그때의 생각이나 느낌으로 쓰고, 그 경험을 바탕으로 로지에게 편지를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u1-C7","difficulty":4,"kind":"essay","stem":"「나도 최고가 되고 싶어요」를 읽고 떠오른 내 경험을 언제·무엇을·그때의 생각이나 느낌으로 쓰고, 그 경험을 바탕으로 로지에게 편지를 쓰세요.","answer_guide":{"answer":"예: 언제 — 2학년 받아쓰기 시험 때. 무엇을 — 짝이 백 점을 받을 것 같아 짝의 공책을 몰래 가렸다. 느낌 — 잠깐 좋았지만 마음이 무거웠다. 편지 — 로지야, 바이올렛의 새싹을 덮고 마음이 무거웠지? 나도 짝의 공책을 가린 뒤 그랬어. 그래도 너는 2주 동안 두 화분을 정성껏 돌보며 잘못을 바로잡았지. 그 모습이 정말 멋졌어.","scoring_points":["경험을 언제·무엇을·생각이나 느낌으로 썼는가","경험이 로지가 겪은 일이나 마음과 이어지는가","로지의 행동을 짚어 마음을 알아주는 편지를 썼는가"]},"explanation":["지도서 121쪽 평가 예시예요.","이야기 내용 이해 → 경험 떠올리기 → 인물에게 하고 싶은 말 차례예요.","편지를 쓴 뒤 친구와 돌려 읽어요."],"asset":{"type":"passage","lines":["[간추림] 로지는 책상에 푹 엎드렸어요. 새싹에게, 바이올렛에게도 미안했어요.","[간추림] 2주 동안 로지는 매일 아침 일찍 와서 화분 두 개를 정성껏 돌보았어요.","[간추림] 바이올렛 새싹을 덮은 흙을 털어 주고, 두 화분에 똑같이 물을 주었어요.","[간추림] 두 완두콩에 노래를 불러 주고, 햇빛이 잘 드는 자리에 두었어요.","“정말 훌륭하게 키웠구나. … 최고의 원예사야!”"],"title":"이야기 「나도 최고가 되고 싶어요」 ③ — 『국어』 45쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#24','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C10',4,'essay','teacher','「호랑이를 이긴 개미」를 보고 등장하는 동물, 기억에 남는 사건, 생각이나 느낌을 간단히 정리한 뒤, 중요한 내용을 간추려 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u1-C10","difficulty":4,"kind":"essay","stem":"「호랑이를 이긴 개미」를 보고 등장하는 동물, 기억에 남는 사건, 생각이나 느낌을 간단히 정리한 뒤, 중요한 내용을 간추려 쓰세요.","answer_guide":{"answer":"예: 등장하는 동물 — 호랑이, 개미, 개미 떼. 기억에 남는 사건 — 개미 떼가 호랑이 털 속으로 들어가 간지럽힌 일. 느낌 — 작은 개미들이 힘을 모은 것이 통쾌했다. 간추린 내용 — 숲속의 왕이라고 으스대던 호랑이가 자기를 무서워하지 않는 개미에게 화를 냈다가, 다음 날 개미 떼에게 혼이 난 뒤로 다른 동물들을 괴롭히지 않게 되었다.","scoring_points":["등장하는 동물·사건·느낌을 나누어 정리했는가","중요한 내용을 차례대로 간추렸는가","줄거리를 늘어놓지 않고 주요 내용 중심으로 썼는가"]},"explanation":["지도서 123쪽 평가 예시 1·2번이에요.","단순히 줄거리를 소개하는 것이 아니에요.","중요한 내용과 내 생각이나 느낌이 드러나야 해요."],"asset":{"type":"passage","lines":["[장면] 다음 날, 개미 떼가 나타나 호랑이 털 속으로 들어갔어요.","[장면] 호랑이는 가려움을 참지 못해 아무것도 할 수 없었어요.","[장면] 그 뒤로 호랑이는 다른 동물들 앞에서 큰소리치거나 괴롭히지 않았어요."],"title":"영상 「호랑이를 이긴 개미」 ② — 『국어』 53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_a#25','kor',3,2,'u1','','tb_g3_2_kor_u1_review_a','unit_review','K3-2-u1-C11',4,'essay','teacher','「우리 지역의 자랑거리」에서 자랑거리 하나를 골라 사는 곳과 자랑거리를 나누어 정리하고, 이 자랑거리를 소개하는 짧은 글로 다시 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u1-C11","difficulty":4,"kind":"essay","stem":"「우리 지역의 자랑거리」에서 자랑거리 하나를 골라 사는 곳과 자랑거리를 나누어 정리하고, 이 자랑거리를 소개하는 짧은 글로 다시 쓰세요.","answer_guide":{"answer":"예: 정리 — 울릉도 오징어 / 사는 곳: 경상북도 울릉군 울릉도 / 환경: 바닷물이 맑고 깨끗함 / 맛: 고소하고 씹을수록 약간의 단맛. 글 — 경상북도 울릉도의 자랑거리는 오징어입니다. 울릉도 주변은 바닷물이 맑고 깨끗해서 해산물이 많습니다. 울릉도 오징어는 말리면 고소하고 씹을수록 단맛이 나서 많은 사람이 좋아합니다.","scoring_points":["사는 곳과 자랑거리를 나누어 정리했는가","정리한 내용을 이어 짧은 글로 썼는가","들은 말을 그대로 옮기지 않고 내 말로 썼는가"]},"explanation":["『국어』 58쪽 정리를 글로 바꾸는 연습이에요.","간추리기는 내 말로 다시 짓는 일이에요.","읽는 사람이 알기 쉽게 차례대로 써요."],"asset":{"type":"speech","turns":[{"who":"기자","text":"여기는 ‘우리 지역의 자랑거리’를 찾는 현장입니다. 첫 번째 참가자는 홍천 옥수수입니다."},{"who":"홍천 옥수수","text":"제가 온 강원특별자치도 홍천군은 낮과 밤의 온도 차이가 크고 공기가 깨끗해요. 달고 쫀득쫀득한 맛을 자랑하지요."},{"who":"기자","text":"이어서 두 번째 참가자인 울릉도 오징어입니다."},{"who":"울릉도 오징어","text":"저는 경상북도 울릉군 울릉도에서 왔어요. 바닷물이 맑고 깨끗해 해산물이 많아요. 저를 말리면 고소하고 씹을수록 약간 단맛이 나요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#1','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C8',1,'ox','auto','「스스로 확인하기」 바구니에서 「모든 내용을 옮겨 적는다」에도 색칠해야 해요.',ARRAY['K3-2-u1-X12']::text[],false,'{"seq":1,"concept":"K3-2-u1-C8","difficulty":1,"kind":"ox","stem":"「스스로 확인하기」 바구니에서 「모든 내용을 옮겨 적는다」에도 색칠해야 해요.","answer":"X","reason_options":[{"t":"간추리기는 중요한 내용을 골라 다시 정리하는 것이기 때문에","correct":true},{"t":"빠짐없이 옮겨 적어야 중요한 내용이 남기 때문에","mis":"K3-2-u1-X12"}],"mis":"K3-2-u1-X12","explanation":["『국어』 63쪽 예시 답안에서 이 감만 색칠하지 않았어요.","간추리기는 줄이는 것이 아니라 다시 정리하는 것이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#2','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C1',1,'mc','auto','친구가 「지난봄 학교 화단에서 강낭콩 싹이 나오기를 오랫동안 기다렸는데, 작은 새싹을 보니 정말 기뻤어.」라고 했어요. 「그때 든 생각이나 느낌」은 무엇인가요?',ARRAY['K3-2-u1-X01']::text[],false,'{"seq":2,"concept":"K3-2-u1-C1","difficulty":1,"kind":"mc","stem":"친구가 「지난봄 학교 화단에서 강낭콩 싹이 나오기를 오랫동안 기다렸는데, 작은 새싹을 보니 정말 기뻤어.」라고 했어요. 「그때 든 생각이나 느낌」은 무엇인가요?","options":[{"t":"정말 기뻤어","correct":true},{"t":"지난봄","mis":"K3-2-u1-X01"},{"t":"학교 화단에서","mis":"K3-2-u1-X01"},{"t":"강낭콩 싹이 나오기를 기다렸는데","mis":"K3-2-u1-X01"}],"explanation":["지난봄은 언제, 학교 화단은 어디예요.","싹을 기다린 것은 무엇을 했는지예요.","마음은 「정말 기뻤어」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#3','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C3',1,'mc','auto','「벽 부수기」에서 마음의 벽을 없애는 약의 이름은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":1,"kind":"mc","stem":"「벽 부수기」에서 마음의 벽을 없애는 약의 이름은 무엇인가요?","options":[{"t":"입장 바꿔 생각해 보기","correct":true},{"t":"좋은 추억 생각해 보기","mis":"K3-2-u1-X07"},{"t":"화만 내 보기","mis":"K3-2-u1-X07"},{"t":"벽 더 쌓기","mis":"K3-2-u1-X07"}],"explanation":["시의 앞부분을 다시 읽어요.","「좋은 추억 생각해 보기」는 친구가 바꾸어 쓴 시의 약이에요.","원래 시의 약은 「입장 바꿔 생각해 보기」예요."],"asset":{"type":"passage","lines":["맘속에 벽이 있으면","[간추림] 말도 하고 싶지 않고, 보고 싶지도 않고, 화만 나고 답답하다.","[간추림] 그 벽은 「입장 바꿔 생각해 보기」라는 약을 마음에 풀어 마시면 없어진다."],"title":"시 「벽 부수기」(박희순) 앞부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#4','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C5',1,'mc','auto','바이올렛이 당분간 학교에 못 나온 까닭은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":4,"concept":"K3-2-u1-C5","difficulty":1,"kind":"mc","stem":"바이올렛이 당분간 학교에 못 나온 까닭은 무엇인가요?","options":[{"t":"수두에 걸려서","correct":true},{"t":"이사를 가서","mis":"K3-2-u1-X07"},{"t":"로지와 다투어서","mis":"K3-2-u1-X07"},{"t":"여행을 가서","mis":"K3-2-u1-X07"}],"explanation":["②의 마지막 줄을 읽어요.","선생님이 반 아이들에게 알려 주었어요.","수두에 걸렸어요."],"asset":{"type":"passage","lines":["[간추림] 이튿날 아침 일찍, 로지는 바이올렛의 새싹이 조금 더 큰 것을 보았어요.","로지는 마음속으로 생각했어요. ‘이러면 안 되는데.’","[간추림] 로지는 슬쩍 어깨 너머를 살핀 뒤 바이올렛의 새싹을 흙으로 덮었어요.","‘됐어. 이제 내 완두콩이 최고야.’","[간추림] 아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.","[간추림] 그날 바이올렛은 수두에 걸려 당분간 학교에 못 나온다고 했어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ② — 『국어』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#5','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C10',1,'sa','auto','「호랑이를 이긴 개미」에서 개미 떼는 호랑이의 어디로 들어갔나요?','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C10","difficulty":1,"kind":"sa","stem":"「호랑이를 이긴 개미」에서 개미 떼는 호랑이의 어디로 들어갔나요?","answer":["털 속","털속","털"],"explanation":["②의 첫 줄을 읽어요.","개미 떼가 호랑이 ○ ○으로 들어갔어요.","털 속이에요."],"asset":{"type":"passage","lines":["[장면] 다음 날, 개미 떼가 나타나 호랑이 털 속으로 들어갔어요.","[장면] 호랑이는 가려움을 참지 못해 아무것도 할 수 없었어요.","[장면] 그 뒤로 호랑이는 다른 동물들 앞에서 큰소리치거나 괴롭히지 않았어요."],"title":"영상 「호랑이를 이긴 개미」 ② — 『국어』 53쪽"},"mis":"K3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#6','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C11',1,'mc','auto','「우리 지역의 자랑거리」에서 홍천 옥수수의 맛은 어떻다고 했나요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":6,"concept":"K3-2-u1-C11","difficulty":1,"kind":"mc","stem":"「우리 지역의 자랑거리」에서 홍천 옥수수의 맛은 어떻다고 했나요?","options":[{"t":"달고 쫀득쫀득하다","correct":true},{"t":"고소하고 씹을수록 단맛이 난다","mis":"K3-2-u1-X17"},{"t":"달고 고소하며 단단하다","mis":"K3-2-u1-X17"},{"t":"질기고 변하지 않는다","mis":"K3-2-u1-X17"}],"explanation":["홍천 옥수수의 말을 다시 들어요.","「달고 쫀득쫀득한 맛을 자랑하지요.」라고 했어요.","다른 참가자의 자랑과 섞지 않아요."],"asset":{"type":"speech","turns":[{"who":"기자","text":"여기는 ‘우리 지역의 자랑거리’를 찾는 현장입니다. 첫 번째 참가자는 홍천 옥수수입니다."},{"who":"홍천 옥수수","text":"제가 온 강원특별자치도 홍천군은 낮과 밤의 온도 차이가 크고 공기가 깨끗해요. 달고 쫀득쫀득한 맛을 자랑하지요."},{"who":"기자","text":"이어서 두 번째 참가자인 울릉도 오징어입니다."},{"who":"울릉도 오징어","text":"저는 경상북도 울릉군 울릉도에서 왔어요. 바닷물이 맑고 깨끗해 해산물이 많아요. 저를 말리면 고소하고 씹을수록 약간 단맛이 나요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#7','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C13',1,'sa','auto','「닿아」를 소리 나는 대로 대괄호 없이 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u1-C13","difficulty":1,"kind":"sa","stem":"「닿아」를 소리 나는 대로 대괄호 없이 쓰세요.","answer":["다아"],"explanation":["받침 ㅎ 뒤에 「아」가 왔어요.","ㅎ 소리가 나지 않아요.","[다아]예요."],"mis":"K3-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#8','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C12',1,'mc','auto','「주인공이 겪은 일을 파악할 때 내 경험을 떠올려 볼 거야.」는 1단원에서 배운 두 갈래 가운데 무엇을 생활에서 실천하는 다짐인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":8,"concept":"K3-2-u1-C12","difficulty":1,"kind":"mc","stem":"「주인공이 겪은 일을 파악할 때 내 경험을 떠올려 볼 거야.」는 1단원에서 배운 두 갈래 가운데 무엇을 생활에서 실천하는 다짐인가요?","options":[{"t":"경험을 떠올리며 작품 감상하기","correct":true},{"t":"중요한 내용 간추리기","mis":"K3-2-u1-X17"},{"t":"받침 ㅎ 소리 알기","mis":"K3-2-u1-X17"},{"t":"글씨 바르게 쓰기","mis":"K3-2-u1-X17"}],"explanation":["1단원은 두 소단원으로 되어 있어요.","주인공이 겪은 일과 내 경험을 잇는 것은 소단원 1이에요.","경험을 떠올리며 작품 감상하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#9','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C2',2,'ox','auto','책이나 영상에서 본 일은 직접 겪은 일이 아니어서 작품과 관련 있는 경험으로 떠올릴 수 없어요.',ARRAY['K3-2-u1-X27']::text[],false,'{"seq":9,"concept":"K3-2-u1-C2","difficulty":2,"kind":"ox","stem":"책이나 영상에서 본 일은 직접 겪은 일이 아니어서 작품과 관련 있는 경험으로 떠올릴 수 없어요.","answer":"X","reason_options":[{"t":"관련 경험이 없으면 책이나 영상에서 보고 들은 간접 경험을 떠올려도 되기 때문에","correct":true},{"t":"경험은 내가 직접 겪은 일만 말하기 때문에","mis":"K3-2-u1-X27"}],"mis":"K3-2-u1-X27","explanation":["지도서 87쪽은 관련 경험이 없는 학생에게 책이나 영상으로 간접 경험을 주라고 해요.","「책에 나온 것들」의 예시 답안도 책에서 본 일이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#10','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C6',2,'mc','auto','로지가 책상에 푹 엎드린 까닭을 짐작할 때 근거로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":10,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"로지가 책상에 푹 엎드린 까닭을 짐작할 때 근거로 알맞은 것은 무엇인가요?","options":[{"t":"새싹에게, 바이올렛에게도 미안한 마음이 들었다는 부분","correct":true},{"t":"로지는 원래 잠이 많다는 생각","mis":"K3-2-u1-X04"},{"t":"지금 내가 졸리다는 기분","mis":"K3-2-u1-X04"},{"t":"제목에 「최고」가 들어 있다는 것","mis":"K3-2-u1-X04"}],"explanation":["근거는 이야기 안에서 찾아요.","글에 없는 것을 지어내지 않아요.","③에 미안한 마음이 나와요."],"asset":{"type":"passage","lines":["[간추림] 로지는 책상에 푹 엎드렸어요. 새싹에게, 바이올렛에게도 미안했어요.","[간추림] 2주 동안 로지는 매일 아침 일찍 와서 화분 두 개를 정성껏 돌보았어요.","[간추림] 바이올렛 새싹을 덮은 흙을 털어 주고, 두 화분에 똑같이 물을 주었어요.","[간추림] 두 완두콩에 노래를 불러 주고, 햇빛이 잘 드는 자리에 두었어요.","“정말 훌륭하게 키웠구나. … 최고의 원예사야!”"],"title":"이야기 「나도 최고가 되고 싶어요」 ③ — 『국어』 45쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#11','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C9',2,'sa','auto','질문 ② 「친구와 이야기 나눌 때 주의할 점은?」의 대답을 「자신의 마음을 ○○○○ 말해야 함.」으로 간추렸어요. ○○○○에 들어갈 말을 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"K3-2-u1-C9","difficulty":2,"kind":"sa","stem":"질문 ② 「친구와 이야기 나눌 때 주의할 점은?」의 대답을 「자신의 마음을 ○○○○ 말해야 함.」으로 간추렸어요. ○○○○에 들어갈 말을 쓰세요.","answer":["솔직하게"],"explanation":["질문 ②의 대답이에요.","마음을 있는 그대로 말하는 것이에요.","솔직하게예요."],"asset":{"type":"speech","turns":[{"who":"이슬기","text":"첫 번째 질문이에요. 친구들과 생각이 달라 문제가 생기면 어떻게 해결해요?"},{"who":"박민수","text":"친구와 계속 이야기하려고 노력해야 해요. 친구 이야기를 집중해서 들으면 생각을 더 알 수 있어요."},{"who":"이슬기","text":"두 번째 질문이에요. 친구와 이야기 나눌 때 주의할 점이 있을까요?"},{"who":"박민수","text":"자신의 마음을 솔직하게 말해야 해요. 그러면 친구가 내 마음을 오해하지 않아요."},{"who":"이슬기","text":"세 번째 질문이에요. 마음을 솔직하게 말하기 어려울 때는요?"},{"who":"박민수","text":"그럴 때에는 선생님께 도움을 요청할 수 있어요."}]},"mis":"K3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#12','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C10',2,'mc','auto','「호랑이를 이긴 개미」에서 「개미 떼가 나타나 호랑이 털 속으로 들어감.」의 결과로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X15']::text[],false,'{"seq":12,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"「호랑이를 이긴 개미」에서 「개미 떼가 나타나 호랑이 털 속으로 들어감.」의 결과로 알맞은 것은 무엇인가요?","options":[{"t":"호랑이는 가려움을 참지 못함.","correct":true},{"t":"호랑이가 개미를 잡음.","mis":"K3-2-u1-X15"},{"t":"호랑이가 더 으스댐.","mis":"K3-2-u1-X15"},{"t":"개미가 호랑이를 무서워함.","mis":"K3-2-u1-X15"}],"explanation":["『국어』 54쪽 (1)번이에요.","결과는 그 일 때문에 생긴 일이에요.","털 속의 개미 때문에 호랑이는 가려움을 참지 못했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#13','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C11',2,'mc','auto','『국어』 58쪽 표에서 전주 한지의 「특성」 칸에 들어갈 말은 무엇인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":13,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"『국어』 58쪽 표에서 전주 한지의 「특성」 칸에 들어갈 말은 무엇인가요?","options":[{"t":"질기고 오랜 시간이 흘러도 변하지 않음.","correct":true},{"t":"달고 고소하며 단단함.","mis":"K3-2-u1-X17"},{"t":"달고 쫀득쫀득함.","mis":"K3-2-u1-X17"},{"t":"닥나무와 깨끗한 물로 만듦.","mis":"K3-2-u1-X17"}],"explanation":["특성은 그것만의 좋은 점이에요.","닥나무와 깨끗한 물은 만드는 방법 칸이에요.","한지는 질기고 오래 변하지 않아요."],"asset":{"type":"speech","turns":[{"who":"전주 한지","text":"저는 전북특별자치도 전주시에서 온 한지예요. 우리나라 고유의 방법으로 만든 종이를 한지라고 해요."},{"who":"전주 한지","text":"닥나무와 깨끗한 물, 장인들의 노력으로 만들어져 질기고 오랜 시간이 흘러도 변하지 않아요."},{"who":"기자","text":"마지막 참가자로 충청남도 공주시에서 온 공주 알밤이 있었네요."},{"who":"공주 알밤","text":"저는 깨끗한 공기와 물, 흙으로 재배해 달고 고소해요. 단단해서 오래 보관할 수도 있어요."},{"who":"기자","text":"모두 지역의 자랑거리가 될 자격이 충분합니다. 여러분이 사는 곳에는 어떤 자랑거리가 있나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#14','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C14',2,'mc','auto','생각그물 보기의 「동물」 아래에 더 넣을 수 있는 낱말은 무엇인가요?',ARRAY['K3-2-u1-X22']::text[],false,'{"seq":14,"concept":"K3-2-u1-C14","difficulty":2,"kind":"mc","stem":"생각그물 보기의 「동물」 아래에 더 넣을 수 있는 낱말은 무엇인가요?","options":[{"t":"고양이","correct":true},{"t":"바지","mis":"K3-2-u1-X22"},{"t":"모자","mis":"K3-2-u1-X22"},{"t":"옷","mis":"K3-2-u1-X22"}],"explanation":["「동물」 아래에는 개·나비·고래가 있어요.","같은 갈래의 낱말을 찾아요.","고양이가 동물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#15','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C10',2,'mc','auto','「요리조리」를 넣어 만든 문장으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X08']::text[],false,'{"seq":15,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"「요리조리」를 넣어 만든 문장으로 알맞은 것은 무엇인가요?","options":[{"t":"강아지가 공을 요리조리 피하며 뛰어다녔다.","correct":true},{"t":"나는 요리조리 밥을 먹었다.","mis":"K3-2-u1-X08"},{"t":"하늘이 요리조리 파랗다.","mis":"K3-2-u1-X08"},{"t":"요리조리 할머니께 인사드렸다.","mis":"K3-2-u1-X08"}],"explanation":["지도서는 낱말을 알맞은 상황에 써 보며 익히게 해요.","요리조리는 일정한 방향 없이 이쪽저쪽으로예요.","피하며 뛰어다니는 모습에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#16','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C4',2,'mc','auto','친구가 「벽 부수기」에서 나와 다른 부분이 인상 깊었다고 했을 때 알맞은 태도는 무엇인가요?',ARRAY['K3-2-u1-X05']::text[],false,'{"seq":16,"concept":"K3-2-u1-C4","difficulty":2,"kind":"mc","stem":"친구가 「벽 부수기」에서 나와 다른 부분이 인상 깊었다고 했을 때 알맞은 태도는 무엇인가요?","options":[{"t":"왜 그 부분이 마음에 남았는지 까닭을 물어본다","correct":true},{"t":"내가 고른 부분이 맞다고 알려 준다","mis":"K3-2-u1-X05"},{"t":"내 생각을 지우고 친구 것을 따라 고른다","mis":"K3-2-u1-X05"},{"t":"인상 깊은 부분을 말하지 않는다","mis":"K3-2-u1-X05"}],"explanation":["인상 깊은 부분은 사람마다 달라요.","까닭을 물으면 내가 못 본 것이 보여요.","내 생각도 지우지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#17','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C7',3,'mc','auto','『국어』 48쪽 경험 나누기 놀이의 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X28']::text[],false,'{"seq":17,"concept":"K3-2-u1-C7","difficulty":3,"kind":"mc","stem":"『국어』 48쪽 경험 나누기 놀이의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"다른 모둠 친구와 쪽지 이야기를 하고 바꾸어 가진다 → 모둠별로 모아 기준에 따라 나눈다 → 칠판에 나누어 붙인다","correct":true},{"t":"칠판에 붙인다 → 모둠별로 나눈다 → 다른 모둠 친구와 바꾼다","mis":"K3-2-u1-X28"},{"t":"모둠별로 나눈다 → 칠판에 붙인다 → 다른 모둠 친구와 바꾼다","mis":"K3-2-u1-X28"},{"t":"다른 모둠 친구와 바꾼다 → 칠판에 붙인다 → 모둠별로 나눈다","mis":"K3-2-u1-X28"}],"explanation":["먼저 쪽지로 이야기를 나누고 바꾸어 가져요.","바꾼 쪽지를 모둠별로 모아 기준에 따라 나누어요.","마지막에 칠판에 나누어 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#18','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C10',3,'mc','auto','「호랑이를 이긴 개미」에서 세 번째로 일어난 일은 무엇인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":18,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"「호랑이를 이긴 개미」에서 세 번째로 일어난 일은 무엇인가요?","options":[{"t":"발톱을 잘 피하는 개미 때문에 호랑이가 더 화가 났다","correct":true},{"t":"호랑이와 개미가 다음 날 다시 만나기로 했다","mis":"K3-2-u1-X14"},{"t":"개미 떼가 호랑이 털 속으로 들어갔다","mis":"K3-2-u1-X14"},{"t":"호랑이와 개미가 만났다","mis":"K3-2-u1-X14"}],"explanation":["『국어』 55쪽 (2)번의 여섯 칸을 떠올려요.","만남 → 화남 → 더 화남 → 다시 만나기로 함 차례예요.","세 번째는 더 화가 난 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#19','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C8',3,'mc','auto','『국어활동』 8쪽 「내가 좋아하는 운동」을 짝과 나누어 읽을 때, 말하는 이가 강조하는 내용을 찾으려면 어떻게 해야 하나요?',ARRAY['K3-2-u1-X13','K3-2-u1-X12','K3-2-u1-X11']::text[],false,'{"seq":19,"concept":"K3-2-u1-C8","difficulty":3,"kind":"mc","stem":"『국어활동』 8쪽 「내가 좋아하는 운동」을 짝과 나누어 읽을 때, 말하는 이가 강조하는 내용을 찾으려면 어떻게 해야 하나요?","options":[{"t":"좋아하는 까닭을 말하는 부분을 찾아 짧게 적는다","correct":true},{"t":"짝의 목소리 크기를 적는다","mis":"K3-2-u1-X13"},{"t":"읽은 문장을 모두 베껴 쓴다","mis":"K3-2-u1-X12"},{"t":"운동 이름만 적는다","mis":"K3-2-u1-X11"}],"explanation":["말하는 이는 좋아하는 까닭을 여러 가지 말해요.","그 까닭이 강조하는 내용이에요.","까닭마다 짧게 나누어 적어요."],"asset":{"type":"speech","turns":[{"who":"윤찬","text":"나는 수영을 좋아해. 온몸을 골고루 움직여서 건강에 좋고, 물에서 하니까 다칠 일이 별로 없어. 시원해서 기분도 좋아."},{"who":"민이","text":"나는 축구가 좋아. 팀을 이루어서 하니까 협동심을 기르고 친해질 수 있어. 다리 근육이 튼튼해지고, 골을 넣으면 짜릿해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#20','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C12',3,'mc','auto','「분리배출을 잘하는 방법」에 따르면 페트병의 뚜껑은 어떻게 버려야 하나요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":20,"concept":"K3-2-u1-C12","difficulty":3,"kind":"mc","stem":"「분리배출을 잘하는 방법」에 따르면 페트병의 뚜껑은 어떻게 버려야 하나요?","options":[{"t":"따로 떼어 플라스틱으로 버린다","correct":true},{"t":"닫은 채 종이로 버린다","mis":"K3-2-u1-X07"},{"t":"쓰레기로 버린다","mis":"K3-2-u1-X07"},{"t":"캔으로 버린다","mis":"K3-2-u1-X07"}],"explanation":["헷갈리는 것들 가운데 하나예요.","뚜껑은 따로 떼어요.","플라스틱으로 버려요."],"asset":{"type":"speech","turns":[{"who":"지유","text":"선생님, 분리배출을 쉽게 알려 주세요!"},{"who":"전문가","text":"음료수 캔이나 통조림 캔은 캔으로, 신문지나 책은 종이로, 플라스틱 도시락통은 플라스틱으로 버려요."},{"who":"전문가","text":"그런데 헷갈리는 것도 있어요. 종이컵은 안쪽이 코팅되어 있어서 깨끗이 씻어 종이컵 전용으로 버려요."},{"who":"전문가","text":"페트병 뚜껑은 따로 떼어 플라스틱으로 버리고, 기름이 묻은 피자 상자는 쓰레기로 버려요."},{"who":"전문가","text":"스티로폼은 깨끗하면 재활용할 수 있지만, 음식물이 묻었으면 쓰레기로 버려요."},{"who":"전문가","text":"그리고 이것은 꼭 기억하세요. 더러운 것은 깨끗이 씻어 버려야 다시 쓸 수 있어요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#21','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C5',3,'mc','auto','「로지는 왜 바이올렛의 새싹을 흙으로 덮어 버렸을까요?」는 어떤 질문인가요?',ARRAY['K3-2-u1-X26']::text[],false,'{"seq":21,"concept":"K3-2-u1-C5","difficulty":3,"kind":"mc","stem":"「로지는 왜 바이올렛의 새싹을 흙으로 덮어 버렸을까요?」는 어떤 질문인가요?","options":[{"t":"글의 내용을 바탕으로 생각해 답을 찾는 추론 질문","correct":true},{"t":"글에서 바로 답을 찾는 내용 확인 질문","mis":"K3-2-u1-X26"},{"t":"내 생각이나 느낌을 말하는 감상 질문","mis":"K3-2-u1-X26"},{"t":"낱말의 뜻을 묻는 질문","mis":"K3-2-u1-X26"}],"explanation":["까닭이 글에 그대로 적혀 있지 않아요.","로지의 말과 행동을 바탕으로 짐작해요.","추론 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#22','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C10',3,'mc','auto','친구가 소개한 옛이야기에는 토끼가 왜 육지로 다시 올라갔는지가 빠져 있어요. 이것은 어떤 잘못인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X12']::text[],false,'{"seq":22,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"친구가 소개한 옛이야기에는 토끼가 왜 육지로 다시 올라갔는지가 빠져 있어요. 이것은 어떤 잘못인가요?","options":[{"t":"너무 간단히 줄여서 중요한 내용이 빠졌다","correct":true},{"t":"인물이 너무 많이 나왔다","mis":"K3-2-u1-X13"},{"t":"재미있는 말투를 쓰지 않았다","mis":"K3-2-u1-X13"},{"t":"한 글자도 빼지 않고 옮겼다","mis":"K3-2-u1-X12"}],"explanation":["지도서가 든 학생 반응 「너무 간단히 줄여서 중요한 내용이 빠져 내용을 모르겠습니다.」예요.","까닭이 빠지면 이야기가 이어지지 않아요.","간추릴 때도 원인은 남겨요."],"asset":{"type":"passage","lines":["옛날에 육지에 사는 토끼가 바닷속 용궁으로 구경을 갔어.","토끼는 자라의 등에 올라타고 간을 가지러 육지로 다시 올라갔어.","육지에 도착하자 토끼는 도망가 버렸지.","그런데 용왕님은 큰 병에 걸려서 시름시름 앓았어.","용왕님의 병을 낫게 하려면 토끼의 간이 필요했거든.","자라는 토끼를 등에 태워서 용궁으로 데려왔어."],"title":"친구가 소개한 옛이야기 — 지도서 104쪽 동기 유발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#23','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C7',4,'essay','teacher','「나도 최고가 되고 싶어요」에서 편지를 쓰고 싶은 인물을 바이올렛으로 정했어요. 바이올렛에게 편지를 쓰고 싶은 까닭과 함께, 내 경험을 담은 편지를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u1-C7","difficulty":4,"kind":"essay","stem":"「나도 최고가 되고 싶어요」에서 편지를 쓰고 싶은 인물을 바이올렛으로 정했어요. 바이올렛에게 편지를 쓰고 싶은 까닭과 함께, 내 경험을 담은 편지를 쓰세요.","answer_guide":{"answer":"예: 까닭 — 바이올렛은 늘 최고여서 부러웠지만, 로지에게 작은 목소리로 고맙다고 한 모습이 궁금했기 때문이다. 편지 — 바이올렛아, 수두에 걸려 많이 힘들었지? 돌아와서 로지에게 「고마워.」라고 말한 건 정말 잘한 일이야. 나도 반장 선거에서 이긴 뒤 도와준 친구에게 고맙다고 말했을 때 쑥스러웠지만 기뻤어.","scoring_points":["편지를 쓰고 싶은 까닭을 썼는가","바이올렛이 한 말이나 행동을 짚었는가","이어지는 내 경험을 담았는가"]},"explanation":["평가 예시 2번 (1)~(3)번 꼴이에요.","인물을 고르고 까닭을 먼저 써요.","인물의 상황과 비슷한 경험을 담아요."],"asset":{"type":"passage","lines":["[간추림] 바이올렛이 돌아와 “내 완두콩이 제일 크다! 만세!” 하고 외쳤어요.","[간추림] 선생님은 로지가 완두콩 두 개를 얼마나 열심히 키웠는지 말해 주었어요.","“고마워, 로지.”","[간추림] 바이올렛은 아주 작은 목소리로 말한 뒤, 큰 목소리로 덧붙였어요.","“그래도 내 완두콩이 제일 반짝반짝 빛난다!”","[간추림] 윌리스 선생님과 로지는 서로 바라보며 빙그레 웃었어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ④ — 『국어』 46쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#24','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C10',4,'essay','teacher','『국어활동』 9쪽 「갈대와 떡갈나무」의 내용을 원인과 결과가 드러나게 간추려 쓰고, 이 이야기가 주는 깨달음을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u1-C10","difficulty":4,"kind":"essay","stem":"『국어활동』 9쪽 「갈대와 떡갈나무」의 내용을 원인과 결과가 드러나게 간추려 쓰고, 이 이야기가 주는 깨달음을 쓰세요.","answer_guide":{"answer":"예: 떡갈나무는 자기 모습이 자랑스러워 잎이 무성해질수록 더욱 자신만만해졌다. 가을에 거센 바람이 불어도 흔들림 없이 버티려다가 결국 기둥이 부러졌고, 겨울에 누워서 후회했다. 갈대는 때로는 흔들릴 줄도 알아야 한다고 말해 주었다. 고집만 부리지 말고 상황에 맞게 굽힐 줄도 알아야 한다는 깨달음을 준다.","scoring_points":["계절(시간) 차례대로 간추렸는가","원인과 결과(버티려 함 → 부러짐)가 드러나는가","이야기가 주는 깨달음을 썼는가"]},"explanation":["시간의 흐름에 따라 간추려요.","왜 부러졌는지가 빠지면 안 돼요.","마지막에 깨달음을 덧붙여요."],"asset":{"type":"passage","lines":["봄 — 떡갈나무는 자기 모습이 자랑스러웠고, 갈대는 작은 바람에도 흔들렸다.","여름 — 떡갈나무 잎이 무성해져 더욱 자신만만해졌고, 갈대는 조용히 자리를 지켰다.","가을 — 바람이 거세도 떡갈나무는 버티려 했지만, 바람에 기둥이 부러졌다.","겨울 — 부러진 떡갈나무는 누워서 후회했고, 갈대는 때로는 흔들릴 줄도 알아야 한다고 말했다."],"title":"「갈대와 떡갈나무」를 계절에 따라 간추린 것 — 『국어활동』 9쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_b#25','kor',3,2,'u1','','tb_g3_2_kor_u1_review_b','unit_review','K3-2-u1-C12',4,'essay','teacher','「분리배출을 잘하는 방법」에서 헷갈리는 것으로 나온 물건 두 가지를 골라 어떻게 버리는지 간추리고, 그것을 바탕으로 내 실천 다짐을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u1-C12","difficulty":4,"kind":"essay","stem":"「분리배출을 잘하는 방법」에서 헷갈리는 것으로 나온 물건 두 가지를 골라 어떻게 버리는지 간추리고, 그것을 바탕으로 내 실천 다짐을 쓰세요.","answer_guide":{"answer":"예: 간추림 — 종이컵은 안쪽이 코팅되어 있어 씻어서 종이컵 전용으로 버린다. 기름 묻은 피자 상자는 재활용이 안 되어 쓰레기로 버린다. 다짐 — 나는 이번 주말부터 집에서 종이컵을 쓰면 헹궈서 따로 모으고, 피자 상자는 기름이 묻었는지 먼저 살피겠다.","scoring_points":["헷갈리는 물건 두 가지를 바르게 간추렸는가","간추린 내용을 근거로 다짐을 썼는가","언제·무엇을이 드러나게 내가 할 일을 썼는가"]},"explanation":["『국어』 61쪽 1·2번 활동이에요.","간추린 내용이 다짐의 근거예요.","「모두 잘하겠다」가 아니라 내가 할 일을 써요."],"asset":{"type":"speech","turns":[{"who":"지유","text":"선생님, 분리배출을 쉽게 알려 주세요!"},{"who":"전문가","text":"음료수 캔이나 통조림 캔은 캔으로, 신문지나 책은 종이로, 플라스틱 도시락통은 플라스틱으로 버려요."},{"who":"전문가","text":"그런데 헷갈리는 것도 있어요. 종이컵은 안쪽이 코팅되어 있어서 깨끗이 씻어 종이컵 전용으로 버려요."},{"who":"전문가","text":"페트병 뚜껑은 따로 떼어 플라스틱으로 버리고, 기름이 묻은 피자 상자는 쓰레기로 버려요."},{"who":"전문가","text":"스티로폼은 깨끗하면 재활용할 수 있지만, 음식물이 묻었으면 쓰레기로 버려요."},{"who":"전문가","text":"그리고 이것은 꼭 기억하세요. 더러운 것은 깨끗이 씻어 버려야 다시 쓸 수 있어요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#1','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C8',1,'mc','auto','『국어』 63쪽처럼 내용을 간추릴 때 알맞은 기호를 쓰면 좋은 점은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X10','K3-2-u1-X11']::text[],false,'{"seq":1,"concept":"K3-2-u1-C8","difficulty":1,"kind":"mc","stem":"『국어』 63쪽처럼 내용을 간추릴 때 알맞은 기호를 쓰면 좋은 점은 무엇인가요?","options":[{"t":"중요한 내용을 나누어 한눈에 정리할 수 있다","correct":true},{"t":"들은 말을 모두 적을 수 있다","mis":"K3-2-u1-X12"},{"t":"듣기 전에 내용을 다 알 수 있다","mis":"K3-2-u1-X10"},{"t":"표지어를 듣지 않아도 된다","mis":"K3-2-u1-X11"}],"explanation":["번호나 화살표 같은 기호를 써요.","내용이 나뉘어 한눈에 보여요.","들은 후에 정리할 때 특히 쓸모 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#2','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C1',1,'sa','auto','경험 쪽지 「친절한 친구」에 「미술 시간에 가위가 없어서 당황했어요. 그런데 지윤이가 가위를 빌려주어서 정말 고마웠어요.」라고 썼어요. 가위를 빌려준 친구의 이름을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u1-C1","difficulty":1,"kind":"sa","stem":"경험 쪽지 「친절한 친구」에 「미술 시간에 가위가 없어서 당황했어요. 그런데 지윤이가 가위를 빌려주어서 정말 고마웠어요.」라고 썼어요. 가위를 빌려준 친구의 이름을 쓰세요.","answer":["지윤","지윤이"],"explanation":["『국어』 48쪽 경험 쪽지 예시예요.","도움을 준 사람이 누구인지 찾아요.","지윤이에요."],"mis":"K3-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#3','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C3',1,'ox','auto','「벽 부수기」의 「‘피식’ 웃음소리」는 친구를 비웃는 소리예요.',ARRAY['K3-2-u1-X24']::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":1,"kind":"ox","stem":"「벽 부수기」의 「‘피식’ 웃음소리」는 친구를 비웃는 소리예요.","answer":"X","reason_options":[{"t":"그 애 마음을 알게 되어 마음이 풀리는 웃음, 곧 벽이 부서지는 소리이기 때문에","correct":true},{"t":"웃음소리는 언제나 남을 놀리는 소리이기 때문에","mis":"K3-2-u1-X24"}],"mis":"K3-2-u1-X24","explanation":["바로 뒤에 「그게 벽 부서지는 소리야.」라고 했어요.","친구 마음을 알게 되어 나온 웃음이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["[간추림] 그 애 마음을 알 것 같아지면","‘피식’ 웃음소리 나온다","그게 벽 부서지는 소리야."],"title":"시 「벽 부수기」 끝부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#4','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C5',1,'sa','auto','로지는 바이올렛이 없는 동안 몇 주 동안 두 화분을 돌보았나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u1-C5","difficulty":1,"kind":"sa","stem":"로지는 바이올렛이 없는 동안 몇 주 동안 두 화분을 돌보았나요? 숫자로 쓰세요.","answer":["2"],"explanation":["③의 둘째 줄을 읽어요.","「○주 동안 로지는 매일 아침 일찍」이에요.","2주예요."],"asset":{"type":"passage","lines":["[간추림] 로지는 책상에 푹 엎드렸어요. 새싹에게, 바이올렛에게도 미안했어요.","[간추림] 2주 동안 로지는 매일 아침 일찍 와서 화분 두 개를 정성껏 돌보았어요.","[간추림] 바이올렛 새싹을 덮은 흙을 털어 주고, 두 화분에 똑같이 물을 주었어요.","[간추림] 두 완두콩에 노래를 불러 주고, 햇빛이 잘 드는 자리에 두었어요.","“정말 훌륭하게 키웠구나. … 최고의 원예사야!”"],"title":"이야기 「나도 최고가 되고 싶어요」 ③ — 『국어』 45쪽"},"mis":"K3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#5','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C10',1,'mc','auto','호랑이와 개미는 언제 다시 만나기로 했나요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":5,"concept":"K3-2-u1-C10","difficulty":1,"kind":"mc","stem":"호랑이와 개미는 언제 다시 만나기로 했나요?","options":[{"t":"다음 날","correct":true},{"t":"일주일 뒤","mis":"K3-2-u1-X07"},{"t":"그날 밤","mis":"K3-2-u1-X07"},{"t":"다음 해 봄","mis":"K3-2-u1-X07"}],"explanation":["①의 마지막 줄을 읽어요.","둘은 다음 날 다시 만나기로 했어요.","그날 개미 떼가 나타났어요."],"asset":{"type":"passage","lines":["[장면] 어느 날 숲속에서 호랑이와 개미가 만났어요.","[장면] 호랑이는 숲속의 왕인 자기를 모두 무서워할 거라며 으스댔어요.","[장면] 개미는 힘만 세고 동물들을 괴롭히는 호랑이는 무섭지 않다고 했어요.","[장면] 화가 난 호랑이가 개미를 잡으려 했지만 개미는 요리조리 피했어요.","[장면] 발톱을 잘 피하는 개미 때문에 호랑이는 더 화가 났어요.","[장면] 둘은 다음 날 다시 만나기로 했어요."],"title":"영상 「호랑이를 이긴 개미」 ① — 『국어』 52~53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#6','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C11',1,'sa','auto','우리나라 고유의 방법으로 만든 종이를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u1-C11","difficulty":1,"kind":"sa","stem":"우리나라 고유의 방법으로 만든 종이를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["한지"],"explanation":["전주 한지의 말을 다시 들어요.","「우리나라 고유의 방법으로 만든 종이를 ○○라고 해요.」예요.","한지예요."],"asset":{"type":"speech","turns":[{"who":"전주 한지","text":"저는 전북특별자치도 전주시에서 온 한지예요. 우리나라 고유의 방법으로 만든 종이를 한지라고 해요."},{"who":"전주 한지","text":"닥나무와 깨끗한 물, 장인들의 노력으로 만들어져 질기고 오랜 시간이 흘러도 변하지 않아요."},{"who":"기자","text":"마지막 참가자로 충청남도 공주시에서 온 공주 알밤이 있었네요."},{"who":"공주 알밤","text":"저는 깨끗한 공기와 물, 흙으로 재배해 달고 고소해요. 단단해서 오래 보관할 수도 있어요."},{"who":"기자","text":"모두 지역의 자랑거리가 될 자격이 충분합니다. 여러분이 사는 곳에는 어떤 자랑거리가 있나요?"}]},"mis":"K3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#7','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C13',1,'ox','auto','「낳아」의 받침 ㅎ은 뒤에 모음으로 시작하는 「아」가 와서 소리 나지 않아요.',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":7,"concept":"K3-2-u1-C13","difficulty":1,"kind":"ox","stem":"「낳아」의 받침 ㅎ은 뒤에 모음으로 시작하는 「아」가 와서 소리 나지 않아요.","answer":"O","reason_options":[{"t":"받침 ㅎ 뒤에 모음으로 시작하는 말이 오면 ㅎ 소리가 나지 않기 때문에","correct":true},{"t":"받침 ㅎ은 어떤 말 앞에서도 늘 소리 나지 않기 때문에","mis":"K3-2-u1-X20"}],"mis":"K3-2-u1-X20","explanation":["『국어』 64쪽 날개의 설명이에요.","뒤에 자음이 오는 「낳고」는 [나코]로 ㅎ이 살아 있어요.","「낳아」는 [나아]이니 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#8','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C12',1,'ox','auto','「선생님 말씀을 간추리며 들어 볼 거야.」는 1단원에서 배운 것을 생활 속에서 실천하려는 다짐이에요.',ARRAY['K3-2-u1-X19']::text[],false,'{"seq":8,"concept":"K3-2-u1-C12","difficulty":1,"kind":"ox","stem":"「선생님 말씀을 간추리며 들어 볼 거야.」는 1단원에서 배운 것을 생활 속에서 실천하려는 다짐이에요.","answer":"O","reason_options":[{"t":"중요한 내용을 간추리며 듣는 방법을 생활에서 쓰려는 것이기 때문에","correct":true},{"t":"간추리며 듣기는 국어 시간에만 하는 것이기 때문에","mis":"K3-2-u1-X19"}],"mis":"K3-2-u1-X19","explanation":["『국어』 63쪽 예시 답안이에요.","소단원 2에서 배운 간추리며 듣기를 써요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#9','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C2',2,'mc','auto','「은행잎 편지」와 관련 있는 경험이 떠오르지 않을 때 할 수 있는 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X27','K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":9,"concept":"K3-2-u1-C2","difficulty":2,"kind":"mc","stem":"「은행잎 편지」와 관련 있는 경험이 떠오르지 않을 때 할 수 있는 일로 알맞은 것은 무엇인가요?","options":[{"t":"친구들이 말한 경험을 듣고 비슷한 경험을 떠올려 본다","correct":true},{"t":"그 시는 감상하지 않고 넘어간다","mis":"K3-2-u1-X27"},{"t":"은행잎이 나오는 아무 일이나 쓴다","mis":"K3-2-u1-X02"},{"t":"시와 상관없는 일을 지어 쓴다","mis":"K3-2-u1-X03"}],"explanation":["지도서는 다른 친구들의 발표를 듣고 비슷한 경험을 떠올리게 해요.","친구의 경험이 생각을 여는 디딤돌이 돼요.","겉에 나온 물건만 같은 일은 이어지는 경험이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#10','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C6',2,'ox','auto','로지가 두 완두콩에 노래를 불러 준 것은 완두콩이 잘 자라기를 바라는 마음을 보여 주는 행동이에요.',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":10,"concept":"K3-2-u1-C6","difficulty":2,"kind":"ox","stem":"로지가 두 완두콩에 노래를 불러 준 것은 완두콩이 잘 자라기를 바라는 마음을 보여 주는 행동이에요.","answer":"O","reason_options":[{"t":"두 화분을 정성껏 돌보며 노래를 불러 주고 햇빛 드는 곳에 둔 행동이 근거이기 때문에","correct":true},{"t":"로지는 원래 노래 부르기를 좋아한다고 글에 쓰여 있기 때문에","mis":"K3-2-u1-X04"}],"mis":"K3-2-u1-X04","explanation":["행동으로 마음을 짐작해요.","노래·물·햇빛이 모두 정성이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["[간추림] 로지는 책상에 푹 엎드렸어요. 새싹에게, 바이올렛에게도 미안했어요.","[간추림] 2주 동안 로지는 매일 아침 일찍 와서 화분 두 개를 정성껏 돌보았어요.","[간추림] 바이올렛 새싹을 덮은 흙을 털어 주고, 두 화분에 똑같이 물을 주었어요.","[간추림] 두 완두콩에 노래를 불러 주고, 햇빛이 잘 드는 자리에 두었어요.","“정말 훌륭하게 키웠구나. … 최고의 원예사야!”"],"title":"이야기 「나도 최고가 되고 싶어요」 ③ — 『국어』 45쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#11','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C9',2,'ox','auto','「생각이 달라도 대화로 풀어요」는 질문이 세 번 나오니, 질문과 대답을 세 짝으로 정리하면 간추린 것이 돼요.',ARRAY['K3-2-u1-X12']::text[],false,'{"seq":11,"concept":"K3-2-u1-C9","difficulty":2,"kind":"ox","stem":"「생각이 달라도 대화로 풀어요」는 질문이 세 번 나오니, 질문과 대답을 세 짝으로 정리하면 간추린 것이 돼요.","answer":"O","reason_options":[{"t":"묻고 답하는 대화는 질문과 대답의 짝이 곧 중요한 내용이기 때문에","correct":true},{"t":"간추리려면 인사말까지 모두 적어야 하기 때문에","mis":"K3-2-u1-X12"}],"mis":"K3-2-u1-X12","explanation":["『국어』 51쪽 2번 표가 세 칸이에요.","인사말은 남기지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#12','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C10',2,'match','auto','「갈대와 떡갈나무」에서 원인과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K3-2-u1-C10","difficulty":2,"kind":"match","stem":"「갈대와 떡갈나무」에서 원인과 결과를 알맞게 이으세요.","pairs":[{"l":"잎이 무성해짐","r":"떡갈나무가 더욱 자신만만해짐"},{"l":"거센 바람에도 흔들림 없이 버티려 함","r":"떡갈나무의 기둥이 부러짐"},{"l":"기둥이 부러져 누움","r":"떡갈나무가 후회함"}],"mis":"K3-2-u1-X15","explanation":["계절마다 일어난 일을 원인과 결과로 이어요.","버티기만 하다가 기둥이 부러졌어요.","부러진 뒤에 후회했어요."],"asset":{"type":"passage","lines":["봄 — 떡갈나무는 자기 모습이 자랑스러웠고, 갈대는 작은 바람에도 흔들렸다.","여름 — 떡갈나무 잎이 무성해져 더욱 자신만만해졌고, 갈대는 조용히 자리를 지켰다.","가을 — 바람이 거세도 떡갈나무는 버티려 했지만, 바람에 기둥이 부러졌다.","겨울 — 부러진 떡갈나무는 누워서 후회했고, 갈대는 때로는 흔들릴 줄도 알아야 한다고 말했다."],"title":"「갈대와 떡갈나무」를 계절에 따라 간추린 것 — 『국어활동』 9쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#13','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C11',2,'ox','auto','공주 알밤의 「깨끗한 공기와 물, 흙으로 재배함」은 「맛」 칸에 넣어야 해요.',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":13,"concept":"K3-2-u1-C11","difficulty":2,"kind":"ox","stem":"공주 알밤의 「깨끗한 공기와 물, 흙으로 재배함」은 「맛」 칸에 넣어야 해요.","answer":"X","reason_options":[{"t":"자란 곳의 모습이니 「환경」 칸에 넣어야 하기 때문에","correct":true},{"t":"알밤이 맛있는 것과 관련 있으면 모두 맛 칸이기 때문에","mis":"K3-2-u1-X17"}],"mis":"K3-2-u1-X17","explanation":["칸 이름에 맞게 넣어요.","공기·물·흙은 자란 환경이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#14','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C14',2,'ox','auto','생각그물에서 「동물」은 「개」, 「나비」, 「고래」를 모두 품는 낱말이에요.',ARRAY['K3-2-u1-X22']::text[],false,'{"seq":14,"concept":"K3-2-u1-C14","difficulty":2,"kind":"ox","stem":"생각그물에서 「동물」은 「개」, 「나비」, 「고래」를 모두 품는 낱말이에요.","answer":"O","reason_options":[{"t":"「동물」이 세 낱말을 묶는 더 큰 이름이기 때문에","correct":true},{"t":"「개」가 「동물」을 품는 더 큰 낱말이기 때문에","mis":"K3-2-u1-X22"}],"mis":"K3-2-u1-X22","explanation":["묶는 이름은 위에 있어요.","개·나비·고래는 동물 안에 들어가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#15','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C11',2,'mc','auto','「해산물」을 넣어 만든 문장으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X08']::text[],false,'{"seq":15,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"「해산물」을 넣어 만든 문장으로 알맞은 것은 무엇인가요?","options":[{"t":"바닷가 시장에는 전복, 미역 같은 해산물이 많다.","correct":true},{"t":"산에서 해산물을 캐었다.","mis":"K3-2-u1-X08"},{"t":"밭에 해산물을 심었다.","mis":"K3-2-u1-X08"},{"t":"해산물로 종이를 만들었다.","mis":"K3-2-u1-X08"}],"explanation":["해산물은 바다에서 나는 동물과 식물이에요.","산이나 밭에서는 나지 않아요.","바닷가 시장 문장이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#16','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C4',2,'ox','auto','친구들이 바꾸어 쓴 시를 읽을 때는 내가 쓴 시와 견주어 보고, 궁금한 점은 자유롭게 물어봐요.',ARRAY['K3-2-u1-X05']::text[],false,'{"seq":16,"concept":"K3-2-u1-C4","difficulty":2,"kind":"ox","stem":"친구들이 바꾸어 쓴 시를 읽을 때는 내가 쓴 시와 견주어 보고, 궁금한 점은 자유롭게 물어봐요.","answer":"O","reason_options":[{"t":"서로 견주고 물으면 감상의 폭이 넓어지기 때문에","correct":true},{"t":"바꾸어 쓴 시는 하나의 정답과 같아야 하기 때문에","mis":"K3-2-u1-X05"}],"mis":"K3-2-u1-X05","explanation":["지도서 93쪽의 안내예요.","내 작품과 견주며 감상해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#17','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C7',3,'mc','auto','인물에게 하고 싶은 말을 나눌 때 지도서가 안내한 「둘 가고 둘 남기」 방식으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X09']::text[],false,'{"seq":17,"concept":"K3-2-u1-C7","difficulty":3,"kind":"mc","stem":"인물에게 하고 싶은 말을 나눌 때 지도서가 안내한 「둘 가고 둘 남기」 방식으로 알맞은 것은 무엇인가요?","options":[{"t":"네 명 가운데 두 명은 자리에 남고, 두 명은 다른 모둠을 돌며 이야기를 나눈다","correct":true},{"t":"네 명이 모두 자리에 앉아 혼자 쓴다","mis":"K3-2-u1-X09"},{"t":"두 명만 말하고 두 명은 듣지 않는다","mis":"K3-2-u1-X09"},{"t":"선생님 한 분에게만 말한다","mis":"K3-2-u1-X09"}],"explanation":["지도서 97쪽의 방법이에요.","남은 사람과 돌아다니는 사람이 서로 이야기를 나누어요.","여러 친구의 말을 들으며 감상을 넓혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#18','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C10',3,'mc','auto','『국어활동』 「나는, 나는 될 터이다」의 사건 카드를 차례대로 놓을 때 맨 마지막 카드는 무엇인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":18,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"『국어활동』 「나는, 나는 될 터이다」의 사건 카드를 차례대로 놓을 때 맨 마지막 카드는 무엇인가요?","options":[{"t":"원태의 보고서를 보고 선생님이 흐뭇하게 웃었다","correct":true},{"t":"곰손 선생님이 직업 체험 숙제를 내 주었다","mis":"K3-2-u1-X14"},{"t":"마술사가 되고 싶은 성빈이에게 마술 교실을 소개해 주었다","mis":"K3-2-u1-X14"},{"t":"발표 날 아이들이 발표하고 보고서를 냈다","mis":"K3-2-u1-X14"}],"explanation":["지도서 116쪽 「사건과 관련 있는 경험 수집하기」 예시예요.","숙제 → 상담 → 발표·보고서 → 보고서 읽기 차례예요.","보고서를 낸 뒤에야 읽을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#19','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C8',3,'error','auto','세 친구가 「분리배출을 잘하는 방법」을 간추리며 듣는 과정을 말했어요. 단계에 맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X10','K3-2-u1-X11']::text[],false,'{"seq":19,"concept":"K3-2-u1-C8","difficulty":3,"kind":"error","stem":"세 친구가 「분리배출을 잘하는 방법」을 간추리며 듣는 과정을 말했어요. 단계에 맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「듣기 전에 들을 내용을 미리 다 받아 적어 둘 거야.」","correct":true,"mis_target":"K3-2-u1-X10"},{"t":"친구 가 — 「제목을 보니 쓰레기를 나누는 방법이 나올 것 같아.」","mis":"K3-2-u1-X10"},{"t":"친구 다 — 「‘이것은 꼭 기억하세요’ 뒤의 말은 꼭 적을 거야.」","mis":"K3-2-u1-X11"}],"explanation":["듣기 전에는 목적을 정하고 내용을 예상해요.","아직 듣지 않은 내용을 미리 적을 수는 없어요.","친구 나가 단계에 맞지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#20','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C12',3,'mc','auto','내 경험에 어울리는 이야기를 찾을 때 알맞은 기준은 무엇인가요?',ARRAY['K3-2-u1-X18']::text[],false,'{"seq":20,"concept":"K3-2-u1-C12","difficulty":3,"kind":"mc","stem":"내 경험에 어울리는 이야기를 찾을 때 알맞은 기준은 무엇인가요?","options":[{"t":"내가 겪은 일이나 그때의 마음과 이어지는 이야기","correct":true},{"t":"가장 유명한 이야기","mis":"K3-2-u1-X18"},{"t":"가장 긴 이야기","mis":"K3-2-u1-X18"},{"t":"친구가 가장 많이 고른 이야기","mis":"K3-2-u1-X18"}],"explanation":["『국어』 60~61쪽 활동이에요.","경험과 어울리는 이야기를 찾아요.","유명하거나 길다고 어울리는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#21','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C10',3,'mc','auto','「호랑이가 개미를 무시한 까닭은 무엇인가요?」처럼 영상에서 답을 찾을 수 있는 질문을 무엇이라고 하나요?',ARRAY['K3-2-u1-X26']::text[],false,'{"seq":21,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"「호랑이가 개미를 무시한 까닭은 무엇인가요?」처럼 영상에서 답을 찾을 수 있는 질문을 무엇이라고 하나요?","options":[{"t":"사실 질문","correct":true},{"t":"추론 질문","mis":"K3-2-u1-X26"},{"t":"감상 질문","mis":"K3-2-u1-X26"},{"t":"인사 질문","mis":"K3-2-u1-X26"}],"explanation":["『국어』 54쪽 「내용과 연결하기」예요.","영상에 답이 나오는 질문이에요.","사실 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#22','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C10',3,'mc','auto','간추린 사건으로 빙고 놀이를 할 때 빙고 칸에 사건을 쓰는 방법은 무엇인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X12']::text[],false,'{"seq":22,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"간추린 사건으로 빙고 놀이를 할 때 빙고 칸에 사건을 쓰는 방법은 무엇인가요?","options":[{"t":"빙고 칸의 수만큼 중요한 사건을 간추려 순서와 상관없이 쓴다","correct":true},{"t":"재미있는 사건 하나를 아홉 칸에 똑같이 쓴다","mis":"K3-2-u1-X13"},{"t":"이야기 문장을 그대로 아홉 줄 베껴 쓴다","mis":"K3-2-u1-X12"},{"t":"등장인물 이름만 쓴다","mis":"K3-2-u1-X13"}],"explanation":["지도서 117쪽 예시 2예요.","가로세로 세 칸이면 중요한 사건 아홉 개를 간추려요.","칸에는 순서와 상관없이 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#23','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C7',4,'essay','teacher','「나도 최고가 되고 싶어요」의 윌리스 선생님에게 편지를 쓰세요. 선생님이 로지를 바라보며 빙그레 웃은 까닭을 짐작해 넣고, 그와 이어지는 내 경험도 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u1-C7","difficulty":4,"kind":"essay","stem":"「나도 최고가 되고 싶어요」의 윌리스 선생님에게 편지를 쓰세요. 선생님이 로지를 바라보며 빙그레 웃은 까닭을 짐작해 넣고, 그와 이어지는 내 경험도 쓰세요.","answer_guide":{"answer":"예: 윌리스 선생님께. 선생님은 로지가 2주 동안 두 화분을 정성껏 돌본 것을 다 알고 계셨지요? 그래서 바이올렛이 자랑할 때 로지와 빙그레 웃으신 것 같아요. 저도 몰래 교실 화분에 물을 주었는데 선생님께서 아무 말 없이 웃어 주셔서 마음이 따뜻했어요.","scoring_points":["선생님이 웃은 까닭을 이야기에서 근거를 들어 짐작했는가","이어지는 내 경험을 썼는가","편지 꼴(받는 사람·인사)을 갖추었는가"]},"explanation":["지도서는 두 사람이 빙그레 웃은 까닭을 이야기해 보게 해요.","근거는 로지가 한 일에서 찾아요.","내 경험과 이어 써요."],"asset":{"type":"passage","lines":["[간추림] 바이올렛이 돌아와 “내 완두콩이 제일 크다! 만세!” 하고 외쳤어요.","[간추림] 선생님은 로지가 완두콩 두 개를 얼마나 열심히 키웠는지 말해 주었어요.","“고마워, 로지.”","[간추림] 바이올렛은 아주 작은 목소리로 말한 뒤, 큰 목소리로 덧붙였어요.","“그래도 내 완두콩이 제일 반짝반짝 빛난다!”","[간추림] 윌리스 선생님과 로지는 서로 바라보며 빙그레 웃었어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ④ — 『국어』 46쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#24','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C10',4,'essay','teacher','지도서 109쪽 활동지처럼 친구들에게 들려주고 싶은 이야기를 골라 등장인물의 이름과 특성, 일어난 일의 차례를 정리한 뒤, 중요한 내용을 간추려 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u1-C10","difficulty":4,"kind":"essay","stem":"지도서 109쪽 활동지처럼 친구들에게 들려주고 싶은 이야기를 골라 등장인물의 이름과 특성, 일어난 일의 차례를 정리한 뒤, 중요한 내용을 간추려 쓰세요.","answer_guide":{"answer":"예: 이야기 — 「흥부와 놀부」. 인물 — 흥부(마음씨가 착함), 놀부(욕심이 많음). 차례 — ① 놀부가 흥부를 내쫓음 ② 흥부가 제비 다리를 고쳐 줌 ③ 제비가 준 박씨에서 보물이 나옴 ④ 놀부가 일부러 제비 다리를 부러뜨림 ⑤ 놀부의 박에서 도깨비가 나와 놀부가 거지가 됨 ⑥ 흥부가 놀부를 도와줌. 간추린 내용 — 착한 흥부는 제비를 도와 복을 받았고, 욕심 많은 놀부는 벌을 받았지만 흥부의 도움을 받았다.","scoring_points":["등장인물의 이름과 특성을 썼는가","일어난 일을 차례대로 정리했는가","정리한 것을 바탕으로 짧게 간추려 썼는가"]},"explanation":["인물의 특성과 일어난 일의 차례를 먼저 정리해요.","그것을 바탕으로 간추리면 빠지는 것이 없어요.","간추린 내용을 친구들과 돌아가며 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_c#25','kor',3,2,'u1','','tb_g3_2_kor_u1_review_c','unit_review','K3-2-u1-C8',4,'essay','teacher','『국어』 63쪽 「생활 속으로」처럼 1단원에서 배운 것을 생활에서 실천할 계획을 쓰세요. 언제 무엇을 들을 때, 듣기 전·듣기 중·들은 후에 무엇을 할지 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u1-C8","difficulty":4,"kind":"essay","stem":"『국어』 63쪽 「생활 속으로」처럼 1단원에서 배운 것을 생활에서 실천할 계획을 쓰세요. 언제 무엇을 들을 때, 듣기 전·듣기 중·들은 후에 무엇을 할지 넣으세요.","answer_guide":{"answer":"예: 다음 주 현장 체험 학습 안내 방송을 들을 때 실천하겠다. 듣기 전에는 준비물과 모이는 시각을 알려고 듣는다고 정한다. 듣는 중에는 「첫째」, 「둘째」 뒤의 말을 번호를 붙여 짧게 적는다. 들은 후에는 적은 것을 기호로 정리하고 빠진 것은 친구와 견주어 본다.","scoring_points":["언제 무엇을 들을지 밝혔는가","듣기 전·듣기 중·들은 후에 할 일을 썼는가","실제로 할 수 있게 구체적으로 썼는가"]},"explanation":["「생활 속으로」의 예시 「안내 방송을 들을 때 중요한 내용을 간단히 정리해 볼 거야.」를 넓혀요.","세 단계마다 할 일을 넣어요.","내가 할 일로 구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#1','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C8',1,'mc','auto','들으면서 간추릴 때 귀 기울여 들어야 할 말은 무엇인가요?',ARRAY['K3-2-u1-X11','K3-2-u1-X13']::text[],false,'{"seq":1,"concept":"K3-2-u1-C8","difficulty":1,"kind":"mc","stem":"들으면서 간추릴 때 귀 기울여 들어야 할 말은 무엇인가요?","options":[{"t":"‘첫째’, ‘둘째’와 같은 말","correct":true},{"t":"‘음’, ‘어’와 같은 말","mis":"K3-2-u1-X11"},{"t":"가장 재미있는 말","mis":"K3-2-u1-X13"},{"t":"맨 처음 인사말","mis":"K3-2-u1-X11"}],"explanation":["『국어』 63쪽 「스스로 확인하기」의 감 하나예요.","그 말 뒤에 중요한 내용이 따라와요.","「음」, 「어」는 생각하며 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#2','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C1',1,'ox','auto','경험을 떠올릴 때 언제, 어디에서, 무엇을, 누구와 했는지 떠올리면 경험이 또렷해져요.',ARRAY['K3-2-u1-X01']::text[],false,'{"seq":2,"concept":"K3-2-u1-C1","difficulty":1,"kind":"ox","stem":"경험을 떠올릴 때 언제, 어디에서, 무엇을, 누구와 했는지 떠올리면 경험이 또렷해져요.","answer":"O","reason_options":[{"t":"경험을 남에게 말하듯 차례대로 떠올릴 수 있기 때문에","correct":true},{"t":"경험은 그때 느낌만 떠올리면 되기 때문에","mis":"K3-2-u1-X01"}],"mis":"K3-2-u1-X01","explanation":["『국어』 34쪽 날개의 말이에요.","본 것, 들은 것, 느낀 것도 함께 떠올려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#3','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C3',1,'mc','auto','「은행잎 편지」의 말하는 이로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X23','K3-2-u1-X07']::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":1,"kind":"mc","stem":"「은행잎 편지」의 말하는 이로 알맞은 것은 무엇인가요?","options":[{"t":"이사 간 친구를 그리워하는 「나」","correct":true},{"t":"시를 쓴 김홍관 시인","mis":"K3-2-u1-X23"},{"t":"은행나무","mis":"K3-2-u1-X23"},{"t":"이사 간 친구","mis":"K3-2-u1-X07"}],"explanation":["말하는 이는 시 속에서 이야기하는 사람 또는 사물이에요.","시를 쓴 사람과 말하는 이는 같지 않아요.","「나도 몰래 이사 간 친구」를 그리워하는 「나」예요."],"asset":{"type":"passage","lines":["방학 때 나도 몰래","이사 간 친구","[간추림] 2~3연 — 떨어진 은행잎에 이야기를 담아 그 친구에게 띄워 보낸다."],"title":"시 「은행잎 편지」(김홍관) 1연 — 『국어』 36쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#4','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C5',1,'ox','auto','바이올렛이 돌아왔을 때 바이올렛과 로지의 완두콩이 제일 컸어요.',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":4,"concept":"K3-2-u1-C5","difficulty":1,"kind":"ox","stem":"바이올렛이 돌아왔을 때 바이올렛과 로지의 완두콩이 제일 컸어요.","answer":"O","reason_options":[{"t":"로지가 두 화분을 정성껏 돌보아 둘 다 잘 자랐기 때문에","correct":true},{"t":"로지가 바이올렛의 새싹을 덮었으니 바이올렛 것은 자라지 않았기 때문에","mis":"K3-2-u1-X07"}],"mis":"K3-2-u1-X07","explanation":["로지는 덮었던 흙을 털어 주었어요.","두 화분에 똑같이 물을 주고 노래를 불러 주었어요.","그래서 둘 다 제일 컸으니 O예요."],"asset":{"type":"passage","lines":["[간추림] 바이올렛이 돌아와 “내 완두콩이 제일 크다! 만세!” 하고 외쳤어요.","[간추림] 선생님은 로지가 완두콩 두 개를 얼마나 열심히 키웠는지 말해 주었어요.","“고마워, 로지.”","[간추림] 바이올렛은 아주 작은 목소리로 말한 뒤, 큰 목소리로 덧붙였어요.","“그래도 내 완두콩이 제일 반짝반짝 빛난다!”","[간추림] 윌리스 선생님과 로지는 서로 바라보며 빙그레 웃었어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ④ — 『국어』 46쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#5','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C10',1,'ox','auto','호랑이는 자신이 숲속의 왕이니 다른 동물들이 자기를 무서워할 것이라고 생각했어요.',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":5,"concept":"K3-2-u1-C10","difficulty":1,"kind":"ox","stem":"호랑이는 자신이 숲속의 왕이니 다른 동물들이 자기를 무서워할 것이라고 생각했어요.","answer":"O","reason_options":[{"t":"숲속의 왕이라며 개미 앞에서 으스댔기 때문에","correct":true},{"t":"호랑이는 처음부터 개미를 무서워했기 때문에","mis":"K3-2-u1-X07"}],"mis":"K3-2-u1-X07","explanation":["호랑이의 특성을 떠올려요.","다른 동물들에게 으스대는 것을 좋아했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["[장면] 어느 날 숲속에서 호랑이와 개미가 만났어요.","[장면] 호랑이는 숲속의 왕인 자기를 모두 무서워할 거라며 으스댔어요.","[장면] 개미는 힘만 세고 동물들을 괴롭히는 호랑이는 무섭지 않다고 했어요.","[장면] 화가 난 호랑이가 개미를 잡으려 했지만 개미는 요리조리 피했어요.","[장면] 발톱을 잘 피하는 개미 때문에 호랑이는 더 화가 났어요.","[장면] 둘은 다음 날 다시 만나기로 했어요."],"title":"영상 「호랑이를 이긴 개미」 ① — 『국어』 52~53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#6','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C11',1,'ox','auto','「우리 지역의 자랑거리」에서 기자는 마지막에 참가자 가운데 한 명만 자랑거리가 될 수 있다고 했어요.',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":6,"concept":"K3-2-u1-C11","difficulty":1,"kind":"ox","stem":"「우리 지역의 자랑거리」에서 기자는 마지막에 참가자 가운데 한 명만 자랑거리가 될 수 있다고 했어요.","answer":"X","reason_options":[{"t":"모두 지역의 자랑거리가 될 자격이 충분하다고 했기 때문에","correct":true},{"t":"가장 크게 자랑한 참가자가 이기는 대회이기 때문에","mis":"K3-2-u1-X07"}],"mis":"K3-2-u1-X07","explanation":["기자의 마지막 말을 다시 들어요.","「모두 지역의 자랑거리가 될 자격이 충분합니다.」라고 했어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"전주 한지","text":"저는 전북특별자치도 전주시에서 온 한지예요. 우리나라 고유의 방법으로 만든 종이를 한지라고 해요."},{"who":"전주 한지","text":"닥나무와 깨끗한 물, 장인들의 노력으로 만들어져 질기고 오랜 시간이 흘러도 변하지 않아요."},{"who":"기자","text":"마지막 참가자로 충청남도 공주시에서 온 공주 알밤이 있었네요."},{"who":"공주 알밤","text":"저는 깨끗한 공기와 물, 흙으로 재배해 달고 고소해요. 단단해서 오래 보관할 수도 있어요."},{"who":"기자","text":"모두 지역의 자랑거리가 될 자격이 충분합니다. 여러분이 사는 곳에는 어떤 자랑거리가 있나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#7','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C13',1,'mc','auto','[조아]라고 소리 나는 말을 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u1-X21','K3-2-u1-X20']::text[],false,'{"seq":7,"concept":"K3-2-u1-C13","difficulty":1,"kind":"mc","stem":"[조아]라고 소리 나는 말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"좋아","correct":true},{"t":"조아","mis":"K3-2-u1-X21"},{"t":"좃아","mis":"K3-2-u1-X21"},{"t":"조하","mis":"K3-2-u1-X20"}],"explanation":["소리는 [조아]예요.","글자는 받침 ㅎ을 살려 써요.","「좋아」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#8','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C12',1,'mc','auto','「생활 속으로」 다짐을 남이 아니라 내가 할 일로 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u1-X19']::text[],false,'{"seq":8,"concept":"K3-2-u1-C12","difficulty":1,"kind":"mc","stem":"「생활 속으로」 다짐을 남이 아니라 내가 할 일로 바르게 쓴 것은 무엇인가요?","options":[{"t":"나는 내일 아침 방송 조회 때 중요한 내용을 공책에 적어 볼 거야.","correct":true},{"t":"친구들이 방송을 잘 들었으면 좋겠어.","mis":"K3-2-u1-X19"},{"t":"모두 조용히 해야 해.","mis":"K3-2-u1-X19"},{"t":"방송이 짧으면 좋겠어.","mis":"K3-2-u1-X19"}],"explanation":["다짐의 주인은 나예요.","언제(내일 아침 방송 조회 때)와 무엇을이 들어 있어요.","남에게 바라는 말은 다짐이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#9','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C2',2,'mc','auto','「책에 나온 것들」에서 「책 밖으로 나오지 못해 내 것이 될 수 없다」는 마음과 이어지는 경험은 무엇인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":9,"concept":"K3-2-u1-C2","difficulty":2,"kind":"mc","stem":"「책에 나온 것들」에서 「책 밖으로 나오지 못해 내 것이 될 수 없다」는 마음과 이어지는 경험은 무엇인가요?","options":[{"t":"영화에서 본 멋진 성에 가 보고 싶었지만 갈 수 없어 아쉬웠던 일","correct":true},{"t":"책을 빌리러 도서관에 간 일","mis":"K3-2-u1-X02"},{"t":"어제 산 연필","mis":"K3-2-u1-X03"},{"t":"망고를 맛있게 먹은 일","mis":"K3-2-u1-X02"}],"explanation":["갖고 싶은데 가질 수 없는 마음이에요.","영화에서 본 일도 떠올릴 수 있어요.","책·망고가 나온다고 이어지는 경험은 아니에요."],"asset":{"type":"passage","lines":["책에 나온 망고","나도 먹고 싶다.","[간추림] 멋있는 안경도 쓰고 싶지만, 책 밖으로 나오지 못해 내 것이 될 수 없다.","[간추림] 책 속에 있는 것들은 모든 사람들의 것이다."],"title":"시 「책에 나온 것들」(김옥애) — 『국어활동』 7쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#10','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C6',2,'mc','auto','「그래도 내 완두콩이 제일 반짝반짝 빛난다!」라는 말에서 짐작할 수 있는 바이올렛의 모습은 무엇인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":10,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"「그래도 내 완두콩이 제일 반짝반짝 빛난다!」라는 말에서 짐작할 수 있는 바이올렛의 모습은 무엇인가요?","options":[{"t":"고마우면서도 여전히 최고이고 싶은 마음이 남아 있다","correct":true},{"t":"로지를 미워한다","mis":"K3-2-u1-X04"},{"t":"완두콩을 버리려고 한다","mis":"K3-2-u1-X04"},{"t":"화분이 깨져서 슬프다","mis":"K3-2-u1-X04"}],"explanation":["바로 앞에 「고마워, 로지.」라고 했어요.","그다음 큰 목소리로 자기 완두콩을 자랑했어요.","두 마음이 함께 있어요."],"asset":{"type":"passage","lines":["[간추림] 바이올렛이 돌아와 “내 완두콩이 제일 크다! 만세!” 하고 외쳤어요.","[간추림] 선생님은 로지가 완두콩 두 개를 얼마나 열심히 키웠는지 말해 주었어요.","“고마워, 로지.”","[간추림] 바이올렛은 아주 작은 목소리로 말한 뒤, 큰 목소리로 덧붙였어요.","“그래도 내 완두콩이 제일 반짝반짝 빛난다!”","[간추림] 윌리스 선생님과 로지는 서로 바라보며 빙그레 웃었어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ④ — 『국어』 46쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#11','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C9',2,'mc','auto','질문 ① 「친구들과 문제가 생겼을 때 해결하는 방법은?」의 대답을 알맞게 간추린 것은 무엇인가요?',ARRAY['K3-2-u1-X17','K3-2-u1-X12']::text[],false,'{"seq":11,"concept":"K3-2-u1-C9","difficulty":2,"kind":"mc","stem":"질문 ① 「친구들과 문제가 생겼을 때 해결하는 방법은?」의 대답을 알맞게 간추린 것은 무엇인가요?","options":[{"t":"친구와 계속 이야기하려고 노력해야 함.","correct":true},{"t":"선생님께 도움을 요청함.","mis":"K3-2-u1-X17"},{"t":"자신의 마음을 솔직하게 말해야 함.","mis":"K3-2-u1-X17"},{"t":"네, 잘 왔어요. 궁금한 내용을 물어보면 대답해 줄게요.","mis":"K3-2-u1-X12"}],"explanation":["질문과 대답의 짝을 맞추어요.","선생님께 도움 요청은 질문 ③, 솔직하게는 질문 ②의 대답이에요.","인사말은 대답이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#12','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C10',2,'ox','auto','「나도 최고가 되고 싶어요」에서 「로지가 바이올렛의 새싹을 흙으로 덮음」의 결과로 「로지의 마음이 몹시 무거워짐」을 이을 수 있어요.',ARRAY['K3-2-u1-X15']::text[],false,'{"seq":12,"concept":"K3-2-u1-C10","difficulty":2,"kind":"ox","stem":"「나도 최고가 되고 싶어요」에서 「로지가 바이올렛의 새싹을 흙으로 덮음」의 결과로 「로지의 마음이 몹시 무거워짐」을 이을 수 있어요.","answer":"O","reason_options":[{"t":"떳떳하지 못한 일을 한 뒤 마음이 무거워졌기 때문에","correct":true},{"t":"로지의 마음은 수두 소식 때문에만 무거워졌기 때문에","mis":"K3-2-u1-X15"}],"mis":"K3-2-u1-X15","explanation":["원인과 결과는 이야기에도 있어요.","새싹을 덮은 뒤 잠깐 기분이 좋다가 마음이 무거워졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["[간추림] 이튿날 아침 일찍, 로지는 바이올렛의 새싹이 조금 더 큰 것을 보았어요.","로지는 마음속으로 생각했어요. ‘이러면 안 되는데.’","[간추림] 로지는 슬쩍 어깨 너머를 살핀 뒤 바이올렛의 새싹을 흙으로 덮었어요.","‘됐어. 이제 내 완두콩이 최고야.’","[간추림] 아주 잠깐 기분이 ‘최고’였지만, 곧 마음이 몹시 무거워졌어요.","[간추림] 그날 바이올렛은 수두에 걸려 당분간 학교에 못 나온다고 했어요."],"title":"이야기 「나도 최고가 되고 싶어요」 ② — 『국어』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#13','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C11',2,'match','auto','「우리 지역의 자랑거리」의 네 자랑거리와 그 맛이나 특성을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"K3-2-u1-C11","difficulty":2,"kind":"match","stem":"「우리 지역의 자랑거리」의 네 자랑거리와 그 맛이나 특성을 알맞게 이으세요.","pairs":[{"l":"홍천 옥수수","r":"달고 쫀득쫀득함"},{"l":"울릉도 오징어","r":"고소하고 씹을수록 단맛이 남"},{"l":"전주 한지","r":"질기고 오래 변하지 않음"},{"l":"공주 알밤","r":"단단해서 오래 보관할 수 있음"}],"mis":"K3-2-u1-X17","explanation":["참가자마다 자랑한 점이 달라요.","먹는 것은 맛, 종이는 특성을 말했어요.","섞이지 않게 나누어 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#14','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C14',2,'sa','auto','사회 교과서에서 「기온, 강수량, 바람」을 찾아 생각그물을 만들었어요. 이 낱말들을 묶는 이름으로 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"K3-2-u1-C14","difficulty":2,"kind":"sa","stem":"사회 교과서에서 「기온, 강수량, 바람」을 찾아 생각그물을 만들었어요. 이 낱말들을 묶는 이름으로 알맞은 두 글자 낱말을 쓰세요.","answer":["날씨","기후"],"explanation":["지도서는 사회·과학 교과서의 낱말로도 생각그물을 만들게 해요.","기온·강수량·바람은 하늘과 공기의 상태예요.","날씨로 묶을 수 있어요."],"mis":"K3-2-u1-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#15','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C5',2,'mc','auto','「모두가 바이올렛을 에워싸고 수두 이야기에 귀를 기울였어요.」에서 「에워싸고」와 뜻이 비슷한 말은 무엇인가요?',ARRAY['K3-2-u1-X08']::text[],false,'{"seq":15,"concept":"K3-2-u1-C5","difficulty":2,"kind":"mc","stem":"「모두가 바이올렛을 에워싸고 수두 이야기에 귀를 기울였어요.」에서 「에워싸고」와 뜻이 비슷한 말은 무엇인가요?","options":[{"t":"둘러싸고","correct":true},{"t":"밀어내고","mis":"K3-2-u1-X08"},{"t":"흘려보내고","mis":"K3-2-u1-X08"},{"t":"슬며시 피하고","mis":"K3-2-u1-X08"}],"explanation":["에워싸다는 둘레를 빙 둘러싸다예요.","모두가 바이올렛 둘레에 모였어요.","둘러싸고와 뜻이 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#16','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C4',2,'mc','auto','『국어』 41쪽 (2)번에서 친구들이 쓴 시를 바꾸어 읽고 기억에 남는 작품을 나누는 방법으로 지도서가 안내한 것은 무엇인가요?',ARRAY['K3-2-u1-X05']::text[],false,'{"seq":16,"concept":"K3-2-u1-C4","difficulty":2,"kind":"mc","stem":"『국어』 41쪽 (2)번에서 친구들이 쓴 시를 바꾸어 읽고 기억에 남는 작품을 나누는 방법으로 지도서가 안내한 것은 무엇인가요?","options":[{"t":"기억에 남는 작품에 붙임딱지를 붙이며 나눈다","correct":true},{"t":"가장 긴 시에만 붙임딱지를 붙인다","mis":"K3-2-u1-X05"},{"t":"맞춤법이 틀린 시를 골라낸다","mis":"K3-2-u1-X05"},{"t":"선생님이 고른 시 하나만 읽는다","mis":"K3-2-u1-X05"}],"explanation":["지도서 93쪽의 방법이에요.","마음에 남는 작품은 사람마다 달라요.","붙임딱지로 서로의 감상을 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#17','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C7',3,'mc','auto','「나도 최고가 되고 싶어요」의 인물에게 편지를 쓸 때 알맞은 내용은 무엇인가요?',ARRAY['K3-2-u1-X09','K3-2-u1-X03']::text[],false,'{"seq":17,"concept":"K3-2-u1-C7","difficulty":3,"kind":"mc","stem":"「나도 최고가 되고 싶어요」의 인물에게 편지를 쓸 때 알맞은 내용은 무엇인가요?","options":[{"t":"인물이 처했던 상황과 비슷한 내 경험을 담아 인물의 마음을 알아주는 말","correct":true},{"t":"인물이 잘못한 점만 꾸짖는 말","mis":"K3-2-u1-X09"},{"t":"이야기와 상관없는 내 자랑","mis":"K3-2-u1-X03"},{"t":"인물의 이름만 여러 번 쓴 말","mis":"K3-2-u1-X09"}],"explanation":["지도서 98쪽 「등장인물에게 편지 쓰기」예요.","비슷한 상황이나 비슷한 마음을 느낀 경험을 담아요.","꾸짖지 않고 마음을 알아주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#18','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C10',3,'mc','auto','「흥부 놀부 이야기」를 간추린 사건 가운데 「제비가 돌아와 흥부에게 박씨를 떨어뜨려 주었다」 바로 앞에 일어난 일은 무엇인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":18,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"「흥부 놀부 이야기」를 간추린 사건 가운데 「제비가 돌아와 흥부에게 박씨를 떨어뜨려 주었다」 바로 앞에 일어난 일은 무엇인가요?","options":[{"t":"흥부가 구렁이에게 공격당하던 제비의 부러진 다리를 치료해 주었다","correct":true},{"t":"흥부가 박씨를 심어 박을 타자 곡물과 보물이 나왔다","mis":"K3-2-u1-X14"},{"t":"놀부가 제비 다리를 부러뜨렸다","mis":"K3-2-u1-X14"},{"t":"흥부가 거지가 된 놀부를 도와주었다","mis":"K3-2-u1-X14"}],"explanation":["지도서 117쪽 빙고 놀이 예시예요.","제비가 은혜를 갚으려면 먼저 도움을 받아야 해요.","다리를 치료해 준 일이 바로 앞이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#19','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C8',3,'mc','auto','듣기 중에 「첫째」, 「둘째」, 「이것은」, 「따라서」 같은 말에 주의하는 까닭은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X11','K3-2-u1-X10']::text[],false,'{"seq":19,"concept":"K3-2-u1-C8","difficulty":3,"kind":"mc","stem":"듣기 중에 「첫째」, 「둘째」, 「이것은」, 「따라서」 같은 말에 주의하는 까닭은 무엇인가요?","options":[{"t":"그 말 뒤에 중요한 내용이 이어지기 때문에","correct":true},{"t":"그 말만 적으면 다 간추린 것이 되기 때문에","mis":"K3-2-u1-X12"},{"t":"말하는 사람의 버릇이기 때문에","mis":"K3-2-u1-X11"},{"t":"듣기 전에 미리 정한 말이기 때문에","mis":"K3-2-u1-X10"}],"explanation":["이런 말을 표지어라고 해요.","표지어 뒤에 중요한 내용이 따라와요.","표지어만 적는 것이 아니라 그 뒤의 내용을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#20','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C12',3,'mc','auto','우리 반에서 정한 활동 「이야기의 사건과 관련 있는 경험 수집하기」의 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X03','K3-2-u1-X13','K3-2-u1-X12']::text[],false,'{"seq":20,"concept":"K3-2-u1-C12","difficulty":3,"kind":"mc","stem":"우리 반에서 정한 활동 「이야기의 사건과 관련 있는 경험 수집하기」의 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"사건 카드를 친구에게 소개하고, 관련 있는 경험을 붙임쪽지에 적어 카드 뒷면에 붙인다","correct":true},{"t":"사건 카드를 혼자 읽고 바로 덮어 둔다","mis":"K3-2-u1-X03"},{"t":"사건 카드를 가장 많이 만든 사람이 이긴다","mis":"K3-2-u1-X13"},{"t":"이야기의 문장을 모두 카드에 베껴 쓴다","mis":"K3-2-u1-X12"}],"explanation":["지도서 116쪽 예시 1이에요.","중요한 사건마다 카드를 한 장씩 만들어요.","친구의 경험을 모아 사건마다 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#21','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C10',3,'mc','auto','추론 질문 「개미가 생각하는 ‘숲속의 왕’은 어떤 모습일까요?」에 알맞은 대답은 무엇인가요?',ARRAY['K3-2-u1-X26','K3-2-u1-X04']::text[],false,'{"seq":21,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"추론 질문 「개미가 생각하는 ‘숲속의 왕’은 어떤 모습일까요?」에 알맞은 대답은 무엇인가요?","options":[{"t":"약한 동물을 괴롭히지 않고 돕고 보살펴 주는 모습일 것 같습니다.","correct":true},{"t":"개미 떼가 털 속으로 들어갔습니다.","mis":"K3-2-u1-X26"},{"t":"호랑이처럼 힘세고 으스대는 모습입니다.","mis":"K3-2-u1-X04"},{"t":"숲속에 사는 모습입니다.","mis":"K3-2-u1-X26"}],"explanation":["추론 질문은 내용을 바탕으로 생각해야 해요.","개미는 호랑이가 동물들을 괴롭혀서 무섭지 않다고 했어요.","그러니 개미가 바라는 왕은 돕고 보살피는 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#22','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C10',3,'mc','auto','평가 자료 2에서 「호랑이를 이긴 개미」를 보며 내용을 간단히 정리하는 칸으로 알맞게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X12']::text[],false,'{"seq":22,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"평가 자료 2에서 「호랑이를 이긴 개미」를 보며 내용을 간단히 정리하는 칸으로 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"등장하는 동물 · 기억에 남는 사건 · 생각이나 느낌","correct":true},{"t":"영상 길이 · 화면 색깔 · 배경 음악","mis":"K3-2-u1-X13"},{"t":"호랑이 발톱 수 · 개미 수 · 숲 크기","mis":"K3-2-u1-X13"},{"t":"대사 전부 · 장면 전부 · 자막 전부","mis":"K3-2-u1-X12"}],"explanation":["지도서 123쪽 평가 예시 1번이에요.","누가 나오고 무슨 일이 있었는지 잡아요.","내 생각이나 느낌도 함께 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#23','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C7',4,'essay','teacher','『국어』 49쪽 (2)번처럼 친구가 「로지야, 새싹을 덮은 건 비겁했지만 스스로 반성해서 다행이야.」라고 말했어요. 이 말에서 기억에 남는 내용과 그 까닭을 쓰고, 나라면 로지에게 무슨 말을 할지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u1-C7","difficulty":4,"kind":"essay","stem":"『국어』 49쪽 (2)번처럼 친구가 「로지야, 새싹을 덮은 건 비겁했지만 스스로 반성해서 다행이야.」라고 말했어요. 이 말에서 기억에 남는 내용과 그 까닭을 쓰고, 나라면 로지에게 무슨 말을 할지 쓰세요.","answer_guide":{"answer":"예: 기억에 남는 내용 — 잘못은 잘못이라고 말하면서도 반성한 것을 알아준 점. 까닭 — 나도 동생에게 잘못했을 때 엄마가 그렇게 말해 주셔서 힘이 났기 때문이다. 나라면 — 「로지야, 바이올렛의 화분까지 돌본 너의 정성이 진짜 최고야.」라고 말하겠다.","scoring_points":["친구의 말에서 기억에 남는 내용을 썼는가","그 까닭을 내 경험과 이어 썼는가","로지의 행동을 짚어 하고 싶은 말을 썼는가"]},"explanation":["『국어』 49쪽 「자신과 관련짓기」 (2)번이에요.","친구의 말을 듣고 기억에 남는 까닭을 써요.","내 말도 인물의 행동을 짚어 해요."],"asset":{"type":"passage","lines":["[간추림] 로지는 책상에 푹 엎드렸어요. 새싹에게, 바이올렛에게도 미안했어요.","[간추림] 2주 동안 로지는 매일 아침 일찍 와서 화분 두 개를 정성껏 돌보았어요.","[간추림] 바이올렛 새싹을 덮은 흙을 털어 주고, 두 화분에 똑같이 물을 주었어요.","[간추림] 두 완두콩에 노래를 불러 주고, 햇빛이 잘 드는 자리에 두었어요.","“정말 훌륭하게 키웠구나. … 최고의 원예사야!”"],"title":"이야기 「나도 최고가 되고 싶어요」 ③ — 『국어』 45쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#24','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C10',4,'essay','teacher','친구가 소개한 옛이야기는 순서가 바뀌고 중요한 내용이 빠져 있어요. 일이 일어난 차례대로 바르게 고쳐 간추려 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u1-C10","difficulty":4,"kind":"essay","stem":"친구가 소개한 옛이야기는 순서가 바뀌고 중요한 내용이 빠져 있어요. 일이 일어난 차례대로 바르게 고쳐 간추려 쓰세요.","answer_guide":{"answer":"예: 바닷속 용왕님이 큰 병에 걸렸는데, 병을 낫게 하려면 토끼의 간이 필요했다. 자라가 육지로 가서 토끼를 등에 태워 용궁으로 데려왔다. 토끼는 간을 육지에 두고 왔다고 꾀를 내어 자라의 등을 타고 다시 육지로 올라갔고, 육지에 닿자마자 도망가 버렸다.","scoring_points":["원인(용왕님의 병)을 맨 앞에 두었는가","일이 일어난 차례대로 바르게 고쳤는가","빠졌던 까닭(토끼가 육지로 간 까닭)을 넣었는가"]},"explanation":["지도서는 일반화하기 단계에서 잘못 소개한 부분을 바르게 고쳐 보게 해요.","원인부터 차례대로 놓아요.","빠진 까닭을 채워 한 편의 이야기로 만들어요."],"asset":{"type":"passage","lines":["옛날에 육지에 사는 토끼가 바닷속 용궁으로 구경을 갔어.","토끼는 자라의 등에 올라타고 간을 가지러 육지로 다시 올라갔어.","육지에 도착하자 토끼는 도망가 버렸지.","그런데 용왕님은 큰 병에 걸려서 시름시름 앓았어.","용왕님의 병을 낫게 하려면 토끼의 간이 필요했거든.","자라는 토끼를 등에 태워서 용궁으로 데려왔어."],"title":"친구가 소개한 옛이야기 — 지도서 104쪽 동기 유발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u1_review_d#25','kor',3,2,'u1','','tb_g3_2_kor_u1_review_d','unit_review','K3-2-u1-C13',4,'essay','teacher','지도서가 더한 「쌓아」와 「넣어」를 넣어 문장을 하나씩 만들고, 두 말이 어떻게 소리 나는지와 쓸 때는 어떻게 쓰는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u1-C13","difficulty":4,"kind":"essay","stem":"지도서가 더한 「쌓아」와 「넣어」를 넣어 문장을 하나씩 만들고, 두 말이 어떻게 소리 나는지와 쓸 때는 어떻게 쓰는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「친구와 블록을 높이 쌓아 탑을 만들었다.」에서 「쌓아」는 [싸아], 「가방에 공책을 넣어 두었다.」에서 「넣어」는 [너어]로 소리 난다. 받침 ㅎ 뒤에 모음으로 시작하는 말이 와서 ㅎ 소리가 나지 않기 때문이다. 그래도 쓸 때는 받침 ㅎ을 살려 「쌓아」, 「넣어」로 쓴다.","scoring_points":["두 말을 넣어 문장을 만들었는가","[싸아]·[너어]로 소리 난다고 썼는가","쓸 때는 받침 ㅎ을 그대로 쓴다는 것과 까닭을 썼는가"]},"explanation":["지도서 118쪽의 추가 사례예요.","모음 앞 받침 ㅎ은 소리 나지 않아요.","글자는 그대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
